css:
@property --dbc-pipe-cov { syntax: '<percentage>'; inherits: true; initial-value: 0%; }

.dbc-pipe {
  /* re-theme with these four */
  --dbc-pipe-bg: oklch(0.205 0.012 65);
  --dbc-pipe-ink: oklch(0.955 0.012 85);
  --dbc-pipe-accent: oklch(0.81 0.15 72);
  --dbc-pipe-cool: oklch(0.64 0.05 245);
  /* derived */
  --dbc-pipe-panel: color-mix(in oklch, var(--dbc-pipe-bg) 94%, var(--dbc-pipe-ink));
  --dbc-pipe-raise: color-mix(in oklch, var(--dbc-pipe-bg) 86%, var(--dbc-pipe-ink));
  --dbc-pipe-line: color-mix(in oklch, var(--dbc-pipe-ink) 11%, transparent);
  --dbc-pipe-soft: color-mix(in oklch, var(--dbc-pipe-ink) 6%, transparent);
  --dbc-pipe-mute: color-mix(in oklch, var(--dbc-pipe-ink) 64%, var(--dbc-pipe-bg));
  --dbc-pipe-faint: color-mix(in oklch, var(--dbc-pipe-ink) 42%, var(--dbc-pipe-bg));
  --dbc-pipe-warn: oklch(0.72 0.16 32);
  --dbc-pipe-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbc-pipe-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbc-pipe-out: cubic-bezier(.16, 1, .3, 1);
  --dbc-pipe-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  width: 100%;
  height: var(--dbc-pipe-h, 680px);
  container-type: inline-size;
  container-name: dbc-pipe;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background:
    radial-gradient(90% 55% at 0% 0%, color-mix(in oklch, var(--dbc-pipe-accent) 7%, transparent), transparent 70%),
    var(--dbc-pipe-bg);
  color: var(--dbc-pipe-ink);
  font: 13px/1.45 var(--dbc-pipe-sans);
  accent-color: var(--dbc-pipe-accent);
  color-scheme: dark;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, dl, dd, ul, ol, figure, table, fieldset) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(input, select, textarea) { font: inherit; color: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dbc-pipe-accent); outline-offset: 2px; border-radius: 6px; }
  & :where(.dbc-pipe__scroll) { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbc-pipe-ink) 22%, transparent) transparent; }
  & .dbc-pipe__num { font-variant-numeric: tabular-nums; }
  & .dbc-pipe__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

}
.dbc-pipe__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbc-pipe__shell { height: 100%; display: grid; grid-template-columns: 204px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------------------------------------------------------------- sidebar */
.dbc-pipe__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 18px 12px 14px;
  border-right: 1px solid var(--dbc-pipe-line);
  background: color-mix(in oklch, var(--dbc-pipe-bg) 82%, black);
}
.dbc-pipe__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 9px; background: var(--dbc-pipe-accent); fill: none; stroke: var(--dbc-pipe-bg); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbc-pipe-mute); }
}
.dbc-pipe__tabs {
  display: grid; gap: 2px;
  & [role=tab] {
    position: relative; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px;
    color: var(--dbc-pipe-mute); font-weight: 560; transition: background-color .2s, color .2s;
    &:hover { background: var(--dbc-pipe-soft); color: var(--dbc-pipe-ink); }
    &[aria-selected=true] { background: var(--dbc-pipe-raise); color: var(--dbc-pipe-ink); }
    &[aria-selected=true] .dbc-pipe__ic { color: var(--dbc-pipe-accent); }
    &[aria-selected=true]::before { content: ""; position: absolute; left: -12px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbc-pipe-accent); }
  }
}
.dbc-pipe__badge { margin-left: auto; font: 600 10.5px/1 var(--dbc-pipe-mono); font-style: normal; padding: 3px 6px; border-radius: 99px; background: var(--dbc-pipe-soft); color: var(--dbc-pipe-mute); }
.dbc-pipe__model { margin-top: auto; padding: 14px 8px 0; border-top: 1px solid var(--dbc-pipe-line); display: grid; gap: 8px; }
.dbc-pipe__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-pipe-faint); }
.dbc-pipe__plist {
  display: grid; gap: 3px; font-size: 12px;
  & li { display: flex; justify-content: space-between; gap: 8px; color: var(--dbc-pipe-mute); }
  & b { font: 600 11.5px var(--dbc-pipe-mono); color: var(--dbc-pipe-ink); font-variant-numeric: tabular-nums; }
  & s { color: var(--dbc-pipe-faint); margin-right: 5px; font-weight: 400; }
  & li.is-mod b { color: var(--dbc-pipe-accent); }
}
.dbc-pipe__hint { font-size: 11.5px; color: var(--dbc-pipe-faint); text-wrap: pretty; }
.dbc-pipe__reset {
  justify-self: start; padding: 6px 10px; border-radius: 8px; font-size: 12px; font-weight: 600;
  background: var(--dbc-pipe-soft); box-shadow: inset 0 0 0 1px var(--dbc-pipe-line); transition: background-color .2s, opacity .2s;
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--dbc-pipe-accent) 22%, transparent); }
  &:disabled { opacity: .4; cursor: default; }
}

/* ---------------------------------------------------------------- main */
.dbc-pipe__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 16px 18px 16px; }
.dbc-pipe__head { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px; }
.dbc-pipe__title h2 { font-size: clamp(19px, 2.2cqi, 26px); font-weight: 760; letter-spacing: -.035em; line-height: 1.08; text-wrap: balance; }
.dbc-pipe__eyebrow { font: 600 10.5px/1.2 var(--dbc-pipe-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-pipe-accent); margin-bottom: 5px; }
.dbc-pipe__filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.dbc-pipe__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dbc-pipe-panel); box-shadow: inset 0 0 0 1px var(--dbc-pipe-line);
  & [role=radio] {
    padding: 5px 10px; border-radius: 7px; font-size: 12px; font-weight: 580; color: var(--dbc-pipe-mute); white-space: nowrap;
    transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover { color: var(--dbc-pipe-ink); }
    &[aria-checked=true] { background: var(--dbc-pipe-raise); color: var(--dbc-pipe-ink); box-shadow: inset 0 1px 0 color-mix(in oklch, var(--dbc-pipe-ink) 9%, transparent), 0 4px 10px -6px black; }
  }
}
.dbc-pipe__select {
  position: relative; display: inline-flex; align-items: center;
  & select { appearance: none; padding: 6px 30px 6px 11px; border-radius: 10px; background: var(--dbc-pipe-panel); border: 1px solid var(--dbc-pipe-line); font-size: 12px; font-weight: 580; cursor: pointer; }
  & select:hover { border-color: color-mix(in oklch, var(--dbc-pipe-ink) 24%, transparent); }
  & option { background: var(--dbc-pipe-bg); color: var(--dbc-pipe-ink); }
  & svg { position: absolute; right: 9px; width: 14px; height: 14px; pointer-events: none; fill: none; stroke: var(--dbc-pipe-mute); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}

.dbc-pipe__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div { min-width: 0; display: grid; gap: 1px; padding: 11px 14px 12px; border-radius: 12px; background: var(--dbc-pipe-panel); box-shadow: inset 0 0 0 1px var(--dbc-pipe-line); }
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-pipe-mute); }
  & dd { font-size: clamp(18px, 2.1cqi, 25px); font-weight: 700; letter-spacing: -.03em; line-height: 1.2; }
  & small { font-size: 11.5px; color: var(--dbc-pipe-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .is-key { background: linear-gradient(160deg, color-mix(in oklch, var(--dbc-pipe-accent) 16%, var(--dbc-pipe-panel)), var(--dbc-pipe-panel) 70%); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-pipe-accent) 30%, transparent); }
  & .is-key dd { color: var(--dbc-pipe-accent); }
}

.dbc-pipe__views { min-height: 0; position: relative; }
.dbc-pipe__view { height: 100%; min-height: 0; display: grid; gap: 12px; }
.dbc-pipe__view[hidden] { display: none; }
.dbc-pipe__v-stages, .dbc-pipe__v-vel { grid-template-columns: minmax(0, 1fr) 286px; }
.dbc-pipe__panel { min-width: 0; min-height: 0; border-radius: 14px; background: var(--dbc-pipe-panel); box-shadow: inset 0 0 0 1px var(--dbc-pipe-line); }
.dbc-pipe__ph {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 12px; padding: 0 4px 6px;
  & h3 { font-size: 12.5px; font-weight: 680; letter-spacing: -.005em; }
}
.dbc-pipe__legend {
  display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--dbc-pipe-mute);
  & i { width: 12px; height: 9px; border-radius: 2px; margin-left: 6px; }
  & .is-solid { background: linear-gradient(90deg in oklab, var(--dbc-pipe-cool), var(--dbc-pipe-accent)); }
  & .is-hatch { background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--dbc-pipe-accent) 60%, transparent) 0 1.5px, transparent 1.5px 4px); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-pipe-accent) 40%, transparent); }
}
.dbc-pipe__chartp, .dbc-pipe__funnelp { display: grid; grid-template-rows: auto minmax(0, 1fr); padding: 12px 12px 4px; margin: 0; }
.dbc-pipe__chart, .dbc-pipe__funnel { position: relative; min-height: 0; touch-action: pan-y; }
.dbc-pipe__chart svg, .dbc-pipe__funnel svg { position: absolute; inset: 0; font-family: var(--dbc-pipe-sans); }

/* chart marks */
.dbc-pipe__gl { stroke: var(--dbc-pipe-line); }
.dbc-pipe__base { stroke: color-mix(in oklch, var(--dbc-pipe-ink) 30%, transparent); }
.dbc-pipe__ax { fill: var(--dbc-pipe-faint); font: 10.5px var(--dbc-pipe-mono); font-variant-numeric: tabular-nums; }
.dbc-pipe__col { --c: color-mix(in oklab, var(--dbc-pipe-accent) calc(var(--i) * 20%), var(--dbc-pipe-cool)); }
.dbc-pipe__hbg { fill: color-mix(in oklch, var(--c) 9%, transparent); }
.dbc-pipe__hatch { stroke: color-mix(in oklch, var(--c) 55%, transparent); stroke-width: 1.3; }
.dbc-pipe__ghost rect { stroke: color-mix(in oklch, var(--c) 45%, transparent); stroke-width: 1; cursor: pointer; transition: opacity .25s, stroke .15s; }
.dbc-pipe__ghost rect:hover { stroke: var(--dbc-pipe-ink); }
.dbc-pipe__solid rect { fill: var(--c); pointer-events: none; transition: opacity .25s; }
.dbc-pipe__chart:has(.is-sel) {
  & .dbc-pipe__ghost rect:not(.is-sel), & .dbc-pipe__solid rect:not(.is-sel) { opacity: .38; }
  & .dbc-pipe__ghost rect.is-sel { stroke: var(--dbc-pipe-ink); stroke-width: 2; }
}
.dbc-pipe__tot { fill: var(--dbc-pipe-ink); font-size: 12px; font-weight: 680; text-anchor: middle; font-variant-numeric: tabular-nums; }
.dbc-pipe__xl { fill: var(--dbc-pipe-ink); font-size: 12px; font-weight: 620; text-anchor: middle; }
.dbc-pipe__xw { fill: var(--dbc-pipe-faint); font: 10.5px var(--dbc-pipe-mono); text-anchor: middle; font-variant-numeric: tabular-nums; & tspan { fill: var(--c); font-weight: 650; } }
.dbc-pipe__knob {
  cursor: ns-resize; outline: none;
  & line { stroke: var(--dbc-pipe-ink); stroke-width: 1.5; stroke-dasharray: 2 3; }
  & rect { fill: var(--dbc-pipe-bg); stroke: var(--c); stroke-width: 1.5; transition: fill .15s, stroke-width .15s; }
  & text { fill: var(--dbc-pipe-ink); font: 650 11px var(--dbc-pipe-mono); text-anchor: middle; dominant-baseline: central; font-variant-numeric: tabular-nums; pointer-events: none; }
  &:hover rect { stroke-width: 2.5; }
  &:focus-visible rect { stroke: var(--dbc-pipe-ink); stroke-width: 2.5; }
  &.is-drag rect { fill: var(--c); }
  &.is-drag text { fill: var(--dbc-pipe-bg); }
}
.dbc-pipe__chart svg.is-enter .dbc-pipe__col { animation: dbc-pipe-rise 1.05s var(--dbc-pipe-out) backwards; animation-delay: calc(var(--i) * 75ms + 60ms); }
.dbc-pipe__chart svg.is-update, .dbc-pipe__funnel svg.is-update { animation: dbc-pipe-fade .28s var(--dbc-pipe-out); }
@keyframes dbc-pipe-rise { from { clip-path: inset(100% 0 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbc-pipe-fade { from { opacity: .35; } }

/* aside */
.dbc-pipe__aside { padding: 14px; display: flex; flex-direction: column; gap: 12px; }
.dbc-pipe__cov { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 14px; align-items: center; }
.dbc-pipe__ring {
  --dbc-pipe-cov: 0%;
  width: 96px; aspect-ratio: 1; border-radius: 50%; display: grid; place-content: center; text-align: center;
  background: radial-gradient(closest-side, var(--dbc-pipe-panel) 80%, transparent 81% 100%), conic-gradient(from -90deg, var(--dbc-pipe-accent) var(--dbc-pipe-cov), var(--dbc-pipe-line) 0);
  transition: --dbc-pipe-cov 1.1s var(--dbc-pipe-spring);
  & b { font-size: 21px; font-weight: 720; letter-spacing: -.03em; line-height: 1; }
  & small { font-size: 10.5px; color: var(--dbc-pipe-mute); letter-spacing: .04em; }
}
.dbc-pipe__covbars {
  display: grid; gap: 8px; font-size: 11.5px;
  & div { display: grid; grid-template-columns: 1fr auto; gap: 3px 8px; }
  & span { color: var(--dbc-pipe-mute); }
  & b { font-weight: 650; font-variant-numeric: tabular-nums; }
  & i { grid-column: 1 / -1; height: 5px; border-radius: 3px; background: var(--dbc-pipe-soft); overflow: hidden; }
  & i::before { content: ""; display: block; height: 100%; width: var(--w); border-radius: inherit; background: var(--bar, var(--dbc-pipe-mute)); transition: width .7s var(--dbc-pipe-spring); }
}
.dbc-pipe__covnote { font-size: 12px; color: var(--dbc-pipe-mute); text-wrap: pretty; & b { color: var(--dbc-pipe-ink); font-weight: 650; } }
.dbc-pipe__h3 { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-pipe-faint); }
.dbc-pipe__top {
  display: grid; gap: 4px; counter-reset: dbc-pipe-n;
  & li { counter-increment: dbc-pipe-n; transition: opacity .3s; @starting-style { opacity: 0; } }
  & button {
    width: 100%; display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; grid-template-areas: "n a v" "n s v" "n bar bar"; gap: 1px 8px; padding: 7px 8px; border-radius: 9px;
    transition: background-color .2s;
    &::before { content: counter(dbc-pipe-n); grid-area: n; font: 600 11px var(--dbc-pipe-mono); color: var(--dbc-pipe-faint); padding-top: 1px; }
    &:hover { background: var(--dbc-pipe-soft); }
    &[aria-pressed=true] { background: color-mix(in oklch, var(--dbc-pipe-accent) 14%, transparent); }
  }
  & .a { grid-area: a; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .s { grid-area: s; font-size: 11.5px; color: var(--dbc-pipe-mute); }
  & .v { grid-area: v; align-self: center; font: 600 12px var(--dbc-pipe-mono); font-variant-numeric: tabular-nums; }
  & .bar { grid-area: bar; height: 3px; margin-top: 5px; border-radius: 2px; background: var(--dbc-pipe-soft); }
  & .bar::before { content: ""; display: block; height: 100%; width: var(--w); border-radius: inherit; background: var(--c); transition: width .5s var(--dbc-pipe-spring); }
  & li { --c: color-mix(in oklab, var(--dbc-pipe-accent) calc(var(--i) * 20%), var(--dbc-pipe-cool)); }
}
.dbc-pipe__pick {
  padding: 12px; border-radius: 12px; background: var(--dbc-pipe-raise); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-pipe-accent) 35%, transparent);
  transition: opacity .25s, translate .35s var(--dbc-pipe-out);
  @starting-style { opacity: 0; translate: 0 6px; }
  & header { display: flex; align-items: start; justify-content: space-between; gap: 8px; }
  & b { font-size: 14px; font-weight: 700; letter-spacing: -.01em; }
  & p { font-size: 11.5px; color: var(--dbc-pipe-mute); margin-top: 1px; }
  & dl { display: grid; grid-template-columns: auto 1fr; gap: 4px 12px; margin-top: 10px; font-size: 12px; }
  & dt { color: var(--dbc-pipe-mute); }
  & dd { text-align: right; font-variant-numeric: tabular-nums; font-weight: 560; }
  & .is-warn { color: var(--dbc-pipe-warn); }
}
.dbc-pipe__x { width: 24px; height: 24px; flex: none; display: grid; place-items: center; border-radius: 7px; color: var(--dbc-pipe-mute); &:hover { background: var(--dbc-pipe-soft); color: var(--dbc-pipe-ink); } & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; } }

/* deals table */
.dbc-pipe__tablep { height: 100%; }
.dbc-pipe__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbc-pipe-panel); text-align: left; font-weight: 600; padding: 0; border-bottom: 1px solid var(--dbc-pipe-line); }
  & th button { width: 100%; padding: 11px 12px 9px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-pipe-mute); display: flex; align-items: center; gap: 4px; }
  & th.is-r button { justify-content: flex-end; }
  & th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; opacity: 0; transition: opacity .15s; }
  & th[aria-sort] button { color: var(--dbc-pipe-ink); }
  & th[aria-sort=ascending] button::after { border-bottom-color: var(--dbc-pipe-accent); margin-top: -4px; opacity: 1; }
  & th[aria-sort=descending] button::after { border-top-color: var(--dbc-pipe-accent); margin-top: 4px; opacity: 1; }
  & td { padding: 8px 12px; border-bottom: 1px solid var(--dbc-pipe-soft); white-space: nowrap; }
  & td.is-r { text-align: right; font-variant-numeric: tabular-nums; font-family: var(--dbc-pipe-mono); font-size: 12px; }
  & tbody tr { cursor: pointer; transition: background-color .15s; outline: none; }
  & tbody tr:hover { background: var(--dbc-pipe-soft); }
  & tbody tr:focus-visible { box-shadow: inset 2px 0 0 var(--dbc-pipe-accent); background: var(--dbc-pipe-soft); }
  & tbody tr[aria-selected=true] { background: color-mix(in oklch, var(--dbc-pipe-accent) 13%, transparent); }
  & .acct { font-weight: 620; } & .prod { display: block; font-size: 11px; color: var(--dbc-pipe-mute); }
  & tfoot td { position: sticky; bottom: 0; background: var(--dbc-pipe-raise); font-weight: 650; border: 0; }
  & .is-warn { color: var(--dbc-pipe-warn); }
}
.dbc-pipe__chip { --c: color-mix(in oklab, var(--dbc-pipe-accent) calc(var(--i) * 20%), var(--dbc-pipe-cool)); display: inline-flex; align-items: center; gap: 6px; font-size: 12px; &::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: var(--c); } }
@supports (animation-timeline: view()) {
  .dbc-pipe__table tbody tr { animation: dbc-pipe-row linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; }
}
@keyframes dbc-pipe-row { from { opacity: 0; transform: translateY(10px); } }

/* velocity */
.dbc-pipe__fbar { fill: var(--c); }
.dbc-pipe__fcol { --c: color-mix(in oklab, var(--dbc-pipe-accent) calc(var(--i) * 16.6%), var(--dbc-pipe-cool)); }
.dbc-pipe__trap { fill: color-mix(in oklch, var(--dbc-pipe-ink) 7%, transparent); &.is-leak { fill: color-mix(in oklch, var(--dbc-pipe-warn) 22%, transparent); } }
.dbc-pipe__tl { fill: var(--dbc-pipe-ink); font: 650 11.5px var(--dbc-pipe-mono); text-anchor: middle; font-variant-numeric: tabular-nums; &.is-leak { fill: var(--dbc-pipe-warn); } }
.dbc-pipe__fc { fill: var(--dbc-pipe-mute); font: 10.5px var(--dbc-pipe-mono); text-anchor: middle; }
.dbc-pipe__fs { fill: var(--dbc-pipe-faint); font: 10.5px var(--dbc-pipe-mono); text-anchor: middle; & .is-warn { fill: var(--dbc-pipe-warn); font-weight: 650; } }
.dbc-pipe__funnel svg.is-enter .dbc-pipe__fcol { animation: dbc-pipe-rise .95s var(--dbc-pipe-out) backwards; animation-delay: calc(var(--i) * 70ms); }
.dbc-pipe__leak { font-size: 11.5px; color: var(--dbc-pipe-mute); & b { color: var(--dbc-pipe-warn); font-weight: 650; } }
.dbc-pipe__stall { padding: 14px; display: flex; flex-direction: column; gap: 8px; }
.dbc-pipe__stallnote { font-size: 12px; color: var(--dbc-pipe-mute); text-wrap: pretty; }
.dbc-pipe__slist {
  display: grid; gap: 4px;
  & button { width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; padding: 8px 9px; border-radius: 9px; transition: background-color .2s; &:hover { background: var(--dbc-pipe-soft); } }
  & .a { font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .v { font: 600 12px var(--dbc-pipe-mono); }
  & .s { grid-column: 1 / -1; font-size: 11.5px; color: var(--dbc-pipe-mute); }
  & .s em { font-style: normal; color: var(--dbc-pipe-warn); font-weight: 600; }
}

/* tooltip */
.dbc-pipe__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; width: max-content; max-width: 250px;
  padding: 10px 12px; border-radius: 10px; font-size: 12px;
  background: color-mix(in oklch, var(--dbc-pipe-bg) 72%, black); color: var(--dbc-pipe-ink);
  box-shadow: 0 0 0 1px var(--dbc-pipe-line), 0 16px 36px -14px black;
  opacity: 0; scale: .96; transform-origin: 0 100%; transition: opacity .14s, scale .22s var(--dbc-pipe-out);
  &[data-on] { opacity: 1; scale: 1; }
  & b { display: block; font-size: 13px; font-weight: 700; }
  & .sub { display: block; color: var(--dbc-pipe-mute); font-size: 11.5px; margin-bottom: 7px; }
  & dl { display: grid; grid-template-columns: auto auto; gap: 2px 14px; }
  & dt { color: var(--dbc-pipe-mute); }
  & dd { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }
}

/* ---------------------------------------------------------------- responsive */
@container dbc-pipe (max-width: 979px) {
  .dbc-pipe__shell { grid-template-columns: 62px minmax(0, 1fr); }
  .dbc-pipe__side { align-items: center; padding: 16px 8px; }
  .dbc-pipe__lbl, .dbc-pipe__brand span { display: none; }
  .dbc-pipe__brand { padding: 0 0 14px; }
  .dbc-pipe__tabs [role=tab] { width: 44px; height: 40px; justify-content: center; padding: 0; }
  .dbc-pipe__tabs [role=tab][aria-selected=true]::before { left: -8px; }
  .dbc-pipe__badge { position: absolute; top: 2px; right: -4px; padding: 2px 4px; font-size: 9.5px; background: var(--dbc-pipe-raise); }
  .dbc-pipe__v-stages, .dbc-pipe__v-vel { grid-template-columns: minmax(0, 1fr) 244px; }
}
@container dbc-pipe (max-width: 759px) {
  .dbc-pipe__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side" "main"; }
  .dbc-pipe__side { flex-direction: row; align-items: center; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbc-pipe-line); }
  .dbc-pipe__brand { padding: 0; }
  .dbc-pipe__brand span { display: block; } .dbc-pipe__brand small { display: none; }
  .dbc-pipe__tabs { grid-auto-flow: column; margin-left: auto; }
  .dbc-pipe__tabs [role=tab][aria-selected=true]::before { left: 10px; right: 10px; top: auto; bottom: -9px; width: auto; height: 3px; border-radius: 3px 3px 0 0; }
  .dbc-pipe__main { display: flex; flex-direction: column; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 14px; }
  .dbc-pipe__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
  .dbc-pipe__views { flex: none; }
  .dbc-pipe__view { height: auto; grid-template-columns: minmax(0, 1fr) !important; }
  .dbc-pipe__chartp, .dbc-pipe__funnelp { height: 380px; }
  .dbc-pipe__tablep { height: auto; max-height: 470px; }
  .dbc-pipe__aside, .dbc-pipe__stall { overflow: visible; }
}
@container dbc-pipe (max-width: 520px) {
  .dbc-pipe__filters { width: 100%; }
  .dbc-pipe__seg { flex: 1 1 auto; & [role=radio] { flex: 1; padding: 5px 6px; text-align: center; } }
  .dbc-pipe__select { flex: 1 1 100%; & select { width: 100%; } }
  .dbc-pipe__hide-s { display: none; }
  .dbc-pipe__kpis > div { padding: 9px 11px 10px; }
  .dbc-pipe__chartp { height: 340px; }
}

@media (prefers-reduced-motion: reduce) {
  .dbc-pipe *, .dbc-pipe *::before, .dbc-pipe *::after { animation: none !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
}

