});
chart.addEventListener('keydown', e => {
  const k = e.target.closest('.dbc-pipe__knob'); if (!k) return;
  const i = +k.closest('.dbc-pipe__col').dataset.s; let p = probs[i];
  switch (e.key) {
    case 'ArrowUp': case 'ArrowRight': p += .05; break;
    case 'ArrowDown': case 'ArrowLeft': p -= .05; break;
    case 'PageUp': p += .2; break; case 'PageDown': p -= .2; break;
    case 'Home': p = 0; break; case 'End': p = 1; break;
    default: return;
  }
  e.preventDefault(); setProb(i, p, true);
});
function dealTip(d) {
  const p = probs[d.stage];
  return '<b>' + esc(d.acct) + '</b><span class="sub">' + esc(d.prod) + ' · ' + d.id + '</span><dl>' +
    '<dt>Stage</dt><dd>' + STAGES[d.stage].n + ' · ' + Math.round(p * 100) + '%</dd>' +
    '<dt>Amount</dt><dd>' + money(d.amt) + '</dd><dt>Weighted</dt><dd>' + money(d.amt * p) + '</dd>' +
    '<dt>Close</dt><dd>' + closeTxt(d) + '</dd><dt>Owner</dt><dd>' + esc(OWNERS[d.owner]) + '</dd>' +
    '<dt>In stage</dt><dd>' + d.days + ' days</dd></dl>';
}
chart.addEventListener('pointermove', e => {
  if (dragging) return;
  const r = e.target.closest('.dbc-pipe__ghost rect');
  if (!r) { hideTip(tip); return; }
  tip.innerHTML = dealTip(byId[r.dataset.id]); placeTip(tip, e.clientX, e.clientY);
});
chart.addEventListener('pointerleave', () => hideTip(tip));
chart.addEventListener('click', e => { const r = e.target.closest('.dbc-pipe__ghost rect'); if (r) select(r.dataset.id === sel ? null : r.dataset.id); });

/* ------------------------------------------------------------------ summary: KPIs, coverage, top list, model */
let sumRaf = 0;
function queueSummary() { cancelAnimationFrame(sumRaf); sumRaf = requestAnimationFrame(() => { if (!root.isConnected) return; summary(); }); }
function summary() {
  const m = metrics(), n = m.ds.length;
  countTo(K('pipe'), m.pipe, kfmt);
  K('pipe2').textContent = n + ' deals · avg ' + kfmt(n ? m.pipe / n : 0);
  countTo(K('wtd'), m.wtd, kfmt);
  K('wtd2').textContent = (m.pipe ? pct(m.wtd / m.pipe) : '0%') + ' of open pipeline';
  countTo(K('gap'), m.gap, kfmt);
  K('gap2').textContent = kfmt(m.closed) + ' won of ' + kfmt(m.q) + ' quota';
  const covTxt = v => m.gap ? v.toFixed(2) + '×' : 'Met';
  countTo(K('cov'), m.cov, covTxt);
  K('cov2').textContent = m.gap ? m.raw.toFixed(1) + '× unweighted' : 'quota already closed';
  K('count').textContent = n;
  countTo(K('ring'), m.cov, covTxt);
  $('.dbc-pipe__ring').style.setProperty('--dbc-pipe-cov', (m.gap ? Math.min(100, m.cov * 100) : 100) + '%');
  const mx = Math.max(m.gap, m.pipe, 1);
  $('.dbc-pipe__covbars').innerHTML =
    '<div style="--w:' + (m.gap / mx * 100) + '%;--bar:var(--dbc-pipe-ink)"><span>Gap to quota</span><b>' + kfmt(m.gap) + '</b><i></i></div>' +
    '<div style="--w:' + (m.pipe / mx * 100) + '%;--bar:color-mix(in oklch, var(--dbc-pipe-accent) 45%, transparent)"><span>Open</span><b>' + kfmt(m.pipe) + '</b><i></i></div>' +
    '<div style="--w:' + (m.wtd / mx * 100) + '%;--bar:var(--dbc-pipe-accent)"><span>Weighted</span><b>' + kfmt(m.wtd) + '</b><i></i></div>';
  const short = m.gap - m.wtd;
  $('.dbc-pipe__covnote').innerHTML = !m.gap ? 'Closed won already covers this slice of quota.' : short > 0
    ? 'Weighted pipeline leaves <b>' + kfmt(short) + '</b> of the gap uncovered. It needs ' + (m.pipe ? '<b>' + pct(Math.min(1, m.gap / m.pipe)) + '</b> of every open dollar to close.' : 'new pipeline.')
    : 'Weighted pipeline covers the gap with <b>' + kfmt(-short) + '</b> to spare.';
  // top list, keyed + FLIP
  const list = $('.dbc-pipe__top');
  const top = m.ds.slice().sort((a, b) => wtdOf(b) - wtdOf(a)).slice(0, 6), mxw = top.length ? wtdOf(top[0]) : 1;
  flip(() => $$('li', list), () => {
    const keep = new Set(top.map(d => d.id));
    $$('li', list).forEach(li => { if (!keep.has(li.dataset.id)) li.remove(); });
    top.forEach(d => {
      let li = list.querySelector('li[data-id="' + d.id + '"]');
      if (!li) { li = document.createElement('li'); li.dataset.id = d.id; li.innerHTML = '<button type="button" aria-pressed="false"><span class="a"></span><span class="s"></span><span class="v"></span><span class="bar"></span></button>'; }
      li.style.setProperty('--i', d.stage);
      li.querySelector('.a').textContent = d.acct;
      li.querySelector('.s').textContent = STAGES[d.stage].n + ' · ' + kfmt(d.amt);
      li.querySelector('.v').textContent = kfmt(wtdOf(d));
      li.querySelector('.bar').style.setProperty('--w', (wtdOf(d) / mxw * 100) + '%');
      li.querySelector('button').setAttribute('aria-pressed', d.id === sel ? 'true' : 'false');
      list.appendChild(li);
    });
  }, 480);
  // probability model in the sidebar
  $('.dbc-pipe__plist').innerHTML = STAGES.map((s, i) => {
    const mod = probs[i] !== s.p;
    return '<li class="' + (mod ? 'is-mod' : '') + '"><span>' + s.n + '</span><b>' + (mod ? '<s>' + Math.round(s.p * 100) + '%</s>' : '') + Math.round(probs[i] * 100) + '%</b></li>';
  }).join('');
  $('.dbc-pipe__reset').disabled = probs.every((p, i) => p === STAGES[i].p);
  if (view === 'deals') renderTable();
}
$('.dbc-pipe__top').addEventListener('click', e => { const li = e.target.closest('li'); if (li) select(li.dataset.id === sel ? null : li.dataset.id); });
$('.dbc-pipe__reset').addEventListener('click', () => STAGES.forEach((s, i) => setProb(i, s.p, true)));

/* ------------------------------------------------------------------ selection */
function select(id) {
  sel = id && byId[id] && inF(byId[id]) ? id : null;
  markSel();
  $$('.dbc-pipe__top li').forEach(li => li.querySelector('button').setAttribute('aria-pressed', li.dataset.id === sel ? 'true' : 'false'));
  $$('.dbc-pipe__table tbody tr').forEach(tr => tr.setAttribute('aria-selected', tr.dataset.id === sel ? 'true' : 'false'));
  const pick = $('.dbc-pipe__pick');
  if (!sel) { pick.hidden = true; pick.innerHTML = ''; return; }
  const d = byId[sel], p = probs[d.stage], st = stalled(d);
  pick.innerHTML = '<header><div><b>' + esc(d.acct) + '</b><p>' + esc(d.prod) + ' · ' + d.id + '</p></div><button class="dbc-pipe__x" type="button" aria-label="Clear selection">' + CLOSE_IC + '</button></header>' +
    '<dl><dt>Stage</dt><dd>' + STAGES[d.stage].n + '</dd><dt>Amount</dt><dd>' + money(d.amt) + '</dd><dt>Weighted at ' + Math.round(p * 100) + '%</dt><dd>' + money(d.amt * p) + '</dd>' +
    '<dt>Expected close</dt><dd>' + closeTxt(d) + '</dd><dt>Owner</dt><dd>' + esc(OWNERS[d.owner]) + '</dd><dt>Segment</dt><dd>' + SEGS[d.seg].n + '</dd>' +
    '<dt>In stage</dt><dd class="' + (st ? 'is-warn' : '') + '">' + d.days + ' days' + (st ? ' · stalled' : '') + '</dd></dl>';
  pick.hidden = false;
}
function markSel() {
  $$('.dbc-pipe__chart rect[data-id]').forEach(r => r.classList.toggle('is-sel', r.dataset.id === sel));
}
$('.dbc-pipe__pick').addEventListener('click', e => { if (e.target.closest('.dbc-pipe__x')) select(null); });

/* ------------------------------------------------------------------ deals table */
const SORTERS = {
  acct: d => d.acct, stage: d => d.stage, owner: d => OWNERS[d.owner], close: d => MKEYS.indexOf(d.month) * 40 + d.day,
  amt: d => d.amt, wtd: d => wtdOf(d), days: d => d.days
};
const tbody = $('.dbc-pipe__table tbody');
function renderTable() {
  const ds = deals.filter(inF), f = SORTERS[sort.k];
  ds.sort((a, b) => { const x = f(a), y = f(b); return (x < y ? -1 : x > y ? 1 : 0) * sort.dir || b.amt - a.amt; });
  const focusedId = root.contains(document.activeElement) && document.activeElement.closest('tbody tr') ? document.activeElement.dataset.id : null;
  flip(() => $$('tr', tbody), () => {
    const keep = new Set(ds.map(d => d.id));
    $$('tr', tbody).forEach(tr => { if (!keep.has(tr.dataset.id)) tr.remove(); });
    ds.forEach((d, i) => {
      let tr = tbody.querySelector('tr[data-id="' + d.id + '"]');
      if (!tr) { tr = document.createElement('tr'); tr.dataset.id = d.id; }
      const st = stalled(d);
      tr.innerHTML = '<td><span class="acct">' + esc(d.acct) + '</span><span class="prod">' + esc(d.prod) + '</span></td>' +
        '<td><span class="dbc-pipe__chip" style="--i:' + d.stage + '">' + STAGES[d.stage].n + '</span></td>' +
        '<td class="dbc-pipe__hide-s">' + esc(OWNERS[d.owner]) + '</td><td class="dbc-pipe__hide-s">' + closeTxt(d) + '</td>' +
        '<td class="is-r">' + money(d.amt) + '</td><td class="is-r">' + money(wtdOf(d)) + '</td>' +
        '<td class="is-r dbc-pipe__hide-s' + (st ? ' is-warn' : '') + '">' + d.days + 'd</td>';
      tr.tabIndex = (focusedId ? d.id === focusedId : i === 0) ? 0 : -1;
      tr.setAttribute('aria-selected', d.id === sel ? 'true' : 'false');
      tbody.appendChild(tr);
    });
  }, 520);
  const tA = ds.reduce((s, d) => s + d.amt, 0), tW = ds.reduce((s, d) => s + wtdOf(d), 0);
  $('.dbc-pipe__table tfoot').innerHTML = '<tr><td>' + ds.length + ' deals</td><td></td><td class="dbc-pipe__hide-s"></td><td class="dbc-pipe__hide-s"></td><td class="is-r">' + money(tA) + '</td><td class="is-r">' + money(tW) + '</td><td class="dbc-pipe__hide-s"></td></tr>';
  $$('.dbc-pipe__table th').forEach(th => { if (th.dataset.sort === sort.k) th.setAttribute('aria-sort', sort.dir > 0 ? 'ascending' : 'descending'); else th.removeAttribute('aria-sort'); });
}
$('.dbc-pipe__table thead').addEventListener('click', e => {
  const th = e.target.closest('th'); if (!th) return;
  const k = th.dataset.sort;
  sort = { k, dir: sort.k === k ? -sort.dir : (k === 'acct' || k === 'owner' || k === 'close' || k === 'stage' ? 1 : -1) };
  renderTable();
});
tbody.addEventListener('click', e => { const tr = e.target.closest('tr'); if (tr) { tr.focus(); select(tr.dataset.id === sel ? null : tr.dataset.id); } });
tbody.addEventListener('keydown', e => {
  const tr = e.target.closest('tr'); if (!tr) return;
  const rows = $$('tr', tbody); let i = rows.indexOf(tr);
  if (e.key === 'ArrowDown') i = Math.min(rows.length - 1, i + 1);
  else if (e.key === 'ArrowUp') i = Math.max(0, i - 1);
  else if (e.key === 'Home') i = 0; else if (e.key === 'End') i = rows.length - 1;
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(tr.dataset.id === sel ? null : tr.dataset.id); return; }
  else return;
  e.preventDefault(); rows.forEach(r => { r.tabIndex = -1; }); rows[i].tabIndex = 0; rows[i].focus(); rows[i].scrollIntoView({ block: 'nearest' });
});

/* ------------------------------------------------------------------ velocity */
let funEntered = false;
function drawFunnel() {
  if (!fun.offsetParent) return;
  const segs = F.seg === 'all' ? Object.keys(HIST) : [F.seg];
  const Hs = [0, 0, 0, 0, 0, 0, 0]; segs.forEach(s => HIST[s].forEach((v, i) => { Hs[i] += v; }));
  const names = STAGES.map(s => s.n).concat('Closed won'), shorts = STAGES.map(s => s.s).concat('Won');
  const { w, h } = sizeOf(fun), narrow = w < 560;
  const M = { l: 6, r: 6, t: 22, b: 72 }, iw = w - M.l - M.r, ih = Math.max(40, h - M.t - M.b);
  const band = iw / 7, bw = Math.min(band * .46, 64), base = M.t + ih;
  const Y = v => base - v / Hs[0] * ih;
  const ds = deals.filter(inF);
  const conv = Hs.slice(1).map((v, i) => v / Hs[i]);
  let leak = 0; conv.slice(0, 5).forEach((c, i) => { if (c < conv[leak]) leak = i; });
  let s = '<svg width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '" class="' + (funEntered ? 'is-update' : 'is-enter') + '">';
  for (let i = 0; i < 6; i++) {
    const xa = M.l + band * i + band / 2 + bw / 2, xb = M.l + band * (i + 1) + band / 2 - bw / 2;
    s += '<path class="dbc-pipe__trap' + (i === leak ? ' is-leak' : '') + '" d="M' + xa + ' ' + Y(Hs[i]) + 'L' + xb + ' ' + Y(Hs[i + 1]) + 'L' + xb + ' ' + base + 'L' + xa + ' ' + base + 'Z"/>';
    s += '<text class="dbc-pipe__tl' + (i === leak ? ' is-leak' : '') + '" x="' + (xa + xb) / 2 + '" y="' + (base - 10) + '">' + pct(conv[i]) + '</text>';
  }
  names.forEach((nm, i) => {
    const cx = M.l + band * i + band / 2, y = Y(Hs[i]);
    s += '<g class="dbc-pipe__fcol" style="--i:' + i + '"><rect class="dbc-pipe__fbar" x="' + (cx - bw / 2) + '" y="' + y + '" width="' + bw + '" height="' + (base - y) + '" rx="3"/>';
    s += '<text class="dbc-pipe__fc" x="' + cx + '" y="' + (y - 7) + '">' + NF.format(Hs[i]) + '</text></g>';
    s += '<text class="dbc-pipe__xl" x="' + cx + '" y="' + (base + 17) + '">' + (narrow ? shorts[i] : nm) + '</text>';
    if (i < 6) {
      const inSt = ds.filter(d => d.stage === i).map(d => d.days).sort((a, b) => a - b);
      const med = inSt.length ? inSt[Math.floor(inSt.length / 2)] : 0, nSt = ds.filter(d => d.stage === i && stalled(d)).length;
      s += '<text class="dbc-pipe__fs" x="' + cx + '" y="' + (base + 33) + '">now <tspan class="' + (med > STAGES[i].avg ? 'is-warn' : '') + '">' + (inSt.length ? med + 'd' : '—') + '</tspan></text>';
      s += '<text class="dbc-pipe__fs" x="' + cx + '" y="' + (base + 47) + '">avg ' + STAGES[i].avg + 'd</text>';
      s += '<text class="dbc-pipe__fs" x="' + cx + '" y="' + (base + 61) + '"><tspan class="' + (nSt ? 'is-warn' : '') + '">' + nSt + ' stalled</tspan></text>';
    } else {
      s += '<text class="dbc-pipe__fs" x="' + cx + '" y="' + (base + 33) + '">' + pct(Hs[6] / Hs[0], 1) + '</text>';
      s += '<text class="dbc-pipe__fs" x="' + cx + '" y="' + (base + 47) + '">of entries</text>';
    }
  });
  s += '<line class="dbc-pipe__base" x1="' + M.l + '" x2="' + (w - M.r) + '" y1="' + base + '" y2="' + base + '"/></svg>';
  fun.innerHTML = s;
  fun.setAttribute('aria-label', 'Conversion by stage. ' + names.map((n, i) => n + ' ' + Hs[i]).join(', '));
  funEntered = true;
  $('.dbc-pipe__leak').innerHTML = 'Biggest drop: <b>' + STAGES[leak].n + ' → ' + names[leak + 1] + ', ' + pct(conv[leak]) + '</b>';
  const st = ds.filter(stalled).sort((a, b) => b.amt - a.amt);
  $('.dbc-pipe__stallnote').textContent = st.length
    ? st.length + ' deals worth ' + kfmt(st.reduce((s2, d) => s2 + d.amt, 0)) + ' have sat in their stage over 1.5× the historical average.'
    : 'Nothing in this slice has sat in its stage longer than 1.5× the historical average.';
  $('.dbc-pipe__slist').innerHTML = st.map(d => '<li><button type="button" data-id="' + d.id + '"><span class="a">' + esc(d.acct) + '</span><span class="v">' + kfmt(d.amt) + '</span><span class="s">' + STAGES[d.stage].n + ' · <em>' + d.days + 'd</em> vs ' + STAGES[d.stage].avg + 'd avg · ' + esc(OWNERS[d.owner].split(' ')[0]) + '</span></button></li>').join('');
}
$('.dbc-pipe__slist').addEventListener('click', e => {
  const b = e.target.closest('button[data-id]'); if (!b) return;
  pickTab($('[role=tab][data-view=stages]'), true); select(b.dataset.id);
});

/* ------------------------------------------------------------------ views, filters */
function showView(v) {
  view = v; hideTip(tip);
  $$('.dbc-pipe__view').forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'stages') drawStages(); else if (v === 'deals') renderTable(); else drawFunnel();
}
const pickTab = tabs($('.dbc-pipe__tabs'), v => showView(v));
function refresh() {
  if (sel && !inF(byId[sel])) select(null);
  summary();
  if (view === 'stages') drawStages(); else if (view === 'velocity') drawFunnel();
}
$$('.dbc-pipe__seg').forEach(g => radioGroup(g, v => { F[g.dataset.f] = v; refresh(); }));
ownerSel.addEventListener('change', () => { F.owner = ownerSel.value; refresh(); });
root.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (tip.dataset.on) hideTip(tip); else if (sel) select(null);
});
onResize(chart, drawStages);
onResize(fun, drawFunnel);
summary();
drawStages();

css:
.dbc-race {
  /* re-theme with these four */
  --dbc-race-bg: oklch(0.976 0.009 95);
  --dbc-race-ink: oklch(0.24 0.03 168);
  --dbc-race-accent: oklch(0.52 0.105 165);
  --dbc-race-gold: oklch(0.79 0.145 80);
  /* derived */
  --dbc-race-card: color-mix(in oklch, var(--dbc-race-bg) 40%, white);
  --dbc-race-side: color-mix(in oklch, var(--dbc-race-bg) 95%, var(--dbc-race-ink));
  --dbc-race-line: color-mix(in oklch, var(--dbc-race-ink) 12%, transparent);
  --dbc-race-soft: color-mix(in oklch, var(--dbc-race-ink) 5%, transparent);
  --dbc-race-mute: color-mix(in oklch, var(--dbc-race-ink) 62%, var(--dbc-race-bg));
  --dbc-race-faint: color-mix(in oklch, var(--dbc-race-ink) 42%, var(--dbc-race-bg));
  --dbc-race-tint: color-mix(in oklch, var(--dbc-race-accent) 11%, var(--dbc-race-card));
  --dbc-race-east: oklch(0.56 0.1 220);
  --dbc-race-west: oklch(0.62 0.13 45);
  --dbc-race-strat: oklch(0.45 0.07 300);
  --dbc-race-down: oklch(0.56 0.17 28);
  --dbc-race-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbc-race-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbc-race-out: cubic-bezier(.16, 1, .3, 1);
  --dbc-race-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  width: 100%;
  height: var(--dbc-race-h, 680px);
  container-type: inline-size;
  container-name: dbc-race;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dbc-race-bg);
  color: var(--dbc-race-ink);
  font: 13px/1.45 var(--dbc-race-sans);
  accent-color: var(--dbc-race-accent);
  box-shadow: inset 0 0 0 1px var(--dbc-race-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, dl, dd, ul, ol, figure, table, fieldset) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(input, select, textarea) { font: inherit; color: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dbc-race-accent); outline-offset: 2px; border-radius: 6px; }
  & :where(.dbc-race__scroll) { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbc-race-ink) 22%, transparent) transparent; }
  & .dbc-race__num { font-variant-numeric: tabular-nums; }
  & .dbc-race__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

}
.dbc-race__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbc-race__shell { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-areas: "side main"; }

.dbc-race__side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 18px 12px 16px; background: var(--dbc-race-side); border-right: 1px solid var(--dbc-race-line); }
.dbc-race__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 50%; background: var(--dbc-race-ink); fill: none; stroke: var(--dbc-race-gold); stroke-width: 2.2; stroke-linecap: round; }
  & b { display: block; font-size: 15px; font-weight: 780; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbc-race-mute); }
}
.dbc-race__tabs {
  display: grid; gap: 2px;
  & [role=tab] {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; color: var(--dbc-race-mute); font-weight: 560;
    transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover { background: var(--dbc-race-soft); color: var(--dbc-race-ink); }
    &[aria-selected=true] { background: var(--dbc-race-card); color: var(--dbc-race-ink); font-weight: 650; box-shadow: 0 1px 0 var(--dbc-race-line), 0 6px 16px -10px color-mix(in oklch, var(--dbc-race-ink) 40%, transparent); }
    &[aria-selected=true] .dbc-race__ic { color: var(--dbc-race-accent); }
  }
}
.dbc-race__foot {
  margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbc-race-line); display: grid; gap: 10px; font-size: 12px; color: var(--dbc-race-mute); text-wrap: pretty;
  & b { color: var(--dbc-race-ink); font-weight: 650; }
}
.dbc-race__legend {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 12px; font-size: 11px;
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 10px; height: 10px; border-radius: 2px; }
  & .is-q { background: repeating-conic-gradient(var(--dbc-race-ink) 0 25%, var(--dbc-race-card) 0 50%) 0 0 / 5px 5px; }
  & .is-c { background: var(--dbc-race-gold); }
  & .is-p { width: 2px; background: repeating-linear-gradient(var(--dbc-race-ink) 0 2px, transparent 2px 4px); }
}

.dbc-race__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto auto minmax(0, 1fr); gap: 12px; padding: 16px 18px 16px; }
.dbc-race__head {
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px;
  & h2 { font-size: clamp(20px, 2.5cqi, 30px); font-weight: 820; letter-spacing: -.045em; line-height: 1; text-wrap: balance; }
}
.dbc-race__eyebrow { font-size: 11.5px; font-weight: 600; color: var(--dbc-race-mute); margin-bottom: 4px; }
.dbc-race__chips {
  display: flex; flex-wrap: wrap; gap: 6px;
  & [role=radio] {
    display: inline-flex; align-items: center; gap: 6px; padding: 5px 11px; border-radius: 99px; font-size: 12px; font-weight: 600;
    background: var(--dbc-race-card); box-shadow: inset 0 0 0 1px var(--dbc-race-line); color: var(--dbc-race-mute); transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover { color: var(--dbc-race-ink); }
    &[aria-checked=true] { background: var(--dbc-race-ink); color: var(--dbc-race-bg); box-shadow: none; }
  }
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--t); }
}
.dbc-race__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-radius: 14px; background: var(--dbc-race-card); box-shadow: inset 0 0 0 1px var(--dbc-race-line);
  & > div { min-width: 0; padding: 10px 16px 11px; display: grid; gap: 1px; }
  & > div + div { border-left: 1px solid var(--dbc-race-line); }
  & dt { font-size: 11px; font-weight: 600; color: var(--dbc-race-mute); }
  & dd { font-size: clamp(18px, 2.2cqi, 26px); font-weight: 780; letter-spacing: -.035em; line-height: 1.15; }
  & small { font-size: 11.5px; color: var(--dbc-race-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}

/* transport */
.dbc-race__transport { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 14px; }
.dbc-race__play {
  width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center; background: var(--dbc-race-ink); color: var(--dbc-race-bg);
  transition: scale .3s var(--dbc-race-out), background-color .2s;
  &:hover { scale: 1.06; } &:active { scale: .94; }
  & svg { width: 16px; height: 16px; grid-area: 1 / 1; fill: currentColor; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; transition: opacity .2s, scale .3s var(--dbc-race-out); }
  & .is-pause { fill: none; opacity: 0; scale: .5; }
  &[aria-pressed=true] .is-play { opacity: 0; scale: .5; }
  &[aria-pressed=true] .is-pause { opacity: 1; scale: 1; }
}
.dbc-race__scrub {
  position: relative; display: grid; gap: 2px;
  & input { width: 100%; margin: 0; height: 22px; cursor: pointer; background: transparent; -webkit-appearance: none; appearance: none; }
  & input::-webkit-slider-runnable-track { height: 6px; border-radius: 3px; background: linear-gradient(90deg, var(--dbc-race-accent) var(--p, 100%), var(--dbc-race-line) 0); }
  & input::-moz-range-track { height: 6px; border-radius: 3px; background: linear-gradient(90deg, var(--dbc-race-accent) var(--p, 100%), var(--dbc-race-line) 0); }
  & input::-webkit-slider-thumb { -webkit-appearance: none; width: 18px; height: 18px; margin-top: -6px; border-radius: 50%; background: var(--dbc-race-card); box-shadow: 0 0 0 2px var(--dbc-race-accent), 0 2px 6px color-mix(in oklch, var(--dbc-race-ink) 30%, transparent); transition: scale .2s var(--dbc-race-out); }
  & input::-moz-range-thumb { width: 16px; height: 16px; border: 0; border-radius: 50%; background: var(--dbc-race-card); box-shadow: 0 0 0 2px var(--dbc-race-accent); }
  & input:active::-webkit-slider-thumb { scale: 1.15; }
  & input:focus-visible { outline: none; }
  & input:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 2px var(--dbc-race-accent), 0 0 0 6px color-mix(in oklch, var(--dbc-race-accent) 25%, transparent); }
}
.dbc-race__ticks {
  display: flex; justify-content: space-between; padding: 0 7px; font: 10px var(--dbc-race-mono); color: var(--dbc-race-faint);
  & span { width: 0; display: flex; justify-content: center; white-space: nowrap; }
  & span.is-m { color: var(--dbc-race-ink); font-weight: 650; }
  & span.is-on { color: var(--dbc-race-accent); }
}
.dbc-race__wk { min-width: 132px; text-align: right; font-size: 12px; color: var(--dbc-race-mute); font-variant-numeric: tabular-nums; & b { display: block; color: var(--dbc-race-ink); font-size: 14px; font-weight: 720; letter-spacing: -.01em; } }

.dbc-race__body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 272px; gap: 12px; }
.dbc-race__views { min-height: 0; min-width: 0; border-radius: 14px; background: var(--dbc-race-card); box-shadow: inset 0 0 0 1px var(--dbc-race-line); overflow: hidden; }
.dbc-race__view { height: 100%; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dbc-race__view[hidden] { display: none; }
.dbc-race__bar, .dbc-race__ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 12px; padding: 10px 12px 8px 14px; border-bottom: 1px solid var(--dbc-race-line); }
.dbc-race__ph { & h3 { font-size: 12.5px; font-weight: 700; } & span { font-size: 11.5px; color: var(--dbc-race-mute); } }
.dbc-race__seg {
  display: inline-flex; padding: 2px; border-radius: 9px; background: var(--dbc-race-soft);
  & [role=radio] { padding: 4px 10px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--dbc-race-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & [role=radio][aria-checked=true] { background: var(--dbc-race-card); color: var(--dbc-race-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbc-race-ink) 18%, transparent); }
}

/* board */
.dbc-race__board { min-height: 0; padding: 4px 6px 8px; }
.dbc-race__row {
  --t: var(--dbc-race-east);
  position: relative; display: grid; grid-template-columns: 26px 28px minmax(96px, 150px) minmax(0, 1fr) 66px 34px; align-items: center; gap: 10px;
  height: 38px; padding: 0 8px; border-radius: 10px; cursor: pointer; outline: none;
  transition: background-color .2s;
  &:hover { background: var(--dbc-race-soft); }
  &:focus-visible { box-shadow: inset 0 0 0 2px var(--dbc-race-accent); }
  &[aria-selected=true] { background: var(--dbc-race-tint); }
  &[data-team=west] { --t: var(--dbc-race-west); } &[data-team=strat] { --t: var(--dbc-race-strat); }
  &.is-out { opacity: .38; }
}
.dbc-race__rk { font: 800 15px/1 var(--dbc-race-sans); letter-spacing: -.04em; text-align: right; font-variant-numeric: tabular-nums; color: var(--dbc-race-ink); }
.dbc-race__row:not(.is-podium) .dbc-race__rk { color: var(--dbc-race-faint); font-weight: 650; }
.dbc-race__av { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font-size: 10.5px; font-weight: 750; letter-spacing: .02em; color: color-mix(in oklch, var(--t) 70%, black); background: color-mix(in oklch, var(--t) 18%, var(--dbc-race-card)); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--t) 45%, transparent); }
.dbc-race__who { min-width: 0; line-height: 1.2; & b { display: block; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } & small { font-size: 11px; color: var(--dbc-race-mute); } }
.dbc-race__track {
  position: relative; height: 16px; border-radius: 4px;
  background: repeating-linear-gradient(90deg, transparent 0 calc(100% / 14 - 1px), var(--dbc-race-soft) calc(100% / 14 - 1px) calc(100% / 14));
  & .fill {
    position: absolute; inset: 2px 0; border-radius: 3px; transform-origin: 0 50%; transform: scaleX(var(--s, 0));
    background: linear-gradient(90deg, color-mix(in oklch, var(--dbc-race-accent) 82%, var(--dbc-race-card)) 0 var(--qf, 100%), var(--dbc-race-gold) var(--qf, 100%));
    transition: transform .85s var(--dbc-race-spring);
  }
  & .q { position: absolute; top: -3px; bottom: -3px; left: var(--qx); width: 5px; translate: -2px 0; background: repeating-conic-gradient(var(--dbc-race-ink) 0 25%, var(--dbc-race-card) 0 50%) 0 0 / 5px 5px; border-radius: 1px; transition: left .6s var(--dbc-race-out); }
  & .c { position: absolute; top: 0; bottom: 0; left: var(--cx); width: 2px; translate: -1px 0; background: var(--dbc-race-gold); transition: left .6s var(--dbc-race-out); }
  & .p { position: absolute; top: -4px; bottom: -4px; left: var(--px); width: 0; border-left: 1.5px dashed color-mix(in oklch, var(--dbc-race-ink) 55%, transparent); transition: left .6s var(--dbc-race-out); }
}
.dbc-race__val { text-align: right; font: 650 12.5px var(--dbc-race-mono); font-variant-numeric: tabular-nums; }
.dbc-race__dl {
  display: inline-flex; align-items: center; justify-content: end; gap: 1px; font: 650 10.5px var(--dbc-race-mono); color: var(--dbc-race-faint);
  & svg { width: 10px; height: 10px; fill: currentColor; }
  &.is-up { color: var(--dbc-race-accent); } &.is-down { color: var(--dbc-race-down); }
}
.dbc-race__board.is-enter .dbc-race__row { animation: dbc-race-in .7s var(--dbc-race-out) backwards; animation-delay: calc(var(--i) * 40ms); }
.dbc-race__board.is-enter .fill { animation: dbc-race-grow 1.1s var(--dbc-race-out) backwards; animation-delay: calc(var(--i) * 40ms + 120ms); }
@keyframes dbc-race-in { from { opacity: 0; transform: translateX(-12px); } }
@keyframes dbc-race-grow { from { transform: scaleX(0); } }

/* trajectory */
.dbc-race__plot { position: relative; min-height: 0; margin: 6px 6px 4px; }
.dbc-race__plot svg { position: absolute; inset: 0; }
.dbc-race__gl { stroke: var(--dbc-race-line); }
.dbc-race__ax { fill: var(--dbc-race-faint); font: 10.5px var(--dbc-race-mono); font-variant-numeric: tabular-nums; }
.dbc-race__ref { fill: none; stroke-width: 1.5; &.is-q { stroke: var(--dbc-race-ink); stroke-dasharray: 1 0; opacity: .5; } &.is-c { stroke: var(--dbc-race-gold); stroke-width: 2; } &.is-p { stroke: var(--dbc-race-ink); stroke-dasharray: 4 4; opacity: .55; } }
.dbc-race__reflbl { font-size: 10.5px; font-weight: 650; fill: var(--dbc-race-mute); }
.dbc-race__ln {
  --t: var(--dbc-race-east);
  fill: none; stroke: color-mix(in oklch, var(--t) 45%, transparent); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; cursor: pointer;
  transition: stroke .2s, stroke-width .2s, opacity .2s;
  &[data-team=west] { --t: var(--dbc-race-west); } &[data-team=strat] { --t: var(--dbc-race-strat); }
  &.is-hot { stroke: var(--t); stroke-width: 2.4; }
  &.is-sel { stroke: var(--dbc-race-accent); stroke-width: 3.2; }
}
.dbc-race__hit { fill: none; stroke: transparent; stroke-width: 12; cursor: pointer; }
.dbc-race__area { fill: color-mix(in oklch, var(--dbc-race-accent) 12%, transparent); }
.dbc-race__end { font-size: 11px; font-weight: 600; fill: var(--dbc-race-mute); &.is-sel { fill: var(--dbc-race-accent); font-weight: 750; } }
.dbc-race__wkline { stroke: var(--dbc-race-accent); stroke-width: 1.5; }
.dbc-race__wklbl { fill: var(--dbc-race-accent); font: 650 10.5px var(--dbc-race-mono); text-anchor: middle; }
.dbc-race__cross { stroke: var(--dbc-race-ink); stroke-width: 1; stroke-dasharray: 2 3; opacity: 0; transition: opacity .15s; &.is-on { opacity: .6; } }
.dbc-race__dot { fill: var(--dbc-race-card); stroke: var(--dbc-race-accent); stroke-width: 2; }
.dbc-race__plot svg.is-enter .dbc-race__ln { stroke-dasharray: 1; animation: dbc-race-draw 1.3s var(--dbc-race-out) backwards; animation-delay: calc(var(--i) * 45ms); }
@keyframes dbc-race-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }

/* distribution */
.dbc-race__distnote { font-variant-numeric: tabular-nums; }
.dbc-race__buckets { min-height: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; padding: 12px; }
.dbc-race__bk {
  min-width: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; gap: 8px; border-radius: 12px; padding: 10px 8px 10px;
  background: linear-gradient(to top, color-mix(in oklch, var(--bk) 13%, transparent), transparent 75%);
  box-shadow: inset 0 -2px 0 var(--bk);
  & .stack { min-height: 0; display: flex; flex-direction: column-reverse; align-items: center; gap: 6px; overflow: hidden; }
  & .stack.is-dense { flex-direction: row; flex-wrap: wrap-reverse; justify-content: center; align-content: flex-start; gap: 5px; }
  & footer { text-align: center; line-height: 1.25; }
  & b { display: block; font-size: 12.5px; font-weight: 720; }
  & small { display: block; font-size: 11px; color: var(--dbc-race-mute); font-variant-numeric: tabular-nums; }
}
.dbc-race__chip {
  --t: var(--dbc-race-east);
  display: grid; grid-template-columns: 24px minmax(0, 1fr); grid-template-rows: auto auto; column-gap: 6px; align-items: center; text-align: left;
  width: 100%; max-width: 140px; padding: 3px 8px 3px 3px; border-radius: 99px; background: var(--dbc-race-card);
  box-shadow: 0 1px 0 var(--dbc-race-line), 0 4px 10px -8px color-mix(in oklch, var(--dbc-race-ink) 60%, transparent); font-size: 11.5px; font-weight: 650; line-height: 1.15;
  &[data-team=west] { --t: var(--dbc-race-west); } &[data-team=strat] { --t: var(--dbc-race-strat); }
  & .dbc-race__av { grid-row: 1 / 3; width: 24px; height: 24px; font-size: 9px; }
  & span:not(.dbc-race__av) { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & em { font: 500 10px var(--dbc-race-mono); font-style: normal; color: var(--dbc-race-mute); }
  .is-dense > & { width: auto; padding: 2px; grid-template-columns: 26px; border-radius: 50%; }
  .is-dense > & .dbc-race__av { width: 26px; height: 26px; }
  .is-dense > & span:not(.dbc-race__av), .is-dense > & em { display: none; }
  &:hover { box-shadow: 0 0 0 1.5px var(--t); }
  &[aria-pressed=true] { box-shadow: 0 0 0 2px var(--dbc-race-accent); }
  @starting-style { opacity: 0; scale: .8; }
  transition: opacity .3s, scale .4s var(--dbc-race-out), box-shadow .2s;
}

/* rep card */
.dbc-race__rep { min-height: 0; border-radius: 14px; background: var(--dbc-race-card); box-shadow: inset 0 0 0 1px var(--dbc-race-line); padding: 14px; display: flex; flex-direction: column; gap: 12px; }
.dbc-race__rh {
  --t: var(--dbc-race-east); display: flex; align-items: center; gap: 10px;
  &[data-team=west] { --t: var(--dbc-race-west); } &[data-team=strat] { --t: var(--dbc-race-strat); }
  & .dbc-race__av { width: 40px; height: 40px; font-size: 13px; }
  & b { display: block; font-size: 15px; font-weight: 750; letter-spacing: -.02em; }
  & small { font-size: 11.5px; color: var(--dbc-race-mute); }
}
.dbc-race__big {
  display: flex; align-items: baseline; justify-content: space-between; gap: 8px;
  & strong { font-size: 34px; font-weight: 820; letter-spacing: -.05em; line-height: 1; font-variant-numeric: tabular-nums; }
  & span { font-size: 12px; color: var(--dbc-race-mute); text-align: right; font-variant-numeric: tabular-nums; }
  & strong.is-club { color: color-mix(in oklch, var(--dbc-race-gold) 70%, var(--dbc-race-ink)); }
}
.dbc-race__weeks {
  display: grid; grid-template-columns: repeat(13, minmax(0, 1fr)); align-items: end; gap: 3px; height: 54px; padding-bottom: 14px; position: relative;
  & i { position: relative; height: max(2px, var(--h)); border-radius: 2px 2px 0 0; background: color-mix(in oklch, var(--dbc-race-accent) 30%, transparent); transition: background-color .25s; }
  & i.is-done { background: var(--dbc-race-accent); }
  & i.is-now { background: var(--dbc-race-ink); }
  & i::after { content: attr(data-w); position: absolute; top: calc(100% + 3px); left: 50%; translate: -50% 0; font: 9px var(--dbc-race-mono); color: var(--dbc-race-faint); }
}
.dbc-race__h4 { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-race-faint); }
.dbc-race__deals {
  display: grid; gap: 2px; font-size: 12px;
  & li { display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; gap: 8px; padding: 5px 0; border-bottom: 1px solid var(--dbc-race-soft); transition: opacity .3s; }
  & li.is-future { opacity: .38; }
  & .w { font: 10.5px var(--dbc-race-mono); color: var(--dbc-race-faint); padding-top: 1px; }
  & .a { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .v { font: 600 11.5px var(--dbc-race-mono); font-variant-numeric: tabular-nums; }
}

.dbc-race__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; width: max-content; max-width: 230px; padding: 9px 11px; border-radius: 10px; font-size: 12px;
  background: var(--dbc-race-ink); color: var(--dbc-race-bg); box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--dbc-race-ink) 70%, transparent);
  opacity: 0; scale: .96; transform-origin: 0 100%; transition: opacity .14s, scale .2s var(--dbc-race-out);
  &[data-on] { opacity: 1; scale: 1; }
  & b { display: block; font-weight: 700; }
  & span { color: color-mix(in oklch, var(--dbc-race-bg) 70%, transparent); font-variant-numeric: tabular-nums; }
}

@container dbc-race (max-width: 979px) {
  .dbc-race__shell { grid-template-columns: 60px minmax(0, 1fr); }
  .dbc-race__side { align-items: center; padding: 16px 8px; }
  .dbc-race__lbl, .dbc-race__brand span { display: none; }
  .dbc-race__brand { padding: 0 0 14px; }
  .dbc-race__tabs [role=tab] { width: 44px; height: 40px; justify-content: center; padding: 0; }
  .dbc-race__body { grid-template-columns: minmax(0, 1fr) 236px; }
  .dbc-race__row { grid-template-columns: 22px 28px minmax(80px, 120px) minmax(0, 1fr) 60px 30px; gap: 8px; }
}
@container dbc-race (max-width: 759px) {
  .dbc-race__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side" "main"; }
  .dbc-race__side { flex-direction: row; align-items: center; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbc-race-line); }
  .dbc-race__brand { padding: 0; } .dbc-race__brand span { display: block; } .dbc-race__brand small { display: none; }
  .dbc-race__tabs { grid-auto-flow: column; margin-left: auto; }
  .dbc-race__main { display: flex; flex-direction: column; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 14px; }
  .dbc-race__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); & > div:nth-child(3) { border-left: 0; } & > div:nth-child(n+3) { border-top: 1px solid var(--dbc-race-line); } }
  .dbc-race__body { display: flex; flex-direction: column; flex: none; }
  .dbc-race__views { height: 470px; flex: none; }
  .dbc-race__rep { flex: none; overflow: visible; }
  .dbc-race__buckets { grid-template-columns: repeat(5, minmax(96px, 1fr)); overflow-x: auto; }
}
@container dbc-race (max-width: 520px) {
  .dbc-race__transport { grid-template-columns: auto minmax(0, 1fr); }
  .dbc-race__wk { grid-column: 1 / -1; text-align: left; display: flex; gap: 8px; align-items: baseline; & b { display: inline; } }
  .dbc-race__ticks span:not(.is-m) { visibility: hidden; }
  .dbc-race__row { grid-template-columns: 18px 26px minmax(0, 1fr) 54px; grid-template-areas: "rk av who val" "rk av track track"; height: 50px; row-gap: 3px; column-gap: 8px; }
  .dbc-race__rk { grid-area: rk; } .dbc-race__av { grid-area: av; } .dbc-race__who { grid-area: who; } .dbc-race__val { grid-area: val; } .dbc-race__track { grid-area: track; height: 10px; }
  .dbc-race__dl { display: none; }
  .dbc-race__who small { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dbc-race *, .dbc-race *::before, .dbc-race *::after { animation: none !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
}

