/* ------------------------------------------------------------------ data: Q3 2026, 13 weeks */
const TEAM = { east: 'East', west: 'West', strat: 'Strategic' };
const SHAPES = {
  steady: () => 1, front: w => 1.7 - w / 10, back: w => .25 + Math.pow(w / 13, 2) * 2.4, hockey: w => w <= 9 ? .45 : 2.4, late: w => w <= 6 ? .2 : 1.4
};
const RSPEC = [
  ['Amara Osei', 'east', 720000, 1.12, 'steady'], ['Liam Brandt', 'east', 680000, .88, 'front'], ['Sofia Reyes', 'east', 650000, .69, 'steady'], ['Noah Kimura', 'east', 600000, .47, 'late'],
  ['Grace Whitfield', 'west', 760000, 1.18, 'steady'], ['Mateo Alvarez', 'west', 700000, .97, 'hockey'], ['Ines Dubois', 'west', 640000, .81, 'front'], ['Owen Fraser', 'west', 620000, .58, 'steady'],
  ['Zara Haddad', 'strat', 1100000, 1.31, 'back'], ['Felix Novak', 'strat', 980000, 1.04, 'hockey'], ['Ruth Achebe', 'strat', 1050000, .93, 'steady'], ['Daniel Moreau', 'strat', 900000, .74, 'front']
];
const PRE = ['Copperline', 'Harbor & Vale', 'Tidewater', 'Blue Mesa', 'Kingsway', 'Sterling Ridge', 'Alder', 'Westbrook', 'Northfield', 'Lakeshore', 'Granite Bay', 'Redfern', 'Cascade', 'Prairie Star', 'Ironwood', 'Seabright', 'Oakhurst', 'Pinecrest'];
const SUF = ['Distribution', 'Cold Chain', 'Imports', 'Freight', 'Grocers', 'Building Supply', 'Auto Parts', 'Pharma Logistics', 'Beverage', 'Home Goods'];
const R = rng(90321);
const usedAcct = new Set();
function acct() { for (;;) { const a = PRE[Math.floor(R() * PRE.length)] + ' ' + SUF[Math.floor(R() * SUF.length)]; if (!usedAcct.has(a)) { usedAcct.add(a); return a; } } }
function pickWeek(shape) {
  const ws = []; let t = 0;
  for (let w = 1; w <= 13; w++) { const v = Math.max(.05, SHAPES[shape](w)); ws.push(v); t += v; }
  let u = R() * t; for (let w = 0; w < 13; w++) { u -= ws[w]; if (u <= 0) return w + 1; } return 13;
}
const reps = RSPEC.map(([name, team, quota, att, shape], i) => {
  const target = Math.round(quota * att / 500) * 500, n = team === 'strat' ? 5 + Math.floor(R() * 3) : 7 + Math.floor(R() * 5);
  const wts = Array.from({ length: n }, () => .35 + Math.pow(R(), 2) * 2), wsum = wts.reduce((a, b) => a + b, 0);
  const deals = wts.map(x => ({ amt: Math.round(target * x / wsum / 500) * 500, acct: acct(), week: pickWeek(shape) }));
  deals[deals.length - 1].amt += target - deals.reduce((s, d) => s + d.amt, 0);
  if (name === 'Zara Haddad') { deals.sort((a, b) => b.amt - a.amt); deals[0].week = 12; }
  if (name === 'Liam Brandt') { deals.sort((a, b) => b.amt - a.amt); deals[0].week = 2; deals[1].week = 3; }
  deals.sort((a, b) => a.week - b.week || b.amt - a.amt);
  const cum = [0]; for (let w = 1; w <= 13; w++) cum[w] = cum[w - 1] + deals.filter(d => d.week === w).reduce((s, d) => s + d.amt, 0);
