];
const bucketsEl = $('.dbc-race__buckets');
bucketsEl.innerHTML = BANDS.map((b, k) => '<div class="dbc-race__bk" style="--bk:' + b.c + '" data-b="' + k + '"><div class="stack"></div><footer><b>' + b.n + '</b><small></small></footer></div>').join('');
function renderDist() {
  const w = S.week, rs = reps.filter(inTeam);
  flip(() => $$('.dbc-race__chip', bucketsEl), () => {
    $$('.dbc-race__chip', bucketsEl).forEach(c => { if (!inTeam(reps[+c.dataset.r])) c.remove(); });
    BANDS.forEach((b, k) => {
      const col = bucketsEl.children[k], stack = col.querySelector('.stack');
      const inB = rs.filter(r => { const a = att(r, w); return a >= b.lo && a < b.hi; }).sort((x, y) => att(x, w) - att(y, w));
      inB.forEach(r => {
        let c = bucketsEl.querySelector('.dbc-race__chip[data-r="' + r.i + '"]');
        if (!c) { c = document.createElement('button'); c.type = 'button'; c.className = 'dbc-race__chip'; c.dataset.r = r.i; c.dataset.team = r.team; c.innerHTML = '<span class="dbc-race__av" aria-hidden="true">' + r.ini + '</span><span>' + esc(r.first) + '</span><em></em>'; }
        c.querySelector('em').textContent = pct(att(r, w));
        c.setAttribute('aria-pressed', r.i === S.sel ? 'true' : 'false');
        c.setAttribute('aria-label', r.name + ', ' + pct(att(r, w)) + ' of quota');
        stack.appendChild(c);
      });
      stack.classList.toggle('is-dense', inB.length > 6);
      col.querySelector('small').textContent = inB.length + (inB.length === 1 ? ' rep · ' : ' reps · ') + kfmt(inB.reduce((s, r) => s + r.cum[w], 0));
    });
  }, 700);
  const med = rs.map(r => att(r, w)).sort((a, b) => a - b), m = med.length ? (med.length % 2 ? med[(med.length - 1) / 2] : (med[med.length / 2 - 1] + med[med.length / 2]) / 2) : 0;
  $('.dbc-race__distnote').textContent = 'Median rep at ' + pct(m) + ' in week ' + w;
}
bucketsEl.addEventListener('click', e => { const c = e.target.closest('.dbc-race__chip'); if (c) selectRep(+c.dataset.r); });

/* ------------------------------------------------------------------ rep card */
function renderRep() {
  const r = reps[S.sel], w = S.week, a = att(r, w), rk = ranking(w).findIndex(x => x.i === r.i) + 1;
  const mx = Math.max(...r.cum.slice(1).map((c, k) => c - r.cum[k]), 1);
  const aside = $('.dbc-race__rep');
  aside.innerHTML = '<div class="dbc-race__rh" data-team="' + r.team + '"><span class="dbc-race__av" aria-hidden="true">' + r.ini + '</span><div><b>' + esc(r.name) + '</b><small>' + TEAM[r.team] + ' · quota ' + money(r.quota) + '</small></div></div>' +
    '<div class="dbc-race__big"><strong class="' + (a >= 1.1 ? 'is-club' : '') + '">' + pct(a) + '</strong><span>' + money(r.cum[w]) + ' closed<br>' + (rk ? 'rank ' + rk + ' of ' + ranking(w).length : 'outside this team') + '</span></div>' +
    '<p class="dbc-race__h4">Closed by week</p><div class="dbc-race__weeks">' + r.cum.slice(1).map((c, k) => { const v = c - r.cum[k]; return '<i data-w="' + (k + 1) + '" class="' + (k + 1 === w ? 'is-now' : k + 1 < w ? 'is-done' : '') + '" style="--h:' + (v / mx * 100) + '%" title="Week ' + (k + 1) + ': ' + money(v) + '"></i>'; }).join('') + '</div>' +
    '<p class="dbc-race__h4">Deals &middot; ' + r.deals.length + '</p><ol class="dbc-race__deals">' + r.deals.map(d => '<li class="' + (d.week > w ? 'is-future' : '') + '"><span class="w">W' + d.week + '</span><span class="a">' + esc(d.acct) + '</span><span class="v">' + kfmt(d.amt) + '</span></li>').join('') + '</ol>';
}
function selectRep(i) {
  S.sel = i;
  $$('.dbc-race__row', board).forEach(li => li.setAttribute('aria-selected', +li.dataset.r === i ? 'true' : 'false'));
  $$('.dbc-race__chip', bucketsEl).forEach(c => c.setAttribute('aria-pressed', +c.dataset.r === i ? 'true' : 'false'));
  renderRep();
  if (S.view === 'path') drawPlot();
}

/* ------------------------------------------------------------------ week scrubbing + playback */
function setWeek(w) {
  S.week = clamp(w, 1, 13); range.value = S.week;
  kpis(); renderRep();
  if (S.view === 'race') renderBoard(); else if (S.view === 'path') drawPlot(); else renderDist();
}
range.addEventListener('input', () => { stop(); setWeek(+range.value); });
let timer = 0, visible = true;
const playBtn = $('.dbc-race__play');
function stop() { if (timer) { clearInterval(timer); timer = 0; } playBtn.setAttribute('aria-pressed', 'false'); playBtn.setAttribute('aria-label', 'Play the quarter'); }
function play() {
  if (S.week >= 13) setWeek(1);
  playBtn.setAttribute('aria-pressed', 'true'); playBtn.setAttribute('aria-label', 'Pause');
  timer = setInterval(() => {
    if (!root.isConnected) { clearInterval(timer); return; }
    if (!visible || document.hidden) return;
    if (S.week >= 13) { stop(); return; }
    setWeek(S.week + 1);
  }, RM ? 1400 : 1000);
}
playBtn.addEventListener('click', () => { if (timer) stop(); else play(); });
const io = new IntersectionObserver(es => { visible = es[0].isIntersecting; if (!root.isConnected) io.disconnect(); });
io.observe(root);

/* ------------------------------------------------------------------ views + filters */
function showView(v) {
  S.view = v; hideTip(tip);
  $$('.dbc-race__view').forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'race') renderBoard(); else if (v === 'path') drawPlot(); else renderDist();
}
tabs($('.dbc-race__tabs'), showView);
radioGroup($('.dbc-race__chips'), v => {
  S.team = v;
  if (!inTeam(reps[S.sel])) S.sel = ranking(S.week)[0].i;
  kpis(); renderRep(); showView(S.view);
});
$$('.dbc-race__seg').forEach(g => radioGroup(g, v => { S[g.dataset.f] = v; renderBoard(); if (g.dataset.f === 'metric') renderRep(); }));
root.addEventListener('keydown', e => {
  if (e.key === 'Escape') { hideTip(tip); stop(); }
});
onResize(plot, drawPlot);
kpis(); renderRep(); renderBoard();

