@property --dbc-call-v { syntax: '<integer>'; inherits: true; initial-value: 0; }

.dbc-call {
  /* re-theme with these four */
  --dbc-call-bg: oklch(0.205 0.022 172);
  --dbc-call-ink: oklch(0.955 0.012 150);
  --dbc-call-commit: oklch(0.82 0.15 152);
  --dbc-call-best: oklch(0.83 0.13 82);
  /* derived */
  --dbc-call-accent: var(--dbc-call-commit);
  --dbc-call-pipe: color-mix(in oklch, var(--dbc-call-ink) 55%, var(--dbc-call-bg));
  --dbc-call-quota: oklch(0.72 0.15 28);
  --dbc-call-panel: color-mix(in oklch, var(--dbc-call-bg) 93%, var(--dbc-call-ink));
  --dbc-call-raise: color-mix(in oklch, var(--dbc-call-bg) 85%, var(--dbc-call-ink));
  --dbc-call-line: color-mix(in oklch, var(--dbc-call-ink) 12%, transparent);
  --dbc-call-soft: color-mix(in oklch, var(--dbc-call-ink) 6%, transparent);
  --dbc-call-mute: color-mix(in oklch, var(--dbc-call-ink) 64%, var(--dbc-call-bg));
  --dbc-call-faint: color-mix(in oklch, var(--dbc-call-ink) 42%, var(--dbc-call-bg));
  --dbc-call-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbc-call-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbc-call-out: cubic-bezier(.16, 1, .3, 1);
  --dbc-call-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  width: 100%;
  height: var(--dbc-call-h, 680px);
  container-type: inline-size;
  container-name: dbc-call;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background:
    radial-gradient(70% 50% at 100% 0%, color-mix(in oklch, var(--dbc-call-commit) 8%, transparent), transparent 70%),
    var(--dbc-call-bg);
  color: var(--dbc-call-ink);
  font: 13px/1.45 var(--dbc-call-sans);
  accent-color: var(--dbc-call-best);
  color-scheme: dark;
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, dl, dd, ul, ol, figure, table, fieldset) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(input, select, textarea) { font: inherit; color: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dbc-call-accent); outline-offset: 2px; border-radius: 6px; }
  & :where(.dbc-call__scroll) { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbc-call-ink) 22%, transparent) transparent; }
  & .dbc-call__num { font-variant-numeric: tabular-nums; }
  & .dbc-call__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

}
.dbc-call__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbc-call__shell { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-areas: "side main"; }

.dbc-call__side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 18px 12px 16px; border-right: 1px solid var(--dbc-call-line); }
.dbc-call__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px;
  & svg { width: 30px; height: 30px; flex: none; fill: none; stroke: var(--dbc-call-commit); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbc-call-mute); }
}
.dbc-call__tabs {
  display: grid; gap: 2px;
  & [role=tab] {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dbc-call-mute); font-weight: 560; transition: background-color .2s, color .2s;
    &:hover { background: var(--dbc-call-soft); color: var(--dbc-call-ink); }
    &[aria-selected=true] { background: var(--dbc-call-raise); color: var(--dbc-call-ink); }
    &[aria-selected=true] .dbc-call__ic { color: var(--dbc-call-commit); }
  }
}
.dbc-call__foot { margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbc-call-line); font-size: 12px; color: var(--dbc-call-mute); text-wrap: pretty; display: grid; gap: 6px; & b { display: block; color: var(--dbc-call-ink); font-weight: 650; } }
.dbc-call__cap, .dbc-call__h3 { font-size: 10.5px; font-weight: 650; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-call-faint); }

.dbc-call__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 16px 18px; }
.dbc-call__head { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px; & h2 { font-size: clamp(19px, 2.3cqi, 27px); font-weight: 740; letter-spacing: -.035em; line-height: 1.05; text-wrap: balance; } }
.dbc-call__eyebrow { font: 600 10.5px/1.2 var(--dbc-call-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dbc-call-commit); margin-bottom: 5px; }
.dbc-call__filters { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.dbc-call__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dbc-call-panel); box-shadow: inset 0 0 0 1px var(--dbc-call-line);
  & [role=radio] { padding: 5px 10px; border-radius: 7px; font-size: 12px; font-weight: 580; color: var(--dbc-call-mute); white-space: nowrap; transition: background-color .2s, color .2s; }
  & [role=radio]:hover { color: var(--dbc-call-ink); }
  & [role=radio][aria-checked=true] { background: var(--dbc-call-raise); color: var(--dbc-call-ink); }
  &.is-sm [role=radio] { padding: 3px 8px; font-size: 11.5px; }
}
.dbc-call__select {
  position: relative; display: inline-flex; align-items: center;
  & select { appearance: none; padding: 6px 30px 6px 11px; border-radius: 10px; background: var(--dbc-call-panel); border: 1px solid var(--dbc-call-line); font-size: 12px; font-weight: 580; cursor: pointer; }
  & option { background: var(--dbc-call-bg); color: var(--dbc-call-ink); }
  & svg { position: absolute; right: 9px; width: 14px; height: 14px; pointer-events: none; fill: none; stroke: var(--dbc-call-mute); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}
.dbc-call__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div { min-width: 0; display: grid; gap: 1px; padding: 10px 14px 11px; border-radius: 12px; background: var(--dbc-call-panel); box-shadow: inset 0 0 0 1px var(--dbc-call-line); }
  & dt { display: flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 620; color: var(--dbc-call-mute); }
  & dt i { width: 10px; height: 3px; border-radius: 2px; }
  & .is-closed { background: var(--dbc-call-ink); } & .is-commit { background: var(--dbc-call-commit); } & .is-best { background: var(--dbc-call-best); }
  & dd { font-size: clamp(18px, 2.1cqi, 25px); font-weight: 720; letter-spacing: -.03em; line-height: 1.2; }
  & small { font-size: 11.5px; color: var(--dbc-call-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}

.dbc-call__body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 262px; gap: 12px; }
.dbc-call__views { min-height: 0; min-width: 0; }
.dbc-call__view { height: 100%; min-height: 0; display: grid; gap: 12px; }
.dbc-call__view[hidden] { display: none; }
.dbc-call__v-cone { grid-template-rows: minmax(0, 1.15fr) minmax(0, 1fr); }
.dbc-call__v-hist { grid-template-rows: minmax(0, 1fr) auto; }
.dbc-call__panel { min-width: 0; min-height: 0; border-radius: 14px; background: var(--dbc-call-panel); box-shadow: inset 0 0 0 1px var(--dbc-call-line); }
.dbc-call__ph { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; padding: 0 2px 6px; & h3 { font-size: 12.5px; font-weight: 660; } & > span { font-size: 11.5px; color: var(--dbc-call-mute); } }
.dbc-call__conep, .dbc-call__histp { margin: 0; padding: 10px 12px 4px; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dbc-call__cone, .dbc-call__hist { position: relative; min-height: 0; }
.dbc-call__cone svg, .dbc-call__hist svg { position: absolute; inset: 0; }

/* cone marks */
.dbc-call__gl { stroke: var(--dbc-call-line); }
.dbc-call__ax { fill: var(--dbc-call-faint); font: 10.5px var(--dbc-call-mono); font-variant-numeric: tabular-nums; }
.dbc-call__band-b { fill: color-mix(in oklch, var(--dbc-call-best) 20%, transparent); }
.dbc-call__band-p { fill: color-mix(in oklch, var(--dbc-call-pipe) 12%, transparent); }
.dbc-call__band-c { fill: color-mix(in oklch, var(--dbc-call-commit) 16%, transparent); }
.dbc-call__closedarea { fill: color-mix(in oklch, var(--dbc-call-ink) 10%, transparent); }
.dbc-call__l { fill: none; stroke-width: 2; stroke-linejoin: round; &.is-closed { stroke: var(--dbc-call-ink); stroke-width: 2.2; } &.is-commit { stroke: var(--dbc-call-commit); } &.is-best { stroke: var(--dbc-call-best); } &.is-pipe { stroke: var(--dbc-call-pipe); stroke-dasharray: 3 3; stroke-width: 1.5; } }
.dbc-call__quota { stroke: var(--dbc-call-quota); stroke-width: 1.5; stroke-dasharray: 6 4; }
.dbc-call__plan { stroke: color-mix(in oklch, var(--dbc-call-quota) 55%, transparent); stroke-width: 1; stroke-dasharray: 2 4; }
.dbc-call__ql { fill: var(--dbc-call-quota); font-size: 10.5px; font-weight: 650; }
.dbc-call__today { stroke: var(--dbc-call-ink); stroke-width: 1; opacity: .5; }
.dbc-call__tl { fill: var(--dbc-call-mute); font: 600 10px var(--dbc-call-mono); letter-spacing: .06em; text-transform: uppercase; }
.dbc-call__end { font: 650 11px var(--dbc-call-mono); font-variant-numeric: tabular-nums; &.is-commit { fill: var(--dbc-call-commit); } &.is-best { fill: var(--dbc-call-best); } &.is-pipe { fill: var(--dbc-call-pipe); } }
.dbc-call__callpin { fill: var(--dbc-call-ink); }
.dbc-call__callpin-l { fill: var(--dbc-call-ink); font: 700 10.5px var(--dbc-call-sans); paint-order: stroke; stroke: var(--dbc-call-panel); stroke-width: 4px; stroke-linejoin: round; }
.dbc-call__cross { stroke: var(--dbc-call-ink); stroke-dasharray: 2 3; opacity: 0; transition: opacity .15s; &.is-on { opacity: .55; } }
.dbc-call__mark { fill: var(--dbc-call-bg); stroke-width: 2.2; opacity: 0; transition: opacity .2s; &.is-on { opacity: 1; } }
.dbc-call__cone svg.is-enter .dbc-call__anim { animation: dbc-call-wipe 1.3s var(--dbc-call-out) backwards; }
.dbc-call__cone svg.is-enter .dbc-call__anim2 { animation: dbc-call-wipe 1.1s var(--dbc-call-out) .55s backwards; }
@keyframes dbc-call-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }

/* deals table */
.dbc-call__dealp { overflow: auto; }
.dbc-call__deals, .dbc-call__reps {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbc-call-panel); text-align: left; padding: 0; border-bottom: 1px solid var(--dbc-call-line); }
  & th button, & th > span { width: 100%; display: flex; align-items: center; gap: 4px; padding: 10px 12px 8px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-call-mute); }
  & th.is-r button { justify-content: flex-end; }
  & th button::after { content: ""; border: 4px solid transparent; opacity: 0; }
  & th[aria-sort] button { color: var(--dbc-call-ink); }
  & th[aria-sort=ascending] button::after { border-bottom-color: var(--dbc-call-commit); margin-top: -4px; opacity: 1; }
  & th[aria-sort=descending] button::after { border-top-color: var(--dbc-call-commit); margin-top: 4px; opacity: 1; }
  & td { padding: 6px 12px; border-bottom: 1px solid var(--dbc-call-soft); white-space: nowrap; }
  & th:first-child button, & td:first-child { padding-left: 14px; }
  & td.is-r { text-align: right; font: 12px var(--dbc-call-mono); font-variant-numeric: tabular-nums; }
  & tbody tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dbc-call-soft); }
  & .a { font-weight: 620; } & .o { display: block; font-size: 11px; color: var(--dbc-call-mute); }
}
.dbc-call__deals tbody tr:has([aria-checked=true][data-v=omit]) td:not(:last-child) { opacity: .45; }
.dbc-call__cat {
  display: inline-flex; padding: 2px; gap: 2px; border-radius: 8px; background: var(--dbc-call-soft);
  & [role=radio] { --c: var(--dbc-call-commit); min-width: 26px; padding: 3px 6px; border-radius: 6px; font: 650 10.5px var(--dbc-call-mono); color: var(--dbc-call-faint); transition: background-color .2s, color .2s, box-shadow .2s; }
  & [data-v=best] { --c: var(--dbc-call-best); } & [data-v=pipe] { --c: var(--dbc-call-pipe); } & [data-v=omit] { --c: var(--dbc-call-quota); }
  & [role=radio]:hover { color: var(--dbc-call-ink); }
  & .s { display: none; }
  & [role=radio][aria-checked=true] { background: color-mix(in oklch, var(--c) 22%, transparent); color: var(--c); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent); }
}
@supports (animation-timeline: view()) {
  .dbc-call__deals tbody tr, .dbc-call__reps tbody tr { animation: dbc-call-row linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}
@keyframes dbc-call-row { from { opacity: 0; transform: translateY(8px); } }

/* reps */
.dbc-call__repp { height: 100%; }
.dbc-call__reps {
  & td, & th button, & th > span { padding-left: 9px; padding-right: 9px; }
  & tbody tr { cursor: pointer; }
  & tbody tr[aria-selected=true] { background: color-mix(in oklch, var(--dbc-call-commit) 12%, transparent); }
  & tbody tr:focus-visible { outline: none; box-shadow: inset 2px 0 0 var(--dbc-call-commit); }
  & td.t { font-size: 11px; color: var(--dbc-call-mute); }
  & tfoot td { position: sticky; bottom: 0; background: var(--dbc-call-raise); font-weight: 650; padding: 8px 12px; }
}
.dbc-call__bulletc { width: 22%; }
.dbc-call__bullet {
  position: relative; height: 10px; min-width: 70px; border-radius: 3px; background: var(--dbc-call-soft); overflow: hidden;
  & i { position: absolute; top: 0; bottom: 0; left: 0; border-radius: 3px; transform-origin: 0 50%; transition: width .6s var(--dbc-call-spring); }
  & .b { background: color-mix(in oklch, var(--dbc-call-best) 55%, transparent); }
  & .c { background: var(--dbc-call-commit); }
  & .k { background: var(--dbc-call-ink); }
  & .q { left: auto; width: 2px; background: var(--dbc-call-quota); }
}

/* history */
.dbc-call__hl { fill: none; stroke-width: 2; &.is-closed { stroke: var(--dbc-call-ink); } &.is-commit { stroke: var(--dbc-call-commit); } &.is-best { stroke: var(--dbc-call-best); } &.is-call { stroke: var(--dbc-call-ink); stroke-width: 1.5; stroke-dasharray: 1 4; stroke-linecap: round; } }
