  st.innerHTML = '<i class="k" style="width:' + (t.cl / mx * 100) + '%"></i><i class="c" style="width:' + (t.commit / mx * 100) + '%"></i><i class="b" style="width:' + (t.best * bestPct / mx * 100) + '%"></i><i class="q" style="left:' + (t.q / mx * 100) + '%"></i>';
  $('.dbc-call__cats').innerHTML = '<li data-c="closed"><span>Closed won<small>' + closed.filter(inF).length + '</small></span><b>' + kfmt(t.cl) + '</b></li>' +
    CK.map(c => '<li data-c="' + c + '"><span>' + CATS[c].n + '<small>' + t.n[c] + '</small></span><b>' + kfmt(t[c]) + '</b></li>').join('');
  if (view === 'reps') renderReps();
  if (view === 'hist') drawHist();
}
$('.dbc-call__slider input').addEventListener('input', e => {
  bestPct = +e.target.value / 100; summary();
  if (G && cur) paintCone(cur, totals());
});
$('.dbc-call__submit').addEventListener('click', () => {
  const t = totals(), scope = F.rep !== 'all' ? REPS[+F.rep].n : F.team === 'all' ? 'the region' : TEAMS[F.team];
  if (F.team === 'all' && F.rep === 'all') submitted = t.call;
  const p = $('.dbc-call__sent'); p.textContent = '';
  requestAnimationFrame(() => { if (!root.isConnected) return; p.textContent = 'Submitted ' + money(t.call) + ' for ' + scope + ' · Fri, Oct 2'; });
  $('.dbc-call__submit').textContent = 'Resubmit call';
  if (view === 'hist') drawHist();
});

/* ------------------------------------------------------------------ views + filters */
function showView(v) {
  view = v; hideTip(tip);
  $$('.dbc-call__view').forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'cone') { drawCone(); renderDeals(); } else if (v === 'reps') renderReps(); else drawHist();
}
const pickTab = tabs($('.dbc-call__tabs'), showView);
function refresh() {
  summary();
  if (view === 'cone') { drawCone(); renderDeals(); } else if (view === 'reps') renderReps(); else drawHist();
}
$$('.dbc-call__head .dbc-call__seg, .dbc-call__conep .dbc-call__seg').forEach(g => radioGroup(g, v => {
  F[g.dataset.f] = v;
  if (g.dataset.f === 'team') fillRepSelect();
  if (g.dataset.f === 'range') drawCone(); else refresh();
}));
repSel.addEventListener('change', () => { F.rep = repSel.value; refresh(); });
root.addEventListener('keydown', e => { if (e.key === 'Escape') { hideTip(tip); markDeal(null); } });
onResize(cone, drawCone);
onResize(hist, drawHist);
fillRepSelect();
summary(); drawCone(); renderDeals();

css:
@property --dbc-room-score { syntax: '<number>'; inherits: true; initial-value: 0; }

.dbc-room {
  /* re-theme with these four */
  --dbc-room-bg: oklch(0.966 0.014 78);
  --dbc-room-ink: oklch(0.27 0.025 48);
  --dbc-room-accent: oklch(0.57 0.145 38);
  --dbc-room-good: oklch(0.56 0.09 150);
  /* derived */
  --dbc-room-card: color-mix(in oklch, var(--dbc-room-bg) 35%, white);
  --dbc-room-side: color-mix(in oklch, var(--dbc-room-bg) 93%, var(--dbc-room-ink));
  --dbc-room-line: color-mix(in oklch, var(--dbc-room-ink) 13%, transparent);
  --dbc-room-soft: color-mix(in oklch, var(--dbc-room-ink) 5.5%, transparent);
  --dbc-room-mute: color-mix(in oklch, var(--dbc-room-ink) 62%, var(--dbc-room-bg));
  --dbc-room-faint: color-mix(in oklch, var(--dbc-room-ink) 42%, var(--dbc-room-bg));
  --dbc-room-tint: color-mix(in oklch, var(--dbc-room-accent) 10%, var(--dbc-room-card));
  --dbc-room-warn: oklch(0.72 0.14 70);
  --dbc-room-bad: oklch(0.55 0.18 25);
  --dbc-room-s-champion: var(--dbc-room-good);
  --dbc-room-s-supporter: color-mix(in oklch, var(--dbc-room-good) 55%, var(--dbc-room-card));
  --dbc-room-s-neutral: color-mix(in oklch, var(--dbc-room-ink) 35%, var(--dbc-room-card));
  --dbc-room-s-skeptic: var(--dbc-room-warn);
  --dbc-room-s-blocker: var(--dbc-room-bad);
  --dbc-room-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbc-room-serif: ui-serif, "New York", Charter, Georgia, serif;
  --dbc-room-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbc-room-out: cubic-bezier(.16, 1, .3, 1);
  --dbc-room-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  width: 100%;
  height: var(--dbc-room-h, 680px);
  container-type: inline-size;
  container-name: dbc-room;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dbc-room-bg);
  color: var(--dbc-room-ink);
  font: 13px/1.45 var(--dbc-room-sans);
  accent-color: var(--dbc-room-accent);
  box-shadow: inset 0 0 0 1px var(--dbc-room-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, dl, dd, ul, ol, figure, table, fieldset) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(input, select, textarea) { font: inherit; color: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dbc-room-accent); outline-offset: 2px; border-radius: 6px; }
  & :where(.dbc-room__scroll) { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbc-room-ink) 22%, transparent) transparent; }
  & .dbc-room__num { font-variant-numeric: tabular-nums; }
  & .dbc-room__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

}
.dbc-room__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbc-room__shell { height: 100%; display: grid; grid-template-columns: 188px minmax(0, 1fr); grid-template-areas: "side main"; }

.dbc-room__side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 18px 12px 16px; background: var(--dbc-room-side); border-right: 1px solid var(--dbc-room-line); }
.dbc-room__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px;
  & svg { width: 28px; height: 28px; flex: none; fill: none; stroke: var(--dbc-room-accent); stroke-width: 2; }
  & b { display: block; font: 700 16px/1.1 var(--dbc-room-serif); letter-spacing: -.01em; }
  & small { display: block; font-size: 11px; color: var(--dbc-room-mute); }
}
.dbc-room__tabs {
  display: grid; gap: 2px;
  & [role=tab] {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dbc-room-mute); font-weight: 560; transition: background-color .2s, color .2s;
    &:hover { background: var(--dbc-room-soft); color: var(--dbc-room-ink); }
    &[aria-selected=true] { background: var(--dbc-room-card); color: var(--dbc-room-ink); font-weight: 650; box-shadow: 0 1px 0 var(--dbc-room-line); }
    &[aria-selected=true] .dbc-room__ic { color: var(--dbc-room-accent); }
  }
}
.dbc-room__team {
  margin-top: auto; padding: 12px 6px 0; border-top: 1px solid var(--dbc-room-line); display: grid; gap: 8px;
  & ul { display: grid; gap: 7px; }
  & li { display: grid; grid-template-columns: 26px 1fr; gap: 8px; align-items: center; font-size: 12px; line-height: 1.2; }
  & li b { display: block; font-weight: 620; }
  & li small { font-size: 11px; color: var(--dbc-room-mute); }
}
.dbc-room__cap, .dbc-room__h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-room-faint); }
.dbc-room__oav { width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; font-size: 10px; font-weight: 700; background: var(--dbc-room-ink); color: var(--dbc-room-bg); }

.dbc-room__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 16px 18px; }
.dbc-room__head {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto; grid-template-areas: "title facts score" "steps steps steps"; gap: 10px 22px; align-items: center;
}
.dbc-room__title {
  grid-area: title; min-width: 0;
  & h2 { font: 650 clamp(21px, 2.6cqi, 30px)/1.05 var(--dbc-room-serif); letter-spacing: -.02em; text-wrap: balance; }
}
.dbc-room__eyebrow { font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--dbc-room-accent); margin-bottom: 4px; }
.dbc-room__sub { font-size: 12px; color: var(--dbc-room-mute); margin-top: 4px; text-wrap: pretty; }
.dbc-room__facts {
  grid-area: facts; display: flex; gap: 20px;
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--dbc-room-faint); }
  & dd { font-size: 15px; font-weight: 700; letter-spacing: -.015em; white-space: nowrap; }
  & dd small { display: block; font-size: 11px; font-weight: 600; color: var(--dbc-room-bad); letter-spacing: 0; }
}
.dbc-room__score {
  grid-area: score; display: flex; align-items: center; gap: 10px;
  & p { display: grid; font-size: 12px; line-height: 1.25; } & p b { font-weight: 700; } & p span { color: var(--dbc-room-mute); max-width: 15ch; }
}
.dbc-room__ring {
  --dbc-room-score: 0;
  width: 54px; aspect-ratio: 1; border-radius: 50%; display: grid; place-items: center;
  background: radial-gradient(closest-side, var(--dbc-room-bg) 76%, transparent 77% 100%),
    conic-gradient(var(--dbc-room-sc, var(--dbc-room-good)) calc(var(--dbc-room-score) * 1%), var(--dbc-room-line) 0);
  transition: --dbc-room-score 1s var(--dbc-room-spring);
  & b { font-size: 17px; font-weight: 780; letter-spacing: -.04em; }
}
.dbc-room__steps {
  grid-area: steps; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px; counter-reset: dbc-room-s;
  & li { counter-increment: dbc-room-s; position: relative; padding: 7px 0 0; font-size: 11px; font-weight: 600; color: var(--dbc-room-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & li::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 4px; border-radius: 2px; background: var(--dbc-room-line); }
  & li.is-done { color: var(--dbc-room-mute); } & li.is-done::before { background: var(--dbc-room-ink); }
  & li.is-now { color: var(--dbc-room-accent); font-weight: 700; }
  & li.is-now::before { background: linear-gradient(90deg, var(--dbc-room-accent) 60%, color-mix(in oklch, var(--dbc-room-accent) 30%, transparent)); }
}

.dbc-room__body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 268px; gap: 12px; }
.dbc-room__views { min-height: 0; min-width: 0; border-radius: 14px; background: var(--dbc-room-card); box-shadow: inset 0 0 0 1px var(--dbc-room-line), 0 10px 30px -24px color-mix(in oklch, var(--dbc-room-ink) 50%, transparent); overflow: hidden; }
.dbc-room__view { position: relative; height: 100%; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dbc-room__view[hidden] { display: none; }
.dbc-room__v-act { grid-template-rows: auto auto minmax(0, 1fr); }
.dbc-room__bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 14px; padding: 10px 14px; border-bottom: 1px solid var(--dbc-room-line); }
.dbc-room__toggles {
  display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 12px; font-weight: 560;
  & label { display: inline-flex; align-items: center; gap: 6px; cursor: pointer; color: var(--dbc-room-mute); }
  & label:has(input:checked) { color: var(--dbc-room-ink); }
  & input { margin: 0; width: 14px; height: 14px; }
}
.dbc-room__legend {
  display: flex; flex-wrap: wrap; gap: 4px 10px; font-size: 11px; color: var(--dbc-room-mute);
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); }
}
.dbc-room__seg {
  display: inline-flex; flex-wrap: wrap; padding: 2px; border-radius: 9px; background: var(--dbc-room-soft);
  & [role=radio] { padding: 4px 10px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--dbc-room-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & [role=radio][aria-checked=true] { background: var(--dbc-room-card); color: var(--dbc-room-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbc-room-ink) 18%, transparent); }
}
.dbc-room__select {
  position: relative; display: inline-flex; align-items: center;
  & select { appearance: none; padding: 5px 28px 5px 10px; border-radius: 9px; background: var(--dbc-room-card); border: 1px solid var(--dbc-room-line); font-size: 12px; font-weight: 580; cursor: pointer; }
  & svg { position: absolute; right: 8px; width: 14px; height: 14px; pointer-events: none; fill: none; stroke: var(--dbc-room-mute); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}

/* map */
.dbc-room__mapwrap { min-height: 0; position: relative; }
.dbc-room__map { position: relative; height: 100%; min-width: 560px; min-height: 380px; }
.dbc-room__map svg { position: absolute; inset: 0; font-family: var(--dbc-room-sans); }
.dbc-room__org { fill: none; stroke: color-mix(in oklch, var(--dbc-room-ink) 28%, transparent); stroke-width: 1.3; transition: opacity .3s; }
.dbc-room__cov { fill: none; stroke: var(--dbc-room-accent); stroke-linecap: round; opacity: .32; transition: opacity .25s, stroke-width .25s; &.is-cold { stroke-dasharray: 3 5; } &.is-hot { opacity: .95; } }
.dbc-room__map.is-noorg .dbc-room__org, .dbc-room__map.is-nocov .dbc-room__cov { opacity: 0; }
.dbc-room__map.is-focus .dbc-room__cov:not(.is-hot) { opacity: .06; }
.dbc-room__node {
  --c: var(--dbc-room-s-neutral);
  cursor: pointer; outline: none; transition: opacity .3s;
  & .halo { fill: none; stroke: var(--dbc-room-accent); stroke-width: 2; opacity: 0; transition: opacity .2s; }
  & .disc { fill: color-mix(in oklch, var(--c) 16%, var(--dbc-room-card)); stroke: var(--c); stroke-width: 3; transition: fill .3s, stroke .3s; }
  & .ini { fill: color-mix(in oklch, var(--c) 45%, var(--dbc-room-ink)); font-size: 12px; font-weight: 750; text-anchor: middle; dominant-baseline: central; pointer-events: none; }
  & .nm { fill: var(--dbc-room-ink); font-size: 11.5px; font-weight: 650; text-anchor: middle; }
  & .tt { fill: var(--dbc-room-mute); font-size: 10.5px; text-anchor: middle; }
  & .lt { fill: var(--dbc-room-faint); font: 10px var(--dbc-room-mono); text-anchor: middle; }
  & .tag rect { fill: var(--dbc-room-ink); } & .tag text { fill: var(--dbc-room-bg); font-size: 8.5px; font-weight: 750; letter-spacing: .04em; text-anchor: middle; dominant-baseline: central; }
  &.is-cold .disc { stroke-dasharray: 4 3; }
  &.is-cold .lt { fill: var(--dbc-room-bad); font-weight: 650; }
  &:hover .halo, &:focus-visible .halo, &.is-sel .halo { opacity: 1; }
  &[data-s=champion] { --c: var(--dbc-room-s-champion); } &[data-s=supporter] { --c: var(--dbc-room-s-supporter); }
  &[data-s=skeptic] { --c: var(--dbc-room-s-skeptic); } &[data-s=blocker] { --c: var(--dbc-room-s-blocker); }
}
.dbc-room__map.is-coldonly .dbc-room__node:not(.is-cold):not(.is-ours) { opacity: .22; }
.dbc-room__ours {
  cursor: pointer; outline: none;
  & rect { fill: var(--dbc-room-ink); transition: fill .2s; }
  & text { fill: var(--dbc-room-bg); font-size: 10.5px; font-weight: 750; text-anchor: middle; dominant-baseline: central; }
  & .nm { fill: var(--dbc-room-ink); font-size: 11px; font-weight: 620; }
  &:hover rect, &:focus-visible rect { fill: var(--dbc-room-accent); }
}
.dbc-room__band { fill: color-mix(in oklch, var(--dbc-room-ink) 4%, transparent); }
.dbc-room__bandl { fill: var(--dbc-room-faint); font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.dbc-room__map svg.is-enter .dbc-room__node, .dbc-room__map svg.is-enter .dbc-room__ours { animation: dbc-room-pop .7s var(--dbc-room-spring) backwards; animation-delay: calc(var(--i) * 55ms + 100ms); transform-box: fill-box; transform-origin: 50% 30%; }
.dbc-room__map svg.is-enter .dbc-room__org, .dbc-room__map svg.is-enter .dbc-room__covg { animation: dbc-room-fade .9s var(--dbc-room-out) .6s backwards; }
@keyframes dbc-room-pop { from { opacity: 0; transform: scale(.6); } }
@keyframes dbc-room-fade { from { opacity: 0; } }

/* drawer */
.dbc-room__drawer {
  position: absolute; top: 52px; right: 10px; bottom: 10px; z-index: 5; width: min(300px, calc(100% - 20px));
  display: flex; flex-direction: column; gap: 10px; padding: 14px; overflow: auto; scrollbar-width: thin;
  border-radius: 14px; background: color-mix(in oklch, var(--dbc-room-card) 94%, transparent); backdrop-filter: blur(6px);
  box-shadow: 0 0 0 1px var(--dbc-room-line), 0 24px 48px -20px color-mix(in oklch, var(--dbc-room-ink) 45%, transparent);
  transition: opacity .25s, translate .45s var(--dbc-room-out), display .45s allow-discrete;
  @starting-style { opacity: 0; translate: 24px 0; }
  &[hidden] { display: none; opacity: 0; translate: 24px 0; }
  & header { display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; gap: 10px; align-items: center; }
  & .av { width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; font-weight: 750; background: color-mix(in oklch, var(--c) 18%, var(--dbc-room-card)); box-shadow: inset 0 0 0 3px var(--c); }
  & h4 { font-size: 14.5px; font-weight: 720; letter-spacing: -.01em; line-height: 1.2; }
  & header p { font-size: 11.5px; color: var(--dbc-room-mute); line-height: 1.3; }
  & dl { display: grid; gap: 8px; font-size: 12px; }
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-room-faint); }
  & dd { text-wrap: pretty; }
  & .touches { display: grid; gap: 5px; font-size: 12px; }
  & .touches li { display: grid; grid-template-columns: 46px 1fr; gap: 6px; }
  & .touches time { font: 10.5px var(--dbc-room-mono); color: var(--dbc-room-faint); padding-top: 1px; }
}
.dbc-room__stance {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 3px;
  & [role=radio] { --c: var(--dbc-room-s-neutral); padding: 5px 0; border-radius: 7px; font-size: 10.5px; font-weight: 650; text-align: center; color: var(--dbc-room-mute); background: var(--dbc-room-soft); transition: background-color .2s, color .2s, box-shadow .2s; }
  & [data-v=champion] { --c: var(--dbc-room-s-champion); } & [data-v=supporter] { --c: var(--dbc-room-s-supporter); } & [data-v=skeptic] { --c: var(--dbc-room-s-skeptic); } & [data-v=blocker] { --c: var(--dbc-room-s-blocker); }
  & [role=radio][aria-checked=true] { background: color-mix(in oklch, var(--c) 22%, var(--dbc-room-card)); color: var(--dbc-room-ink); box-shadow: inset 0 0 0 1.5px var(--c); }
}
.dbc-room__x { width: 26px; height: 26px; display: grid; place-items: center; border-radius: 8px; color: var(--dbc-room-mute); &:hover { background: var(--dbc-room-soft); color: var(--dbc-room-ink); } & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; } }

/* plan: rows share the parent's columns through subgrid */
.dbc-room__planhead { font-size: 12px; color: var(--dbc-room-mute); & b { color: var(--dbc-room-ink); } & .is-late { color: var(--dbc-room-bad); font-weight: 650; } }
.dbc-room__plan {
  --dbc-room-tl: 1;
  min-height: 0; display: grid; grid-template-columns: 28px minmax(140px, 1fr) 84px 54px minmax(180px, 42%); align-content: start; column-gap: 10px; padding: 0 14px 10px;
  position: relative;
}
.dbc-room__prow {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; min-height: 36px; border-bottom: 1px solid var(--dbc-room-soft);
  transition: opacity .3s;
  &.is-head { position: sticky; top: 0; z-index: 2; background: var(--dbc-room-card); min-height: 30px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-room-faint); }
  & input { margin: 0; width: 16px; height: 16px; cursor: pointer; }
  & .t { min-width: 0; font-weight: 600; line-height: 1.25; }
  & .t small { display: block; font-size: 11px; font-weight: 400; color: var(--dbc-room-mute); }
  & .o { font-size: 11px; font-weight: 650; padding: 2px 7px; border-radius: 99px; justify-self: start; white-space: nowrap; }
  & .o.is-us { background: var(--dbc-room-ink); color: var(--dbc-room-bg); }
  & .o.is-them { background: var(--dbc-room-tint); color: var(--dbc-room-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-room-accent) 35%, transparent); }
  & .d { font: 11.5px var(--dbc-room-mono); font-variant-numeric: tabular-nums; color: var(--dbc-room-mute); }
  & .tl { position: relative; height: 100%; min-height: 26px; }
