    s += '<g class="dbc-room__wg" style="--i:' + k + '" data-k="' + k + '"><rect x="' + (cx - band / 2) + '" y="' + M.t + '" width="' + band + '" height="' + ih + '" fill="transparent"/>';
    s += '<rect class="dbc-room__wb is-out" x="' + (cx - bw / 2) + '" y="' + Y(x.out) + '" width="' + bw + '" height="' + (Y(0) - Y(x.out)) + '" rx="2"/>';
    s += '<rect class="dbc-room__wb is-in" x="' + (cx - bw / 2) + '" y="' + Y(x.out + x.in) + '" width="' + bw + '" height="' + (Y(x.out) - Y(x.out + x.in)) + '" rx="2"/></g>';
    s += '<text class="dbc-room__ax" x="' + cx + '" y="' + (h - 5) + '" text-anchor="middle">' + dtx(d) + '</text>';
  });
  weeksEl.innerHTML = s + '</svg>'; weeksEntered = true;
  weeksEl._wk = wk;
}
weeksEl.addEventListener('pointermove', e => {
  const g = e.target.closest('.dbc-room__wg'); if (!g || !weeksEl._wk) { hideTip(tip); return; }
  const k = +g.dataset.k, x = weeksEl._wk[k], d = new Date(W0.getTime() + k * 7 * DAY);
  tip.innerHTML = '<b>Week of ' + dtx(d) + '</b><span>' + x.in + ' initiated by Ashgrove · ' + x.out + ' by Oriel</span>'; placeTip(tip, e.clientX, e.clientY);
});
weeksEl.addEventListener('pointerleave', () => hideTip(tip));
function renderFeed() {
  const list = ACT.filter(actIn).slice().reverse();
  feed.innerHTML = list.length ? list.map(x => '<li><time>' + dtx(x.d) + '</time><span class="ty' + (x.dir === 'in' ? ' is-in' : '') + '" title="' + x.ty + (x.dir === 'in' ? ', from Ashgrove' : '') + '"><svg viewBox="0 0 24 24" aria-hidden="true">' + TICON[x.ty] + '</svg></span><span><b>' + esc(x.title) + '</b><small>' +
    x.them.map(t => esc(P[t].n)).join(', ') + ' · with ' + x.us.map(u => esc(US[u].n.split(' ')[0])).join(', ') + '</small></span></li>').join('') : '<li><span class="empty">No activity of this type with this person.</span></li>';
}

/* ------------------------------------------------------------------ views */
function showView(v) {
  S.view = v; hideTip(tip);
  $$('.dbc-room__view').forEach(s => { s.hidden = s.dataset.view !== v; });
  if (v === 'people') drawMap(); else if (v === 'plan') renderPlan(); else { drawWeeks(); renderFeed(); }
}
tabs($('.dbc-room__tabs'), showView);
$$('.dbc-room__seg').forEach(g => radioGroup(g, v => { S[g.dataset.f] = v; if (g.dataset.f === 'planf') renderPlan(); else { drawWeeks(); renderFeed(); } }));
whoSel.addEventListener('change', () => { S.who = whoSel.value; drawWeeks(); renderFeed(); });
root.addEventListener('keydown', e => { if (e.key === 'Escape') { if (!closeDrawer()) hideTip(tip); } });
onResize(map, drawMap);
onResize(weeksEl, drawWeeks);
onResize(planEl, () => placeVLines(projected()));
summary(); drawMap();

css:
.dbc-activity {
  /* re-theme with these four (keep them in oklch: the canvas ramps are interpolated from them) */
  --dbc-activity-bg: oklch(0.983 0.006 195);
  --dbc-activity-ink: oklch(0.24 0.03 215);
  --dbc-activity-cool: oklch(0.46 0.1 205);
  --dbc-activity-warm: oklch(0.66 0.17 48);
  /* derived */
  --dbc-activity-card: color-mix(in oklch, var(--dbc-activity-bg) 35%, white);
  --dbc-activity-well: color-mix(in oklch, var(--dbc-activity-ink) 4%, var(--dbc-activity-bg));
  --dbc-activity-line: color-mix(in oklch, var(--dbc-activity-ink) 12%, transparent);
  --dbc-activity-rule: color-mix(in oklch, var(--dbc-activity-ink) 7%, transparent);
  --dbc-activity-mute: color-mix(in oklch, var(--dbc-activity-ink) 64%, var(--dbc-activity-bg));
  --dbc-activity-faint: color-mix(in oklch, var(--dbc-activity-ink) 44%, var(--dbc-activity-bg));
  --dbc-activity-tint: color-mix(in oklab, var(--dbc-activity-cool) 10%, transparent);
  --dbc-activity-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbc-activity-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbc-activity-out: cubic-bezier(.16, 1, .3, 1);
  --dbc-activity-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.6%, 1.053 22.6%, 1.061 25.8%, 1.045 30.4%, 1.012 39.3%, 0.995 49.7%, 1);
  width: 100%;
  height: var(--dbc-activity-h, 680px);
  container-type: inline-size; container-name: dbc-activity;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dbc-activity-bg);
  color: var(--dbc-activity-ink);
  font: 13px/1.45 var(--dbc-activity-sans);
  accent-color: var(--dbc-activity-cool);
  box-shadow: inset 0 0 0 1px var(--dbc-activity-line);
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, table) { margin: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbc-activity-cool); outline-offset: 2px; border-radius: 6px; }
}
.dbc-activity__ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbc-activity__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.dbc-activity__eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-activity-faint); }
.dbc-activity__shell { height: 100%; display: grid; grid-template-columns: 184px minmax(0, 1fr); }

/* ------------------------------------------------------------------ sidebar */
.dbc-activity__side {
  display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px; min-height: 0;
  border-right: 1px solid var(--dbc-activity-line); background: var(--dbc-activity-well);
}
.dbc-activity__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; flex: none; background: var(--dbc-activity-ink); fill: none; stroke: var(--dbc-activity-bg); stroke-width: 2.2; stroke-linecap: round; }
  & b { display: block; font-size: 14px; font-weight: 760; letter-spacing: -.01em; }
  & small { display: block; font-size: 11px; color: var(--dbc-activity-mute); white-space: nowrap; }
}
.dbc-activity__nav { display: grid; gap: 2px; }
.dbc-activity__item {
  display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; font-weight: 600; color: var(--dbc-activity-mute); white-space: nowrap;
  transition: background-color .2s, color .2s;
  &:hover { color: var(--dbc-activity-ink); background: color-mix(in oklch, var(--dbc-activity-ink) 5%, transparent); }
  &[aria-current="page"] { color: var(--dbc-activity-ink); background: var(--dbc-activity-card); box-shadow: 0 0 0 1px var(--dbc-activity-line), 0 1px 2px color-mix(in oklch, var(--dbc-activity-ink) 7%, transparent); }
  &[aria-current="page"] .dbc-activity__ic { color: var(--dbc-activity-cool); }
}
.dbc-activity__pods {
  display: grid; gap: 2px;
  & .dbc-activity__eyebrow { padding: 0 10px 4px; }
  & button { display: flex; align-items: center; gap: 9px; padding: 6px 10px; border-radius: 8px; font-size: 12.5px; font-weight: 580; color: var(--dbc-activity-mute); text-align: left; transition: background-color .2s, color .2s; }
  & button::before { content: ""; width: 12px; height: 12px; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--dbc-activity-faint); transition: box-shadow .25s var(--dbc-activity-spring); }
  & button:hover { color: var(--dbc-activity-ink); }
  & button[aria-checked="true"] { color: var(--dbc-activity-ink); font-weight: 650; }
  & button[aria-checked="true"]::before { box-shadow: inset 0 0 0 4px var(--dbc-activity-cool); }
}
.dbc-activity__foot { margin-top: auto; padding: 0 6px; font-size: 11px; line-height: 1.45; color: var(--dbc-activity-faint); text-wrap: pretty; }

/* ------------------------------------------------------------------ main */
.dbc-activity__main {
  min-width: 0; min-height: 0; padding: 14px 16px 14px;
  display: grid; gap: 10px;
  grid-template-rows: auto auto 226px minmax(0, 1fr);
}
.dbc-activity__head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap;
  & h2 { font-size: clamp(17px, 2cqi, 22px); font-weight: 760; letter-spacing: -.028em; line-height: 1.15; text-wrap: balance; margin-top: 2px; }
}
.dbc-activity__metric {
  display: flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--dbc-activity-well); box-shadow: inset 0 0 0 1px var(--dbc-activity-rule);
  & button { height: 28px; padding: 0 11px; border-radius: 7px; font-size: 12.5px; font-weight: 620; color: var(--dbc-activity-mute); white-space: nowrap; transition: color .2s, background-color .2s, box-shadow .2s; }
  & button:hover { color: var(--dbc-activity-ink); }
  & button[aria-checked="true"] { color: var(--dbc-activity-ink); background: var(--dbc-activity-card); box-shadow: 0 0 0 1px var(--dbc-activity-line), 0 1px 2px color-mix(in oklch, var(--dbc-activity-ink) 8%, transparent); }
}
.dbc-activity__kpis {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0;
  & > div { padding: 2px 14px 2px 0; min-width: 0; animation: dbc-activity-rise .6s var(--dbc-activity-out) both; animation-delay: calc(var(--i) * 50ms); }
  & > div + div { padding-left: 14px; border-left: 1px solid var(--dbc-activity-line); }
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--dbc-activity-faint); white-space: nowrap; }
  & dd { display: flex; align-items: baseline; gap: 8px; font-size: clamp(18px, 2.1cqi, 24px); font-weight: 760; letter-spacing: -.035em; font-variant-numeric: tabular-nums; line-height: 1.25; white-space: nowrap; }
  & dd small { font-size: 11px; font-weight: 650; letter-spacing: 0; padding: 1px 5px; border-radius: 5px; color: var(--dbc-activity-mute); background: var(--dbc-activity-rule); }
  & dd small.up { color: color-mix(in oklab, var(--dbc-activity-cool) 85%, black); background: var(--dbc-activity-tint); }
  & dd small.dn { color: color-mix(in oklab, var(--dbc-activity-warm) 80%, black); background: color-mix(in oklab, var(--dbc-activity-warm) 12%, transparent); }
}

/* ------------------------------------------------------------------ panels */
.dbc-activity__heat, .dbc-activity__punch, .dbc-activity__reps, .dbc-activity__card {
  min-width: 0; min-height: 0; border-radius: 12px; background: var(--dbc-activity-card); box-shadow: 0 0 0 1px var(--dbc-activity-line);
}
.dbc-activity__ph {
  display: flex; align-items: center; gap: 6px 12px; padding: 9px 14px 4px; font-size: 11.5px; color: var(--dbc-activity-faint); flex-wrap: wrap; min-width: 0;
  & > b { font-size: 12.5px; font-weight: 700; color: var(--dbc-activity-ink); white-space: nowrap; }
}
.dbc-activity__heat { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; animation: dbc-activity-rise .6s var(--dbc-activity-out) .08s both; }
.dbc-activity__brushlbl { font-variant-numeric: tabular-nums; }
.dbc-activity__presets {
  margin-left: auto; display: flex; gap: 2px;
  & button { height: 24px; padding: 0 8px; border-radius: 6px; font: 650 11px/1 var(--dbc-activity-mono); color: var(--dbc-activity-mute); transition: background-color .2s, color .2s; }
  & button:hover { background: var(--dbc-activity-well); color: var(--dbc-activity-ink); }
  & button[aria-pressed="true"] { background: var(--dbc-activity-ink); color: var(--dbc-activity-bg); }
}
.dbc-activity__hs { min-height: 0; overflow-x: auto; overflow-y: hidden; scrollbar-width: thin; scrollbar-color: var(--dbc-activity-line) transparent; padding: 0 8px; }
.dbc-activity__hw { position: relative; height: 100%; min-width: 620px; }
.dbc-activity__cv, .dbc-activity__ov { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.dbc-activity__ov { cursor: crosshair; touch-action: pan-y; &:focus-visible { outline-offset: -2px; } &.is-move { cursor: grabbing; } &.is-edge { cursor: ew-resize; } }
.dbc-activity__scale {
  display: flex; align-items: center; justify-content: flex-end; gap: 8px; padding: 2px 14px 8px; font-size: 10.5px; color: var(--dbc-activity-faint); font-variant-numeric: tabular-nums;
  & i { width: 120px; height: 7px; border-radius: 4px; background: linear-gradient(to right, var(--r0, var(--dbc-activity-well)), var(--r1, var(--dbc-activity-cool))); }
}

/* ------------------------------------------------------------------ views */
.dbc-activity__view {
  min-height: 0; min-width: 0;
  transition: opacity .35s var(--dbc-activity-out), translate .5s var(--dbc-activity-out);
  @starting-style { opacity: 0; translate: 0 8px; }
  &[hidden] { display: none; }
}
.dbc-activity__pv { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.12fr); gap: 10px; }
.dbc-activity__punch { display: grid; grid-template-rows: auto minmax(0, 1fr); animation: dbc-activity-rise .6s var(--dbc-activity-out) .16s both; }
.dbc-activity__pw { position: relative; min-height: 0; margin: 0 8px 6px; }
.dbc-activity__psvg {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; font-family: var(--dbc-activity-sans); font-variant-numeric: tabular-nums;
  & .ax { fill: var(--dbc-activity-faint); font-size: 10.5px; }
  & .ax.d { fill: var(--dbc-activity-mute); font-weight: 650; }
  & .gl { stroke: var(--dbc-activity-rule); }
  & .pc { cursor: pointer; }
  & .pc circle.b { transition: r .6s var(--dbc-activity-spring), fill .4s; stroke: color-mix(in oklch, var(--dbc-activity-ink) 18%, transparent); stroke-width: .75; }
  & .pc rect { fill: transparent; }
  & .pc:hover circle.b, & .pc.hv circle.b { stroke: var(--dbc-activity-ink); stroke-width: 1.5; }
  & .rk circle { fill: var(--dbc-activity-ink); }
  & .rk text { fill: var(--dbc-activity-bg); font-size: 9.5px; font-weight: 750; text-anchor: middle; dominant-baseline: central; }
  & .rk { transition: opacity .3s, transform .6s var(--dbc-activity-spring); }
}
.dbc-activity__psvg.is-enter .pc circle.b { animation: dbc-activity-pop .6s var(--dbc-activity-spring) both; animation-delay: calc(var(--i) * 9ms + .3s); transform-box: fill-box; transform-origin: center; }
.dbc-activity__reps { display: grid; min-height: 0; overflow: hidden; animation: dbc-activity-rise .6s var(--dbc-activity-out) .22s both; }
.dbc-activity__tw { overflow: auto; min-height: 0; scrollbar-width: thin; scrollbar-color: var(--dbc-activity-line) transparent; }
.dbc-activity__tbl {
  width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbc-activity-card); text-align: left; padding: 9px 8px 6px; font-size: 10px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--dbc-activity-faint); white-space: nowrap; box-shadow: inset 0 -1px 0 var(--dbc-activity-line); }
  & th button { font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; display: inline-flex; gap: 3px; }
  & th button:hover, & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dbc-activity-ink); }
  & th[aria-sort="ascending"] button::after { content: "↑"; }
  & th[aria-sort="descending"] button::after { content: "↓"; }
  & .r { text-align: right; }
  & td { padding: 6px 8px; border-bottom: 1px solid var(--dbc-activity-rule); white-space: nowrap; }
  & th:first-child, & td:first-child { padding-left: 12px; width: 30px; }
  & th:last-child, & td:last-child { padding-right: 12px; }
  & tbody tr { cursor: pointer; transition: background-color .2s; }
  & tbody tr:hover { background: color-mix(in oklch, var(--dbc-activity-ink) 3%, transparent); }
  & tbody tr[aria-selected="true"] { background: var(--dbc-activity-tint); }
  & tbody tr:focus-visible { outline-offset: -2px; border-radius: 0; }
  & tbody tr.is-dim td:not(:first-child) { opacity: .45; }
  & b { font-weight: 650; }
  & small { margin-left: 6px; font-size: 10px; font-weight: 700; letter-spacing: .06em; color: var(--dbc-activity-faint); }
  & .rate { font-weight: 650; }
}
.dbc-activity__ck { appearance: none; margin: 0; width: 15px; height: 15px; border-radius: 4px; display: grid; place-items: center; box-shadow: inset 0 0 0 1.5px var(--dbc-activity-faint); pointer-events: none; transition: background-color .2s, box-shadow .2s;
  &::after { content: ""; width: 4px; height: 8px; margin-top: -2px; border: solid var(--dbc-activity-bg); border-width: 0 2px 2px 0; rotate: 45deg; scale: 0; transition: scale .3s var(--dbc-activity-spring); }
  &:checked { background: var(--dbc-activity-cool); box-shadow: none; }
  &:checked::after { scale: 1; }
}
.dbc-activity__spark { display: block; width: 84px; height: 20px; overflow: visible;
  & polyline { fill: none; stroke: var(--dbc-activity-cool); stroke-width: 1.4; stroke-linejoin: round; stroke-linecap: round; }
  & path { fill: var(--dbc-activity-tint); }
}

/* rep grid view: small multiples */
.dbc-activity__rv { overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbc-activity-line) transparent; }
.dbc-activity__grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(196px, 1fr)); gap: 10px; }
.dbc-activity__card {
  display: grid; gap: 6px; padding: 10px 12px 10px; text-align: left; transition: box-shadow .2s, translate .3s var(--dbc-activity-spring);
  animation: dbc-activity-rise .5s var(--dbc-activity-out) both; animation-delay: calc(var(--i) * 40ms);
  &:hover { translate: 0 -2px; box-shadow: 0 0 0 1px var(--dbc-activity-line), 0 10px 22px -12px color-mix(in oklch, var(--dbc-activity-ink) 40%, transparent); }
  &[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--dbc-activity-cool); }
  & header { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
  & b { font-weight: 700; font-size: 13px; }
  & header small { font-size: 10px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--dbc-activity-faint); }
  & canvas { width: 100%; height: 50px; display: block; border-radius: 4px; }
  & dl { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; font-variant-numeric: tabular-nums; }
  & dt { font-size: 9.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--dbc-activity-faint); }
  & dd { font-size: 14px; font-weight: 720; letter-spacing: -.02em; }
}

/* ------------------------------------------------------------------ tooltip */
.dbc-activity__tip {
  position: absolute; left: 0; top: 0; z-index: 80; pointer-events: none; min-width: 168px; padding: 8px 11px; border-radius: 10px;
  background: var(--dbc-activity-ink); color: var(--dbc-activity-bg); font-size: 12px; line-height: 1.55; font-variant-numeric: tabular-nums;
  box-shadow: 0 12px 30px -10px color-mix(in oklch, var(--dbc-activity-ink) 60%, transparent);
  opacity: 0; scale: .96; transition: opacity .12s, scale .2s var(--dbc-activity-out);
  & b { display: block; margin-bottom: 2px; }
  & span { display: flex; justify-content: space-between; gap: 16px; color: color-mix(in oklch, var(--dbc-activity-bg) 70%, transparent); }
  & em { font-style: normal; font-weight: 650; color: var(--dbc-activity-bg); }
  &.on { opacity: 1; scale: 1; }
}

@keyframes dbc-activity-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbc-activity-pop { from { transform: scale(0); } }

/* ------------------------------------------------------------------ responsive */
@container dbc-activity (width < 960px) {
  .dbc-activity__shell { grid-template-columns: 60px minmax(0, 1fr); }
  .dbc-activity__side { align-items: center; padding: 16px 8px; }
  .dbc-activity__side .dbc-activity__lbl { display: none; }
  .dbc-activity__brand { padding: 0; }
  .dbc-activity__item { padding: 10px; }
  .dbc-activity__main { overflow: auto; scrollbar-width: thin; grid-template-rows: auto auto 226px auto; align-content: start; }
  .dbc-activity__pv { grid-template-columns: minmax(0, 1fr); }
  .dbc-activity__punch { height: 280px; }
  .dbc-activity__tw { max-height: 360px; }
}
@container dbc-activity (width < 760px) {
  .dbc-activity__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dbc-activity__side { flex-direction: row; align-items: center; gap: 8px; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbc-activity-line); }
  .dbc-activity__nav { display: flex; }
  .dbc-activity__item { padding: 7px 9px; }
  .dbc-activity__side .dbc-activity__pods { display: flex; margin-left: auto; gap: 0; padding: 2px; border-radius: 9px; background: var(--dbc-activity-card); box-shadow: inset 0 0 0 1px var(--dbc-activity-line); }
  .dbc-activity__pods .dbc-activity__eyebrow { display: none; }
  .dbc-activity__pods button { padding: 5px 8px; font-size: 12px; border-radius: 7px; }
  .dbc-activity__pods button::before { display: none; }
  .dbc-activity__pods button[aria-checked="true"] { background: var(--dbc-activity-ink); color: var(--dbc-activity-bg); }
  .dbc-activity__main { padding: 12px; }
  .dbc-activity__kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px 0; & > div:nth-child(4) { border-left: 0; padding-left: 0; } }
  .dbc-activity__brushlbl { display: none; }
}
@container dbc-activity (width < 480px) {
  .dbc-activity__metric { width: 100%; & button { flex: 1; padding: 0 4px; font-size: 11.5px; } }
  .dbc-activity__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); & > div:nth-child(odd) { border-left: 0; padding-left: 0; } & > div:nth-child(4) { border-left: 1px solid var(--dbc-activity-line); padding-left: 14px; } }
  .dbc-activity__pods button { padding: 5px 6px; }
  .dbc-activity__tbl .c-m100, .dbc-activity__tbl td:nth-child(6), .dbc-activity__tbl .c-spark, .dbc-activity__tbl td:nth-child(7) { display: none; }
  .dbc-activity__item .dbc-activity__ic { width: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .dbc-activity__kpis > div, .dbc-activity__heat, .dbc-activity__punch, .dbc-activity__reps, .dbc-activity__card, .dbc-activity__psvg.is-enter .pc circle.b { animation: none; }
  .dbc-activity__view, .dbc-activity__psvg .pc circle.b, .dbc-activity__psvg .rk, .dbc-activity__ck::after, .dbc-activity__card, .dbc-activity__pods button::before { transition-duration: .01s; }
