.dbc-winloss {
  /* re-theme with these four */
  --dbc-winloss-bg: oklch(0.195 0.006 255);
  --dbc-winloss-ink: oklch(0.95 0.008 250);
  --dbc-winloss-win: oklch(0.82 0.13 168);
  --dbc-winloss-loss: oklch(0.72 0.16 28);
