  --dbc-winloss-raise: color-mix(in oklab, var(--dbc-winloss-ink) 9%, var(--dbc-winloss-bg));
  --dbc-winloss-line: color-mix(in oklab, var(--dbc-winloss-ink) 13%, transparent);
  --dbc-winloss-rule: color-mix(in oklab, var(--dbc-winloss-ink) 7%, transparent);
  --dbc-winloss-mute: color-mix(in oklab, var(--dbc-winloss-ink) 66%, var(--dbc-winloss-bg));
  --dbc-winloss-faint: color-mix(in oklab, var(--dbc-winloss-ink) 44%, var(--dbc-winloss-bg));
  --dbc-winloss-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbc-winloss-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbc-winloss-out: cubic-bezier(.16, 1, .3, 1);
  --dbc-winloss-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.6%, 1.053 22.6%, 1.061 25.8%, 1.045 30.4%, 1.012 39.3%, 0.995 49.7%, 1);
  width: 100%;
  height: var(--dbc-winloss-h, 680px);
  container-type: inline-size; container-name: dbc-winloss;
  position: relative; isolation: isolate; overflow: hidden;
  display: grid; grid-template-rows: auto auto auto minmax(0, 1fr);
  border-radius: 16px;
  background: var(--dbc-winloss-bg);
  color: var(--dbc-winloss-ink);
  font: 13px/1.45 var(--dbc-winloss-sans);
  accent-color: var(--dbc-winloss-win);
  color-scheme: dark;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p, dl, dd, ul, figure, table) { margin: 0; }
  & :where(ul) { padding: 0; list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbc-winloss-ink); outline-offset: 2px; border-radius: 6px; }
}
.dbc-winloss__ic { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
