  display: flex; align-items: center; gap: 10px; flex: none;
  & svg { width: 30px; height: 30px; padding: 4px; border-radius: 9px; flex: none; fill: none; stroke: var(--dbc-winloss-bg); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; background: linear-gradient(135deg, var(--dbc-winloss-win), color-mix(in oklab, var(--dbc-winloss-win) 55%, var(--dbc-winloss-loss))); }
