/* reasons */
.dbc-winloss__why { display: grid; grid-template-rows: auto auto; align-content: start; gap: 4px; padding: 10px 0 8px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbc-winloss-line) transparent; }
.dbc-winloss__wg {
  & h3 { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding: 2px 14px 6px; font-size: 12.5px; font-weight: 700; }
  & h3 small { font-size: 11px; font-weight: 550; color: var(--dbc-winloss-faint); font-variant-numeric: tabular-nums; }
  & + .dbc-winloss__wg { padding-top: 8px; border-top: 1px solid var(--dbc-winloss-rule); }
  &[data-o="won"] { --k: var(--dbc-winloss-win); }
  &[data-o="lost"] { --k: var(--dbc-winloss-loss); }
}
.dbc-winloss__rr {
  width: 100%; display: grid; grid-template-columns: minmax(0, 1fr) 38px 34px; align-items: center; gap: 2px 8px; padding: 4px 14px; text-align: left; font-variant-numeric: tabular-nums;
  transition: background-color .2s;
