  & .n { font-size: 12px; font-weight: 580; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .c { font-size: 11.5px; color: var(--dbc-winloss-mute); text-align: right; }
  & .p { font-size: 12px; font-weight: 700; text-align: right; }
  & .bar { grid-column: 1 / -1; height: 5px; border-radius: 3px; background: var(--dbc-winloss-rule); overflow: hidden; }
  & .bar i { display: block; height: 100%; border-radius: inherit; background: var(--k); transform-origin: 0 50%; transform: scaleX(var(--v, 0)); transition: transform .7s var(--dbc-winloss-spring); }
  &.zero { opacity: .45; }
}
.dbc-winloss__why:has(.dbc-winloss__rr[aria-pressed="true"]) .dbc-winloss__rr:not([aria-pressed="true"]) { opacity: .6; }

/* ------------------------------------------------------------------ head-to-head */
.dbc-winloss__hv { display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(250px, 1fr); gap: 12px; }
.dbc-winloss__h2h { overflow: hidden; display: grid; }
.dbc-winloss__tw { overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbc-winloss-line) transparent; }
.dbc-winloss__tbl {
  width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; background: var(--dbc-winloss-panel); text-align: left; padding: 11px 12px 8px; font-size: 10px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--dbc-winloss-faint); white-space: nowrap; box-shadow: inset 0 -1px 0 var(--dbc-winloss-line); }
  & th button { font: inherit; letter-spacing: inherit; text-transform: inherit; color: inherit; display: inline-flex; gap: 3px; }
  & th button:hover, & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dbc-winloss-ink); }
  & th[aria-sort="ascending"] button::after { content: "↑"; }
  & th[aria-sort="descending"] button::after { content: "↓"; }
  & .r { text-align: right; }
  & td { padding: 10px 12px; border-bottom: 1px solid var(--dbc-winloss-rule); white-space: nowrap; }
  & tbody tr { cursor: pointer; transition: background-color .2s; }
  & tbody tr:hover { background: var(--dbc-winloss-rule); }
