}
.dbc-winloss__wr {
  display: flex; align-items: center; gap: 8px; min-width: 150px;
  & span { flex: 1; display: flex; height: 8px; border-radius: 4px; overflow: hidden; background: color-mix(in oklab, var(--dbc-winloss-loss) 55%, transparent); }
  & span i { background: var(--dbc-winloss-win); width: calc(var(--v) * 100%); transition: width .7s var(--dbc-winloss-spring); }
