    background: color-mix(in oklab, color-mix(in oklab, var(--dbc-winloss-win) var(--v), var(--dbc-winloss-loss)) calc(var(--a) * 34%), transparent);
    box-shadow: inset 0 0 0 1px color-mix(in oklab, color-mix(in oklab, var(--dbc-winloss-win) var(--v), var(--dbc-winloss-loss)) calc(var(--a) * 60%), transparent);
