}
.dbc-winloss__det { padding: 14px 14px 12px; display: grid; align-content: start; gap: 6px; overflow: auto;
  & h3 { font-size: 17px; font-weight: 760; letter-spacing: -.02em; line-height: 1.2; text-wrap: balance; }
}
.dbc-winloss__dl { margin-top: 10px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-winloss-faint); }
.dbc-winloss__trend {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; align-items: end; height: 120px; margin-top: 8px; padding-bottom: 18px; position: relative;
  border-bottom: 1px solid var(--dbc-winloss-line);
