/* ------------------------------------------------------------------ tooltip */
.dbc-winloss__tip {
  position: absolute; left: 0; top: 0; z-index: 80; pointer-events: none; min-width: 190px; padding: 9px 11px; border-radius: 10px;
  background: var(--dbc-winloss-ink); color: var(--dbc-winloss-bg); font-size: 12px; line-height: 1.5; font-variant-numeric: tabular-nums;
