  .dbc-winloss__body { padding: 0 12px 12px; }
  .dbc-winloss__tbl .c-cyc, .dbc-winloss__tbl td:nth-child(5), .dbc-winloss__tbl .c-disc, .dbc-winloss__tbl td:nth-child(6) { display: none; }
  .dbc-winloss__cap span { margin-left: 0; }
}
@container dbc-winloss (width < 480px) {
  .dbc-winloss__brand span { display: none; }
  .dbc-winloss__period button { padding: 0 8px; }
  .dbc-winloss__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); & > div:nth-child(odd) { padding-left: 0; border-left: 0; } & > div:nth-child(4) { padding-left: 14px; border-left: 1px solid var(--dbc-winloss-line); } }
  .dbc-winloss__tbl .c-won, .dbc-winloss__tbl td:nth-child(4) { display: none; }
  .dbc-winloss__wr { min-width: 110px; }
