}

@media (prefers-reduced-motion: reduce) {
  .dbc-winloss__kpis > div, .dbc-winloss__trend i, .dbc-winloss__lr li { animation: none; }
  .dbc-winloss__svg .dot, .dbc-winloss__svg .med, .dbc-winloss__rr .bar i, .dbc-winloss__wr span i, .dbc-winloss__view { transition: none; }
}

