const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
function rng(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const R = rng(15);
const gauss = () => Math.sqrt(-2 * Math.log(1 - R())) * Math.cos(2 * Math.PI * R());
const pickW = obj => { const e = Object.entries(obj), t = e.reduce((s, [, w]) => s + w, 0); let x = R() * t; for (const [k, w] of e) { if ((x -= w) <= 0) return k; } return e[e.length - 1][0]; };
const km = v => v >= 1000 ? '$' + (v / 1000).toFixed(2) + 'M' : '$' + (v < 10 ? v.toFixed(1) : Math.round(v)) + 'k';   // amounts are in $k
const pc = v => Math.round(v * 100) + '%';

/* ------------------------------------------------------------------ 152 closed deals over four quarters */
const QS = ['Q4 FY25', 'Q1 FY26', 'Q2 FY26', 'Q3 FY26'];
const SEG = { smb: { n: 'SMB', med: 22, sd: .42, w: .4, adj: .08, cyc: 26 }, mid: { n: 'Mid-market', med: 72, sd: .38, w: .36, adj: 0, cyc: 58 }, ent: { n: 'Enterprise', med: 250, sd: .48, w: .24, adj: -.1, cyc: 112 } };
const COMP = {
  bas: { n: 'Bastion Cloud', w: .3, wr: .42, loss: { price: 5, feature: 1.5, incumbent: 1.5, timing: 1, security: .5 }, win: { acc: 4, dep: 2, sup: 2, int: 1.5, cha: 1.5, val: .5 } },
  iro: { n: 'Ironleaf', w: .23, wr: .34, loss: { feature: 5, incumbent: 2, price: 1.5, timing: 1, security: .5 }, win: { acc: 2, dep: 3, val: 2, sup: 1.5, int: 1, cha: 1.5 } },
  qua: { n: 'Quarry Labs', w: .17, wr: .56, loss: { price: 2, feature: 2, timing: 1.5, security: 1, incumbent: .5 }, win: { acc: 3, dep: 1.5, int: 2.5, sup: 1.5, cha: 1, val: 1 } },
  non: { n: 'No competitor', w: .3, wr: .45, loss: { nodec: 6, timing: 2.5, price: 1, security: 1 }, win: { cha: 3, val: 2, dep: 2, acc: 2, sup: 1, int: 1 } }
};
const WIN = { acc: 'Detection accuracy', dep: 'Time to deploy', sup: 'Support and onboarding', int: 'Integrations', cha: 'Strong champion', val: 'Price and packaging' };
const LOSS = { price: 'Price', feature: 'Missing capability', incumbent: 'Incumbent relationship', timing: 'Timing or budget', nodec: 'No decision', security: 'Failed security review' };
const REPS = ['Priya Natarajan', 'Colm Brennan', 'Adaora Eze', 'Mateus Rocha', 'Hollis Grant', 'Sanne de Vries'];
const A1 = ['Alder', 'Brookfield', 'Calder', 'Dovetail', 'Everly', 'Fenwick', 'Garnet', 'Hearth', 'Inlet', 'Kestrel', 'Larkin', 'Meridian', 'Norland', 'Oriel', 'Pellham', 'Quinlan', 'Rowan', 'Selby', 'Thornbury', 'Vantor', 'Westcombe', 'Yardley'];
const A2 = ['Health', 'Bank', 'Insurance', 'Logistics', 'Retail', 'Labs', 'Energy', 'Media', 'Legal', 'Manufacturing', 'School District', 'Credit Union', 'Biotech', 'Hotels'];
const used = new Set();
const acct = () => { let n; do n = A1[Math.floor(R() * A1.length)] + ' ' + A2[Math.floor(R() * A2.length)]; while (used.has(n)); used.add(n); return n; };
const D = Array.from({ length: 152 }, (_, i) => {
  const seg = pickW(Object.fromEntries(Object.entries(SEG).map(([k, v]) => [k, v.w]))), comp = pickW(Object.fromEntries(Object.entries(COMP).map(([k, v]) => [k, v.w])));
  const q = Math.floor(R() * 4), S0 = SEG[seg], C = COMP[comp];
  const amt = clamp(Math.round(Math.exp(Math.log(S0.med) + S0.sd * gauss() * 1.6) * 2) / 2, 6, 950);
  const won = R() < C.wr + S0.adj + (q - 1.5) * .035;
  const why = won ? pickW(C.win) : pickW(C.loss);
  const cyc = Math.round(S0.cyc * (.6 + R() * .8) * (won ? 1 : why === 'nodec' ? 1.45 : 1.12));
  const disc = won ? Math.round(({ smb: 4 + R() * 8, mid: 7 + R() * 12, ent: 11 + R() * 17 })[seg] * 10) / 10 : null;
  return { i, a: acct(), seg, comp, q, amt, won, why, cyc, disc, rep: REPS[Math.floor(R() * REPS.length)] };
});

/* ------------------------------------------------------------------ state */
const S = { q: 4, seg: 'all', comp: 'all', reason: null, peek: null, view: 'swarm', sort: { k: 'deals', dir: -1 }, h2h: 'bas', focus: -1 };
const inPeriod = d => d.q >= 4 - S.q;
const inSeg = d => S.seg === 'all' || d.seg === S.seg;
const vis = () => D.filter(d => inPeriod(d) && inSeg(d) && (S.comp === 'all' || d.comp === S.comp));
const matches = (d, r) => !r || (r.o === 'won' ? d.won : !d.won) && d.why === r.k;
const median = a => { if (!a.length) return 0; const s = a.slice().sort((x, y) => x - y), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

/* ------------------------------------------------------------------ tooltip */
const tip = $('.dbc-winloss__tip');
function showTip(html, x, y) {
  tip.innerHTML = html; tip.classList.add('on');
  const b = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let l = x - b.left + 14, t = y - b.top - h - 12;
  if (l + w > b.width - 8) l = x - b.left - w - 14;
  if (t < 8) t = y - b.top + 16;
  tip.style.translate = Math.round(clamp(l, 8, b.width - w - 8)) + 'px ' + Math.round(clamp(t, 8, b.height - h - 8)) + 'px';
}
const hideTip = () => tip.classList.remove('on');
const dealTip = d => `<b>${esc(d.a)}</b><span class="o ${d.won ? 'won' : 'lost'}">${d.won ? 'Won' : 'Lost'} · ${km(d.amt)}</span>
  <span>Reason<em>${d.won ? WIN[d.why] : LOSS[d.why]}</em></span><span>Against<em>${COMP[d.comp].n}</em></span>
  <span>Segment<em>${SEG[d.seg].n}</em></span><span>Cycle<em>${d.cyc} days</em></span>${d.won ? `<span>Discount<em>${d.disc}%</em></span>` : ''}<span>Rep · quarter<em>${d.rep.split(' ')[0]} · ${QS[d.q]}</em></span>`;

/* ------------------------------------------------------------------ filters */
$('[data-g="comp"]').innerHTML = `<button type="button" data-v="all" aria-pressed="true">Any competitor</button>` + Object.entries(COMP).map(([k, c]) => `<button type="button" data-v="${k}" aria-pressed="false">${c.n}</button>`).join('');
$$('.dbc-winloss__chips').forEach(g => g.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  S[g.dataset.g] = b.dataset.v; syncChips(); update();
}));
function syncChips() {
  $$('.dbc-winloss__chips').forEach(g => $$('button', g).forEach(b => b.setAttribute('aria-pressed', b.dataset.v === S[g.dataset.g])));
  $$('.dbc-winloss__period [role="radio"]').forEach(b => { const on = +b.dataset.q === S.q; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; });
}
$('.dbc-winloss__period').addEventListener('click', e => { const b = e.target.closest('[data-q]'); if (b) { S.q = +b.dataset.q; syncChips(); update(); } });
$('.dbc-winloss__period').addEventListener('keydown', e => {
  const d = { ArrowRight: 1, ArrowLeft: -1 }[e.key]; if (!d) return;
  const all = $$('.dbc-winloss__period [role="radio"]'), i = all.findIndex(b => +b.dataset.q === S.q), n = all[clamp(i + d, 0, all.length - 1)];
  e.preventDefault(); S.q = +n.dataset.q; syncChips(); update(); n.focus();
});
$('.dbc-winloss__count').addEventListener('click', e => { if (e.target.closest('[data-clear]')) { S.seg = 'all'; S.comp = 'all'; S.q = 4; S.reason = null; syncChips(); update(); } });

/* ------------------------------------------------------------------ KPIs */
const kpis = $('.dbc-winloss__kpis');
kpis.innerHTML = ['Win rate', 'Won value', 'Win rate by value', 'Sales cycle', 'Discount on wins'].map((t, i) => `<div style="--i:${i}"><dt>${t}</dt><dd data-k="${i}"></dd></div>`).join('');
function renderKpis(list) {
  const w = list.filter(d => d.won), l = list.filter(d => !d.won), wv = w.reduce((s, d) => s + d.amt, 0), lv = l.reduce((s, d) => s + d.amt, 0);
  const avg = a => a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0;
  const ent = w.filter(d => d.seg === 'ent');
  const k = $$('dd', kpis);
  k[0].innerHTML = list.length ? `<span class="w">${pc(w.length / list.length)}</span><small>${w.length} won · ${l.length} lost</small>` : '—';
  k[1].innerHTML = `${km(wv)}<small>of ${km(wv + lv)}</small>`;
  k[2].innerHTML = wv + lv ? `${pc(wv / (wv + lv))}<small>${wv / (wv + lv) < w.length / Math.max(1, list.length) ? 'big deals slip away' : 'we win the big ones'}</small>` : '—';
  k[3].innerHTML = `${Math.round(avg(w.map(d => d.cyc)))}d<small>won · lost ${Math.round(avg(l.map(d => d.cyc)))}d</small>`;
  k[4].innerHTML = w.length ? `${avg(w.map(d => d.disc)).toFixed(1)}%<small>${ent.length ? 'Enterprise ' + avg(ent.map(d => d.disc)).toFixed(1) + '%' : 'no enterprise wins'}</small>` : '—';
  const n = list.length, filtered = S.seg !== 'all' || S.comp !== 'all' || S.q !== 4 || S.reason;
  $('.dbc-winloss__count').innerHTML = `<b>${n}</b> of ${D.length} closed deals${filtered ? '<button type="button" data-clear>Clear filters</button>' : ''}`;
}

/* ------------------------------------------------------------------ beeswarm: wins packed upward, losses downward, on a log axis */
const plot = $('.dbc-winloss__plot'), svg = $('.dbc-winloss__svg');
const NS = 'http://www.w3.org/2000/svg';
let G = null, DOTS = [], ORDER = [];
const LO = 5, HI = 1000, TICKS = [10, 25, 50, 100, 250, 500, 1000];
function layoutSwarm() {
  const w = plot.clientWidth, h = plot.clientHeight;
  if (w < 60 || h < 80) return false;
  G = { w, h, ml: 12, mr: 12, mt: 8, mb: 22 };
  G.iw = w - G.ml - G.mr; G.mid = G.mt + (h - G.mt - G.mb) / 2; G.half = (h - G.mt - G.mb) / 2;
