    transition: background-color .2s, color .2s, box-shadow .2s;
    &:hover { background: var(--dbc-territory-soft); color: var(--dbc-territory-ink); }
    &[aria-selected=true] { background: var(--dbc-territory-card); color: var(--dbc-territory-ink); font-weight: 650; box-shadow: 0 1px 0 var(--dbc-territory-line), 0 6px 16px -10px color-mix(in oklch, var(--dbc-territory-ink) 40%, transparent); }
    &[aria-selected=true] .dbc-territory__ic { color: var(--dbc-territory-accent); }
    & em { margin-left: auto; font-style: normal; font-size: 11px; font-weight: 650; padding: 0 7px; border-radius: 99px; background: var(--dbc-territory-soft); color: var(--dbc-territory-mute); }
    & em:empty { display: none; }
  }
}
.dbc-territory__cap { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-territory-faint); }
.dbc-territory__rules {
  margin-top: 18px; padding: 0 8px; display: grid; gap: 8px;
  & ul { display: grid; gap: 7px; font-size: 12px; color: var(--dbc-territory-mute); text-wrap: pretty; }
  & li { position: relative; padding-left: 14px; }
  & li::before { content: ""; position: absolute; left: 1px; top: .5em; width: 6px; height: 6px; rotate: 30deg; clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%); background: var(--dbc-territory-faint); }
  & b { color: var(--dbc-territory-ink); font-weight: 650; }
}
.dbc-territory__keys {
  margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbc-territory-line); display: grid; gap: 6px; font-size: 11.5px; color: var(--dbc-territory-mute);
  & p { display: flex; flex-wrap: wrap; align-items: center; gap: 3px; }
}
.dbc-territory__reset {
  justify-self: start; margin-top: 6px; padding: 6px 10px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dbc-territory-ink);
  box-shadow: inset 0 0 0 1px var(--dbc-territory-line); background: var(--dbc-territory-card); transition: box-shadow .2s, background-color .2s;
  &:hover { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-territory-ink) 30%, transparent); }
}

/* main */
.dbc-territory__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 14px; padding: 16px 18px 16px; }
.dbc-territory__head {
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px;
  & h2 { font-size: clamp(20px, 2.5cqi, 29px); font-weight: 800; letter-spacing: -.04em; line-height: 1.02; text-wrap: balance; }
}
.dbc-territory__eyebrow { font-size: 11.5px; font-weight: 600; color: var(--dbc-territory-mute); margin-bottom: 5px; font-variant-numeric: tabular-nums; }
.dbc-territory__acts { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.dbc-territory__seg {
  display: inline-flex; padding: 2px; border-radius: 10px; background: var(--dbc-territory-soft); box-shadow: inset 0 0 0 1px var(--dbc-territory-line);
  & [role=radio] { padding: 5px 11px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dbc-territory-mute); transition: background-color .2s, color .2s, box-shadow .2s; white-space: nowrap; }
  & [role=radio]:hover { color: var(--dbc-territory-ink); }
  & [role=radio][aria-checked=true] { background: var(--dbc-territory-card); color: var(--dbc-territory-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbc-territory-ink) 20%, transparent); }
}
.dbc-territory__switch {
  display: inline-flex; align-items: center; gap: 7px; padding: 5px 10px 5px 6px; border-radius: 10px; font-size: 12px; font-weight: 600; color: var(--dbc-territory-mute); cursor: pointer; user-select: none;
  box-shadow: inset 0 0 0 1px var(--dbc-territory-line); transition: color .2s, background-color .2s;
  & input { appearance: none; margin: 0; width: 28px; height: 16px; border-radius: 99px; background: color-mix(in oklch, var(--dbc-territory-ink) 18%, transparent); position: relative; cursor: pointer; transition: background-color .25s; }
  & input::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--dbc-territory-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbc-territory-ink) 30%, transparent); transition: translate .35s var(--dbc-territory-spring); }
  & input:checked { background: var(--dbc-territory-ink); }
  & input:checked::after { translate: 12px 0; }
  &:has(input:checked) { color: var(--dbc-territory-ink); }
  &:has(input:focus-visible) { outline: 2px solid var(--dbc-territory-accent); outline-offset: 2px; }
  & input:focus-visible { outline: none; }
}
.dbc-territory__btn {
  display: inline-flex; align-items: center; gap: 6px; height: 31px; padding: 0 12px 0 10px; border-radius: 10px; font-size: 12.5px; font-weight: 650; white-space: nowrap;
  background: var(--dbc-territory-card); box-shadow: inset 0 0 0 1px var(--dbc-territory-line); transition: background-color .2s, box-shadow .2s, opacity .2s, scale .25s var(--dbc-territory-out);
  & .dbc-territory__ic { width: 16px; height: 16px; }
  &:hover:not(:disabled) { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-territory-ink) 32%, transparent); }
  &:active:not(:disabled) { scale: .96; }
  &:disabled { opacity: .45; cursor: default; }
}
.dbc-territory__go {
  background: var(--dbc-territory-ink); color: var(--dbc-territory-paper); box-shadow: none;
  & .dbc-territory__ic { color: var(--dbc-territory-r2); }
  &:hover:not(:disabled) { box-shadow: 0 6px 16px -8px color-mix(in oklch, var(--dbc-territory-ink) 70%, transparent); }
  &[aria-pressed=true] { background: var(--dbc-territory-over); }
  &[aria-pressed=true] .dbc-territory__ic { color: var(--dbc-territory-paper); animation: dbc-territory-spin 1.2s linear infinite; }
}
@keyframes dbc-territory-spin { to { rotate: 1turn; } }

.dbc-territory__view { min-height: 0; min-width: 0; }
.dbc-territory__view[hidden] { display: none; }
.dbc-territory__body { height: 100%; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 300px; grid-template-areas: "map panel"; gap: 12px; }

/* map */
.dbc-territory__map {
  grid-area: map; position: relative; min-height: 0; min-width: 0; border-radius: 16px; overflow: hidden;
  background:
    radial-gradient(circle at 1px 1px, color-mix(in oklch, var(--dbc-territory-water) 55%, transparent) 1px, transparent 1.5px) 0 0 / 14px 14px,
    color-mix(in oklch, var(--dbc-territory-water) 22%, var(--dbc-territory-card));
  box-shadow: inset 0 0 0 1px var(--dbc-territory-line);
}
.dbc-territory__svg { position: absolute; inset: 0; width: 100%; height: 100%; cursor: cell; touch-action: none; outline: none; }
.dbc-territory__map:has(.dbc-territory__svg:focus-visible) { box-shadow: inset 0 0 0 2px var(--dbc-territory-accent); }
.dbc-territory__halo { fill: none; stroke: color-mix(in oklch, var(--dbc-territory-water) 80%, var(--dbc-territory-accent)); stroke-width: 7; stroke-linejoin: round; stroke-linecap: round; opacity: .42; }
.dbc-territory__lake { fill: color-mix(in oklch, var(--dbc-territory-water) 75%, var(--dbc-territory-card)); stroke: color-mix(in oklch, var(--dbc-territory-water) 75%, var(--dbc-territory-card)); stroke-width: 1; }
.dbc-territory__hex {
  fill: color-mix(in oklab, var(--c) var(--m), var(--dbc-territory-card));
  stroke: var(--dbc-territory-card); stroke-width: 1; stroke-opacity: .85;
  transform-box: fill-box; transform-origin: center;
  transition: fill .45s var(--dbc-territory-out), opacity .3s;
  &.is-dim { opacity: .28; }
}
.dbc-territory__coast { fill: none; stroke: var(--dbc-territory-ink); stroke-width: 1.3; stroke-linecap: round; opacity: .7; }
.dbc-territory__bounds { fill: none; stroke: var(--dbc-territory-ink); stroke-width: 2.3; stroke-linecap: round; }
.dbc-territory__fy { fill: none; stroke: var(--dbc-territory-ink); stroke-width: 1.5; stroke-linecap: round; stroke-dasharray: .5 4.5; opacity: 0; transition: opacity .35s; }
.dbc-territory__mv { opacity: 0; transition: opacity .35s; & circle { fill: var(--dbc-territory-ink); } }
.dbc-territory:has([data-fy26]:checked) {
  & .dbc-territory__fy { opacity: .85; }
  & .dbc-territory__mv { opacity: .75; }
}
.dbc-territory__city {
  pointer-events: none;
  & rect { fill: var(--dbc-territory-card); stroke: var(--dbc-territory-ink); stroke-width: 1.4; }
  & text { font: 650 10.5px var(--dbc-territory-sans); letter-spacing: .01em; fill: var(--dbc-territory-ink); paint-order: stroke; stroke: color-mix(in oklch, var(--dbc-territory-card) 85%, transparent); stroke-width: 3.2; stroke-linejoin: round; }
}
.dbc-territory__tag {
  pointer-events: none; transition: transform .7s var(--dbc-territory-spring), opacity .3s;
  & circle { fill: var(--c); stroke: var(--dbc-territory-card); stroke-width: 2; }
  & .ini { font: 760 9.5px var(--dbc-territory-sans); fill: white; text-anchor: middle; dominant-baseline: central; letter-spacing: .02em; }
  & rect { fill: var(--dbc-territory-ink); }
  & .pc { font: 650 9.5px var(--dbc-territory-mono); fill: var(--dbc-territory-paper); text-anchor: middle; dominant-baseline: central; font-variant-numeric: tabular-nums; }
  &.is-over rect { fill: var(--dbc-territory-over); }
  &.is-under rect { fill: color-mix(in oklch, var(--dbc-territory-under) 85%, var(--dbc-territory-ink)); }
  &.is-gone { opacity: 0; }
}
.dbc-territory__hov { fill: none; stroke: var(--paint, var(--dbc-territory-ink)); stroke-width: 2.6; stroke-linejoin: round; pointer-events: none; opacity: 0; transition: opacity .12s; &.is-on { opacity: 1; } }
.dbc-territory__cur { fill: none; stroke: var(--dbc-territory-accent); stroke-width: 2.4; stroke-dasharray: 4 3; stroke-linejoin: round; pointer-events: none; opacity: 0; }
.dbc-territory__svg:focus-visible .dbc-territory__cur { opacity: 1; }
.dbc-territory__ring { fill: none; stroke: var(--c); stroke-width: 2.2; pointer-events: none; transform-box: fill-box; transform-origin: center; }
.dbc-territory__svg.is-enter {
  & .dbc-territory__hex, & .dbc-territory__lake { animation: dbc-territory-pop .75s var(--dbc-territory-spring) backwards; animation-delay: calc(var(--i) * 6ms); }
  & .dbc-territory__bounds, & .dbc-territory__coast, & .dbc-territory__halo { animation: dbc-territory-fade .6s var(--dbc-territory-out) .65s backwards; }
  & .dbc-territory__city, & .dbc-territory__tags { animation: dbc-territory-drop .6s var(--dbc-territory-out) .85s backwards; }
}
@keyframes dbc-territory-pop { from { opacity: 0; transform: scale(.35); } }
@keyframes dbc-territory-fade { from { opacity: 0; } }
@keyframes dbc-territory-drop { from { opacity: 0; transform: translateY(-6px); } }
.dbc-territory__legend {
  position: absolute; left: 12px; bottom: 10px; display: grid; grid-template-columns: auto 72px; grid-template-rows: auto auto; column-gap: 8px; align-items: center;
  padding: 6px 9px; border-radius: 9px; background: color-mix(in oklch, var(--dbc-territory-card) 88%, transparent); box-shadow: inset 0 0 0 1px var(--dbc-territory-line);
  font-size: 10.5px; color: var(--dbc-territory-mute); pointer-events: none;
  & span:first-child { grid-row: 1 / 3; font-weight: 650; color: var(--dbc-territory-ink); }
  & i { height: 7px; border-radius: 2px; background: linear-gradient(90deg, color-mix(in oklch, var(--dbc-territory-ink) 22%, var(--dbc-territory-card)), var(--dbc-territory-ink)); }
  & span:nth-of-type(2), & span:nth-of-type(3) { grid-row: 2; font-size: 9.5px; }
  & span:nth-of-type(2) { grid-column: 2; justify-self: start; }
  & span:nth-of-type(3) { grid-column: 2; justify-self: end; }
}

/* panel */
.dbc-territory__panel { grid-area: panel; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 14px; border-radius: 16px; background: var(--dbc-territory-card); box-shadow: inset 0 0 0 1px var(--dbc-territory-line); }
.dbc-territory__score { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 14px; align-items: center; padding-bottom: 10px; border-bottom: 1px solid var(--dbc-territory-line); }
.dbc-territory__dial {
  --dbc-territory-score: 0;
  --g: var(--dbc-territory-ink);
  position: relative; width: 96px; aspect-ratio: 1; display: grid; place-content: center; text-align: center;
  transition: --dbc-territory-score 1.2s var(--dbc-territory-out);
  &::before, &::after { content: ""; position: absolute; inset: 0; border-radius: 50%; }
  &::before {
    background: conic-gradient(from -135deg, var(--g) calc(var(--dbc-territory-score) * 2.7deg), var(--dbc-territory-line) 0 270deg, transparent 0);
    mask: radial-gradient(farthest-side, transparent calc(100% - 9px), #000 calc(100% - 8.5px));
  }
  /* tick at 90 = ready */
  &::after { background: conic-gradient(from calc(-135deg + 243deg - 1deg), var(--dbc-territory-ok) 0 2deg, transparent 0); mask: radial-gradient(farthest-side, transparent calc(100% - 13px), #000 calc(100% - 12.5px)); }
  & b { font-size: 29px; font-weight: 820; letter-spacing: -.05em; line-height: 1; }
  & small { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-territory-faint); }
  &.is-ready { --g: var(--dbc-territory-ok); }
}
.dbc-territory__facts {
  display: grid; gap: 7px;
  & div { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
  & dt { font-size: 11.5px; color: var(--dbc-territory-mute); }
  & dd { font-size: 13px; font-weight: 700; }
}
.dbc-territory__reps { display: grid; gap: 3px; }
.dbc-territory__rep {
  --c: var(--dbc-territory-r1);
  position: relative; display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; grid-template-areas: "k nm v" "k bar bar"; column-gap: 9px; row-gap: 5px; align-items: center;
  padding: 5px 8px 6px; border-radius: 10px; transition: background-color .2s, box-shadow .2s;
  &:hover { background: var(--dbc-territory-soft); }
  &[aria-checked=true] { background: color-mix(in oklab, var(--c) 11%, var(--dbc-territory-card)); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--c) 70%, transparent); }
  & .k { grid-area: k; align-self: start; margin-top: 1px; width: 22px; height: 22px; border-radius: 6px; display: grid; place-items: center; font: 700 11px var(--dbc-territory-mono); color: white; background: var(--c); clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%); }
  & .nm { grid-area: nm; min-width: 0; line-height: 1.2; }
  & .nm b { display: block; font-size: 12.5px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .nm small { font-size: 11px; color: var(--dbc-territory-mute); font-variant-numeric: tabular-nums; }
  & .v { grid-area: v; text-align: right; line-height: 1.2; font-variant-numeric: tabular-nums; }
  & .v b { display: block; font: 650 12.5px var(--dbc-territory-mono); }
  & .v em { font-style: normal; font: 650 11px var(--dbc-territory-mono); }
  & .is-over { color: var(--dbc-territory-over); } & .is-under { color: color-mix(in oklch, var(--dbc-territory-under) 80%, var(--dbc-territory-ink)); } & .is-ok { color: var(--dbc-territory-ok); }
  & .bar { grid-area: bar; position: relative; height: 6px; border-radius: 3px; background: var(--dbc-territory-soft); }
  & .band { position: absolute; top: -3px; bottom: -3px; left: calc(0.9 / 1.8 * 100%); width: calc(0.2 / 1.8 * 100%); border-radius: 2px; background: color-mix(in oklch, var(--dbc-territory-ok) 16%, transparent); }
  & .fill { position: absolute; inset: 0; border-radius: 3px; background: var(--c); transform-origin: 0 50%; transform: scaleX(var(--s, 0)); transition: transform .8s var(--dbc-territory-spring); }
  & .tgt { position: absolute; top: -4px; bottom: -4px; left: calc(1 / 1.8 * 100%); width: 1.5px; translate: -50% 0; background: var(--dbc-territory-ink); opacity: .6; }
}
.dbc-territory__reps.is-enter .dbc-territory__rep { animation: dbc-territory-rise .6s var(--dbc-territory-out) backwards; animation-delay: calc(var(--i) * 55ms + 150ms); }
@keyframes dbc-territory-rise { from { opacity: 0; transform: translateY(8px); } }
.dbc-territory__warn {
  margin-top: auto; display: grid; gap: 6px; padding-top: 10px; border-top: 1px solid var(--dbc-territory-line); font-size: 12px; text-wrap: pretty;
  & li { display: grid; grid-template-columns: 16px minmax(0, 1fr); gap: 7px; align-items: start; }
  & li svg { width: 16px; height: 16px; fill: none; stroke: var(--dbc-territory-over); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & li.is-split svg { stroke: var(--dbc-territory-under); }
  & li.is-good svg { stroke: var(--dbc-territory-ok); }
  & li { animation: dbc-territory-fade .35s var(--dbc-territory-out) backwards; }
  & b { font-weight: 650; }
}

/* districts */
.dbc-territory__view[data-view=list]:not([hidden]) { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; }
.dbc-territory__lbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; }
.dbc-territory__sel select {
  height: 31px; padding: 0 28px 0 10px; border: 0; border-radius: 10px; font-size: 12.5px; font-weight: 600; cursor: pointer;
  background: var(--dbc-territory-card); box-shadow: inset 0 0 0 1px var(--dbc-territory-line);
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--dbc-territory-mute) 50%), linear-gradient(-45deg, transparent 50%, var(--dbc-territory-mute) 50%);
  background-position: right 14px top 14px, right 10px top 14px; background-size: 4px 4px; background-repeat: no-repeat;
}
.dbc-territory__count { margin-left: auto; font-size: 12px; color: var(--dbc-territory-mute); }
.dbc-territory__tw { min-height: 0; border-radius: 16px; background: var(--dbc-territory-card); box-shadow: inset 0 0 0 1px var(--dbc-territory-line); }
.dbc-territory__tbl {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th, & td { padding: 0 12px; height: 40px; text-align: left; white-space: nowrap; border-bottom: 1px solid var(--dbc-territory-soft); }
  & thead th { position: sticky; top: 0; z-index: 1; height: 36px; background: var(--dbc-territory-card); border-bottom: 1px solid var(--dbc-territory-line); font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-territory-faint); }
  & thead button { display: inline-flex; align-items: center; gap: 4px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; }
  & thead button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; border-top-color: currentColor; translate: 0 2px; opacity: 0; transition: opacity .2s, rotate .25s var(--dbc-territory-out); }
  & th[aria-sort=ascending] button::after { opacity: 1; rotate: 180deg; translate: 0 -2px; }
  & th[aria-sort=descending] button::after { opacity: 1; }
  & th[aria-sort=ascending], & th[aria-sort=descending] { color: var(--dbc-territory-ink); }
  & .is-r { text-align: right; } & .is-r button { flex-direction: row-reverse; }
  & tbody th { font-weight: 400; }
  & tbody th b { font: 650 12px var(--dbc-territory-mono); margin-right: 8px; }
  & tbody th small { font-size: 12px; color: var(--dbc-territory-mute); }
  & td.is-r { font-family: var(--dbc-territory-mono); font-size: 12px; font-variant-numeric: tabular-nums; }
  & tbody tr { transition: background-color .2s; }
  & tbody tr:hover { background: var(--dbc-territory-soft); }
  & tbody tr.is-moved th b { color: var(--dbc-territory-accent); }
  & tbody tr.is-moved .dbc-territory__was { text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--dbc-territory-ink) 40%, transparent); }
  & .sw { display: inline-block; width: 9px; height: 9px; margin-right: 7px; border-radius: 2px; background: var(--c); vertical-align: 0; transition: background-color .3s; }
  & select { border: 0; padding: 4px 22px 4px 6px; margin-left: -6px; border-radius: 7px; font-size: 12.5px; font-weight: 600; background: transparent; cursor: pointer; appearance: none;
    background-image: linear-gradient(45deg, transparent 50%, var(--dbc-territory-faint) 50%), linear-gradient(-45deg, transparent 50%, var(--dbc-territory-faint) 50%);
    background-position: right 11px top 50%, right 7px top 50%; background-size: 4px 4px; background-repeat: no-repeat; }
  & select:hover { background-color: var(--dbc-territory-soft); }
  & .dbc-territory__was { color: var(--dbc-territory-mute); }
  & .loc { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: var(--dbc-territory-faint); transition: color .2s, background-color .2s; }
  & .loc:hover { color: var(--dbc-territory-accent); background: var(--dbc-territory-tint); }
  & .loc svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}
@supports (animation-timeline: scroll()) {
  .dbc-territory__tbl thead th { animation: dbc-territory-shade linear both; animation-timeline: scroll(nearest block); animation-range: 0 40px; }
}
@keyframes dbc-territory-shade { to { box-shadow: 0 10px 14px -12px color-mix(in oklch, var(--dbc-territory-ink) 45%, transparent); } }

.dbc-territory__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; width: max-content; max-width: 240px; padding: 9px 11px; border-radius: 10px; font-size: 12px; line-height: 1.4;
  background: var(--dbc-territory-ink); color: var(--dbc-territory-paper); box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--dbc-territory-ink) 70%, transparent);
  opacity: 0; scale: .96; transform-origin: 0 100%; transition: opacity .14s, scale .2s var(--dbc-territory-out);
  &[data-on] { opacity: 1; scale: 1; }
  & b { display: block; font-weight: 700; }
  & .row { display: flex; justify-content: space-between; gap: 14px; color: color-mix(in oklch, var(--dbc-territory-paper) 72%, transparent); font-variant-numeric: tabular-nums; }
  & .row strong { color: var(--dbc-territory-paper); font-weight: 650; }
  & i { display: inline-block; width: 8px; height: 8px; margin-right: 5px; border-radius: 2px; background: var(--c); }
}

@container dbc-territory (max-width: 979px) {
  .dbc-territory__shell { grid-template-columns: 60px minmax(0, 1fr); }
  .dbc-territory__side { align-items: center; padding: 16px 8px; }
  .dbc-territory__lbl { display: none; }
  .dbc-territory__brand { padding: 0 0 14px; }
  .dbc-territory__tabs [role=tab] { width: 44px; height: 40px; justify-content: center; padding: 0; }
  .dbc-territory__body { grid-template-columns: minmax(0, 1fr) 262px; }
