@property --dbc-renewal-grr { syntax: '<number>'; inherits: true; initial-value: 0; }
.dbc-renewal {
  /* re-theme with these five */
  --dbc-renewal-bg: oklch(0.205 0.016 258);
  --dbc-renewal-ink: oklch(0.95 0.008 250);
  --dbc-renewal-good: oklch(0.79 0.15 152);
  --dbc-renewal-warn: oklch(0.85 0.14 84);
  --dbc-renewal-risk: oklch(0.7 0.19 27);
  /* derived */
  --dbc-renewal-accent: var(--dbc-renewal-ink);
  --dbc-renewal-panel: color-mix(in oklch, var(--dbc-renewal-bg) 93%, var(--dbc-renewal-ink));
  --dbc-renewal-raise: color-mix(in oklch, var(--dbc-renewal-bg) 86%, var(--dbc-renewal-ink));
  --dbc-renewal-side: color-mix(in oklch, var(--dbc-renewal-bg) 80%, black);
  --dbc-renewal-line: color-mix(in oklch, var(--dbc-renewal-ink) 11%, transparent);
  --dbc-renewal-soft: color-mix(in oklch, var(--dbc-renewal-ink) 6%, transparent);
  --dbc-renewal-mute: color-mix(in oklch, var(--dbc-renewal-ink) 64%, var(--dbc-renewal-bg));
  --dbc-renewal-faint: color-mix(in oklch, var(--dbc-renewal-ink) 42%, var(--dbc-renewal-bg));
  --dbc-renewal-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbc-renewal-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbc-renewal-out: cubic-bezier(.16, 1, .3, 1);
  --dbc-renewal-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 25.3%, 0.849 31.5%, 0.937 38.1%, 0.968 41.8%, 0.991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  width: 100%;
  height: var(--dbc-renewal-h, 680px);
  container-type: inline-size;
  container-name: dbc-renewal;
  position: relative; isolation: isolate; overflow: hidden; overflow: clip;
  border-radius: 18px;
  background: var(--dbc-renewal-bg);
  color: var(--dbc-renewal-ink);
  font: 13px/1.45 var(--dbc-renewal-sans);
  accent-color: var(--dbc-renewal-ink);
  color-scheme: dark;
  box-shadow: inset 0 0 0 1px var(--dbc-renewal-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h1, h2, h3, h4, p, dl, dd, ul, ol, figure, table, fieldset) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(input, select, textarea) { font: inherit; color: inherit; }
  & :where(svg) { display: block; overflow: visible; }
  & :focus-visible { outline: 2px solid var(--dbc-renewal-accent); outline-offset: 2px; border-radius: 6px; }
  & :where(.dbc-renewal__scroll) { overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbc-renewal-ink) 22%, transparent) transparent; }
  & .dbc-renewal__num { font-variant-numeric: tabular-nums; }
  & .dbc-renewal__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  & .is-good { --t: var(--dbc-renewal-good); }
  & .is-warn { --t: var(--dbc-renewal-warn); }
  & .is-risk { --t: var(--dbc-renewal-risk); }
}
.dbc-renewal__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbc-renewal__shell { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-areas: "side main"; }

/* side */
.dbc-renewal__side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 18px 12px 16px; background: var(--dbc-renewal-side); border-right: 1px solid var(--dbc-renewal-line); }
.dbc-renewal__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 16px;
  & svg { width: 30px; height: 30px; flex: none; padding: 5px; border-radius: 9px; background: var(--dbc-renewal-good); fill: none; stroke: var(--dbc-renewal-bg); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbc-renewal-mute); }
}
.dbc-renewal__tabs {
  display: grid; gap: 2px;
  & [role=tab] {
    display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; color: var(--dbc-renewal-mute); font-weight: 560;
    transition: background-color .2s, color .2s;
    &:hover { background: var(--dbc-renewal-soft); color: var(--dbc-renewal-ink); }
    &[aria-selected=true] { background: var(--dbc-renewal-raise); color: var(--dbc-renewal-ink); font-weight: 650; box-shadow: inset 0 0 0 1px var(--dbc-renewal-line); }
  }
}
.dbc-renewal__cap { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbc-renewal-faint); & span { text-transform: none; letter-spacing: 0; font-weight: 500; } }
.dbc-renewal__book {
  margin-top: auto; padding: 14px 8px 0; border-top: 1px solid var(--dbc-renewal-line); display: grid; gap: 10px;
  & dl { display: grid; gap: 6px; }
  & dl div { display: flex; justify-content: space-between; gap: 8px; font-size: 12px; }
  & dt { color: var(--dbc-renewal-mute); }
  & dd { font-weight: 650; }
}
.dbc-renewal__fine { font-size: 11px; color: var(--dbc-renewal-faint); text-wrap: pretty; }

/* main */
.dbc-renewal__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 12px; padding: 16px 18px 16px; }
.dbc-renewal__head {
  display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 16px;
  & h2 { font-size: clamp(20px, 2.6cqi, 30px); font-weight: 780; letter-spacing: -.04em; line-height: 1; text-wrap: balance; }
}
.dbc-renewal__eyebrow { font: 600 10.5px/1.3 var(--dbc-renewal-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--dbc-renewal-faint); margin-bottom: 6px; }
.dbc-renewal__filters { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.dbc-renewal__seg {
  display: inline-flex; padding: 2px; border-radius: 10px; background: var(--dbc-renewal-soft); box-shadow: inset 0 0 0 1px var(--dbc-renewal-line);
  & [role=radio] { padding: 5px 10px; border-radius: 8px; font-size: 12px; font-weight: 600; color: var(--dbc-renewal-mute); white-space: nowrap; transition: background-color .2s, color .2s; }
  & [role=radio]:hover { color: var(--dbc-renewal-ink); }
  & [role=radio][aria-checked=true] { background: var(--dbc-renewal-ink); color: var(--dbc-renewal-bg); }
}
.dbc-renewal__sel select {
  height: 30px; padding: 0 28px 0 10px; border: 0; border-radius: 10px; font-size: 12px; font-weight: 600; cursor: pointer; appearance: none;
  background: var(--dbc-renewal-soft); box-shadow: inset 0 0 0 1px var(--dbc-renewal-line);
  background-image: linear-gradient(45deg, transparent 50%, var(--dbc-renewal-mute) 50%), linear-gradient(-45deg, transparent 50%, var(--dbc-renewal-mute) 50%);
  background-position: right 14px top 13px, right 10px top 13px; background-size: 4px 4px; background-repeat: no-repeat;
  & option { background: var(--dbc-renewal-panel); color: var(--dbc-renewal-ink); }
}
.dbc-renewal__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; border-radius: 14px; background: var(--dbc-renewal-panel); box-shadow: inset 0 0 0 1px var(--dbc-renewal-line);
  & > div { min-width: 0; padding: 10px 16px 11px; display: grid; gap: 2px; align-content: start; }
  & > div + div { border-left: 1px solid var(--dbc-renewal-line); }
  & dt { font-size: 11px; font-weight: 600; color: var(--dbc-renewal-mute); }
  & dd { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 720; letter-spacing: -.035em; line-height: 1.15; }
  & dd.is-risk { color: var(--dbc-renewal-risk); } & dd.is-good { color: var(--dbc-renewal-good); }
  & .dbc-renewal__grr dd { display: flex; align-items: center; gap: 12px; }
  & small { display: block; min-width: 0; font-size: 11.5px; color: var(--dbc-renewal-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dbc-renewal__bullet {
  --dbc-renewal-grr: 70;
  position: relative; flex: none; width: clamp(36px, 6cqi, 64px); height: 6px; border-radius: 3px; background: var(--dbc-renewal-soft); overflow: visible;
  transition: --dbc-renewal-grr 1.1s var(--dbc-renewal-out);
  & i { position: absolute; inset: 0; border-radius: 3px; background: linear-gradient(90deg, var(--dbc-renewal-risk), var(--dbc-renewal-warn) 50%, var(--dbc-renewal-good)); clip-path: inset(0 calc(100% - (var(--dbc-renewal-grr) - 70) / 30 * 100%) 0 0 round 3px); }
  & b { position: absolute; top: -3px; bottom: -3px; left: calc(20 / 30 * 100%); width: 2px; translate: -1px 0; border-radius: 1px; background: var(--dbc-renewal-ink); }
}

.dbc-renewal__body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 268px; grid-template-areas: "views model"; gap: 12px; }
.dbc-renewal__views { grid-area: views; min-height: 0; min-width: 0; border-radius: 14px; background: var(--dbc-renewal-panel); box-shadow: inset 0 0 0 1px var(--dbc-renewal-line); overflow: hidden; }
.dbc-renewal__view { height: 100%; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dbc-renewal__view[hidden] { display: none; }
.dbc-renewal__ph {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 14px; padding: 11px 14px 9px; border-bottom: 1px solid var(--dbc-renewal-line);
  & h3 { font-size: 12.5px; font-weight: 650; text-wrap: balance; }
}
.dbc-renewal__legend {
  display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11px; color: var(--dbc-renewal-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 9px; height: 9px; border-radius: 2px; background: var(--t); }
  & i.is-exp { width: 14px; height: 0; border-radius: 0; border-top: 2px solid var(--dbc-renewal-ink); }
}
.dbc-renewal__plot { position: relative; min-height: 0; }
.dbc-renewal__plot svg { position: absolute; inset: 0; width: 100%; height: 100%; outline: none; }
.dbc-renewal__plot:has(svg:focus-visible) { box-shadow: inset 0 0 0 2px var(--dbc-renewal-ink); border-radius: 0 0 14px 14px; }
.dbc-renewal__gl { stroke: var(--dbc-renewal-line); }
.dbc-renewal__ax { fill: var(--dbc-renewal-faint); font: 10px var(--dbc-renewal-mono); font-variant-numeric: tabular-nums; }
.dbc-renewal__ax.is-yr { fill: var(--dbc-renewal-mute); font-weight: 650; }
.dbc-renewal__colbg { fill: var(--dbc-renewal-ink); opacity: 0; transition: opacity .15s; &.is-on { opacity: .045; } }
.dbc-renewal__col { transition: opacity .35s; &.is-off { opacity: 0; pointer-events: none; } }
.dbc-renewal__blk {
  fill: color-mix(in oklab, var(--t) 80%, var(--dbc-renewal-panel)); stroke: var(--dbc-renewal-panel); stroke-width: 1; cursor: pointer;
  transition: transform .75s var(--dbc-renewal-spring), fill .45s, opacity .3s;
  &:hover { fill: var(--t); }
  &.is-out { opacity: 0; pointer-events: none; }
  &.is-played { stroke: var(--dbc-renewal-ink); stroke-dasharray: 2 2; }
  &.is-sel { fill: var(--t); stroke: var(--dbc-renewal-ink); stroke-width: 2; stroke-dasharray: none; }
  &.is-kb { stroke: var(--dbc-renewal-ink); stroke-width: 2; stroke-dasharray: 3 2; }
}
.dbc-renewal__exp { stroke: var(--dbc-renewal-ink); stroke-width: 2; stroke-linecap: round; transition: transform .75s var(--dbc-renewal-spring), opacity .3s; pointer-events: none; }
.dbc-renewal__tot { fill: var(--dbc-renewal-mute); font: 600 10px var(--dbc-renewal-mono); text-anchor: middle; font-variant-numeric: tabular-nums; transition: transform .75s var(--dbc-renewal-spring), opacity .3s; pointer-events: none; }
.dbc-renewal__plot svg.is-enter .dbc-renewal__col { animation: dbc-renewal-rise .9s var(--dbc-renewal-out) backwards; animation-delay: calc(var(--i) * 55ms); }
@keyframes dbc-renewal-rise { from { opacity: 0; clip-path: inset(100% 0 0 0); transform: translateY(10px); } }

/* matrix */
.dbc-renewal__band { opacity: .07; fill: var(--t); }
.dbc-renewal__cut { stroke: var(--dbc-renewal-ink); stroke-dasharray: 3 4; opacity: .35; }
.dbc-renewal__qlbl { fill: var(--dbc-renewal-faint); font: 700 10px var(--dbc-renewal-sans); letter-spacing: .1em; text-transform: uppercase; }
.dbc-renewal__qlbl.is-hot { fill: var(--dbc-renewal-risk); }
.dbc-renewal__dot {
  fill: color-mix(in oklch, var(--t) 34%, transparent); stroke: var(--t); stroke-width: 1.4; cursor: pointer;
  transition: transform .8s var(--dbc-renewal-spring), fill .4s, stroke .4s, opacity .3s;
  &:hover, &.is-sel { fill: color-mix(in oklch, var(--t) 70%, transparent); }
  &.is-sel { stroke: var(--dbc-renewal-ink); stroke-width: 2; }
  &.is-kb { stroke: var(--dbc-renewal-ink); stroke-width: 2; stroke-dasharray: 3 2; }
  &.is-out { opacity: 0; pointer-events: none; }
}
.dbc-renewal__plot svg.is-enter .dbc-renewal__dot { animation: dbc-renewal-pop .7s var(--dbc-renewal-spring) backwards; animation-delay: calc(var(--i) * 14ms); }
@keyframes dbc-renewal-pop { from { opacity: 0; scale: .2; } }
.dbc-renewal__dot { transform-box: fill-box; transform-origin: center; }
.dbc-renewal__cross { stroke: var(--dbc-renewal-ink); stroke-dasharray: 2 3; opacity: 0; pointer-events: none; transition: opacity .12s; &.is-on { opacity: .55; } }
.dbc-renewal__pill { pointer-events: none; opacity: 0; transition: opacity .12s; &.is-on { opacity: 1; } & rect { fill: var(--dbc-renewal-ink); } & text { fill: var(--dbc-renewal-bg); font: 650 10px var(--dbc-renewal-mono); text-anchor: middle; dominant-baseline: central; } }

/* table */
.dbc-renewal__chips {
  display: flex; flex-wrap: wrap; gap: 6px;
  & [role=radio] { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--dbc-renewal-mute); box-shadow: inset 0 0 0 1px var(--dbc-renewal-line); transition: background-color .2s, color .2s; }
  & [role=radio]:hover { color: var(--dbc-renewal-ink); }
  & [role=radio][aria-checked=true] { background: var(--dbc-renewal-raise); color: var(--dbc-renewal-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-renewal-ink) 25%, transparent); }
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--t); }
  & em { font-style: normal; font: 600 11px var(--dbc-renewal-mono); color: var(--dbc-renewal-faint); }
}
.dbc-renewal__tw { min-height: 0; }
.dbc-renewal__tbl {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th, & td { padding: 0 11px; height: 46px; text-align: left; white-space: nowrap; border-bottom: 1px solid var(--dbc-renewal-soft); }
  & thead th { position: sticky; top: 0; z-index: 1; height: 34px; background: var(--dbc-renewal-panel); border-bottom: 1px solid var(--dbc-renewal-line); font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dbc-renewal-faint); }
  & thead button { display: inline-flex; align-items: center; gap: 4px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; }
  & thead button::after { content: ""; border: 4px solid transparent; border-top-color: currentColor; translate: 0 2px; opacity: 0; transition: opacity .2s, rotate .25s var(--dbc-renewal-out); }
  & th[aria-sort=ascending] button::after { opacity: 1; rotate: 180deg; translate: 0 -2px; }
  & th[aria-sort=descending] button::after { opacity: 1; }
  & th[aria-sort=ascending], & th[aria-sort=descending] { color: var(--dbc-renewal-ink); }
  & .is-r { text-align: right; } & .is-r button { flex-direction: row-reverse; }
  & td.is-r, & .dt { font: 12px var(--dbc-renewal-mono); font-variant-numeric: tabular-nums; }
  & tbody tr { transition: background-color .2s; }
  & tbody tr:hover { background: var(--dbc-renewal-soft); }
  & tbody tr.is-sel { background: var(--dbc-renewal-raise); }
  & .nm { display: grid; text-align: left; line-height: 1.25; }
  & .nm b { font-weight: 650; max-width: 200px; overflow: hidden; text-overflow: ellipsis; }
  & .ar { display: grid; line-height: 1.2; } & .ar b { font-weight: 650; } & .ar small { font-size: 10.5px; color: var(--dbc-renewal-faint); }
  & .nm small { font-size: 11px; color: var(--dbc-renewal-mute); }
  & .hl { display: inline-flex; align-items: center; gap: 10px; }
  & .hl b { width: 22px; font: 700 12.5px var(--dbc-renewal-mono); color: var(--t); text-align: right; }
  & .spark { display: inline-flex; align-items: end; gap: 2px; height: 18px; }
  & .spark i { width: 4px; height: calc(var(--v) * 1%); min-height: 2px; border-radius: 1px; background: color-mix(in oklch, var(--t) 80%, transparent); transition: height .5s var(--dbc-renewal-out); }
  & .risk { color: var(--dbc-renewal-risk); }
}
@supports (animation-timeline: view()) {
  .dbc-renewal__tbl tbody tr { animation: dbc-renewal-row linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}
@keyframes dbc-renewal-row { from { opacity: 0; transform: translateY(8px); } }

/* model */
.dbc-renewal__model { grid-area: model; min-height: 0; display: flex; flex-direction: column; gap: 12px; padding: 14px; border-radius: 14px; background: var(--dbc-renewal-panel); box-shadow: inset 0 0 0 1px var(--dbc-renewal-line); }
.dbc-renewal__mh { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; & h3 { font-size: 13px; font-weight: 700; } & small { display: block; margin-top: 2px; font-size: 11px; font-weight: 500; color: var(--dbc-renewal-mute); } & small b { color: var(--dbc-renewal-ink); font-weight: 650; } }
.dbc-renewal__link { font-size: 12px; font-weight: 600; color: var(--dbc-renewal-mute); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: var(--dbc-renewal-line); &:hover:not(:disabled) { color: var(--dbc-renewal-ink); } &:disabled { opacity: .4; cursor: default; text-decoration: none; } }
.dbc-renewal__presets { display: flex; & [role=radio] { flex: 1; padding: 5px 4px; text-align: center; font-size: 11.5px; } }
.dbc-renewal__weights { display: grid; gap: 5px; }
.dbc-renewal__w {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; row-gap: 2px; align-items: center;
  & label { font-size: 12px; font-weight: 600; }
  & output { font: 650 11.5px var(--dbc-renewal-mono); color: var(--dbc-renewal-mute); font-variant-numeric: tabular-nums; }
  & input { grid-column: 1 / -1; width: 100%; height: 18px; margin: 0; background: transparent; cursor: pointer; -webkit-appearance: none; appearance: none; }
  & input::-webkit-slider-runnable-track { height: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--dbc-renewal-ink) calc(var(--p) * 1%), var(--dbc-renewal-line) 0); }
  & input::-moz-range-track { height: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--dbc-renewal-ink) calc(var(--p) * 1%), var(--dbc-renewal-line) 0); }
  & input::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; margin-top: -5px; border-radius: 50%; background: var(--dbc-renewal-ink); box-shadow: 0 0 0 3px var(--dbc-renewal-panel); transition: scale .2s var(--dbc-renewal-out); }
  & input::-moz-range-thumb { width: 14px; height: 14px; border: 0; border-radius: 50%; background: var(--dbc-renewal-ink); }
  & input:active::-webkit-slider-thumb { scale: 1.25; }
  & input:focus-visible { outline: none; }
  & input:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 3px var(--dbc-renewal-panel), 0 0 0 5px var(--dbc-renewal-ink); }
  &:has(input:active) output { color: var(--dbc-renewal-ink); }
}
.dbc-renewal__cuts { font-size: 11.5px; color: var(--dbc-renewal-mute); & b { color: var(--dbc-renewal-ink); font-weight: 650; } }
.dbc-renewal__dist { margin-top: auto; padding-top: 12px; border-top: 1px solid var(--dbc-renewal-line); display: grid; gap: 10px; }
.dbc-renewal__distbar {
  display: flex; gap: 2px; height: 10px;
  & i { flex: var(--g, 1) 1 0; min-width: 0; border-radius: 2px; background: var(--t); transition: flex-grow .7s var(--dbc-renewal-out); }
}
.dbc-renewal__dist ul {
  display: grid; gap: 4px; font-size: 12px;
  & li { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto auto; gap: 8px; align-items: center; }
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--t); }
  & span { color: var(--dbc-renewal-mute); }
  & b { font: 650 12px var(--dbc-renewal-mono); font-variant-numeric: tabular-nums; text-align: right; }
  & em { font-style: normal; font: 11px var(--dbc-renewal-mono); color: var(--dbc-renewal-faint); min-width: 22px; text-align: right; }
}

/* drawer */
.dbc-renewal__drawer {
  position: absolute; z-index: 20; top: 8px; right: 8px; bottom: 8px; width: min(392px, calc(100% - 16px));
  display: flex; flex-direction: column; gap: 14px; padding: 16px 16px 18px; border-radius: 16px;
  background: var(--dbc-renewal-raise); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbc-renewal-ink) 16%, transparent), -24px 0 48px -20px black;
  translate: calc(100% + 16px) 0; visibility: hidden;
  transition: translate .55s var(--dbc-renewal-out), visibility 0s linear .55s;
  &.is-open { translate: 0 0; visibility: visible; transition: translate .55s var(--dbc-renewal-out), visibility 0s; }
}
.dbc-renewal__dh {
  display: flex; align-items: start; justify-content: space-between; gap: 10px;
  & h3 { font-size: 19px; font-weight: 750; letter-spacing: -.025em; line-height: 1.15; text-wrap: balance; }
}
.dbc-renewal__x { flex: none; width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; color: var(--dbc-renewal-mute); transition: background-color .2s, color .2s; &:hover { background: var(--dbc-renewal-soft); color: var(--dbc-renewal-ink); } & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; } }
.dbc-renewal__dk {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-radius: 12px; background: var(--dbc-renewal-soft); box-shadow: inset 0 0 0 1px var(--dbc-renewal-line);
  & div { padding: 8px 10px; min-width: 0; }
  & div + div { border-left: 1px solid var(--dbc-renewal-line); }
  & dt { font-size: 10.5px; color: var(--dbc-renewal-mute); }
  & dd { font-size: 15px; font-weight: 700; letter-spacing: -.02em; white-space: nowrap; }
  & dd.is-t { color: var(--t); }
}
.dbc-renewal__build { display: grid; gap: 10px; }
.dbc-renewal__stack {
  position: relative; display: flex; gap: 2px; height: 12px; border-radius: 3px; background: var(--dbc-renewal-soft);
  & i { flex: none; width: calc(var(--w) * 1%); border-radius: 2px; background: var(--t); transition: width .6s var(--dbc-renewal-out), background-color .4s; }
  &::after { content: ""; position: absolute; top: -4px; bottom: -4px; left: 50%; border-left: 1.5px dashed var(--dbc-renewal-faint); }
  &::before { content: ""; position: absolute; top: -4px; bottom: -4px; left: 70%; border-left: 1.5px dashed var(--dbc-renewal-faint); }
}
.dbc-renewal__sigs {
  display: grid; gap: 2px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) 70px 58px; gap: 4px 10px; align-items: center; padding: 5px 0; border-bottom: 1px solid var(--dbc-renewal-soft); }
  & .n { min-width: 0; line-height: 1.25; }
  & .n b { display: block; font-size: 12px; font-weight: 650; }
  & .n small { display: block; font-size: 11px; color: var(--dbc-renewal-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .bar { position: relative; height: 5px; border-radius: 3px; background: var(--dbc-renewal-soft); }
  & .bar i { position: absolute; inset: 0; border-radius: 3px; background: var(--t); transform-origin: 0 50%; transform: scaleX(calc(var(--v) / 100)); transition: transform .6s var(--dbc-renewal-spring), background-color .4s; }
  & .c { font: 650 11.5px var(--dbc-renewal-mono); text-align: right; font-variant-numeric: tabular-nums; }
  & .c small { display: block; font-size: 9.5px; font-weight: 500; color: var(--dbc-renewal-faint); white-space: nowrap; }
  & li.is-bumped .n small { color: var(--dbc-renewal-good); }
}
.dbc-renewal__pg { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 8px; }
.dbc-renewal__play {
  display: grid; gap: 2px; padding: 9px 10px; border-radius: 11px; text-align: left; box-shadow: inset 0 0 0 1px var(--dbc-renewal-line); transition: background-color .2s, box-shadow .2s, scale .25s var(--dbc-renewal-out);
  & b { font-size: 12px; font-weight: 650; display: flex; align-items: center; gap: 6px; }
