  BLK.forEach((b, i) => b.classList.toggle('is-sel', i === S.sel));
  DOTS.forEach((d, i) => d.classList.toggle('is-sel', i === S.sel));
  TRS.forEach(tr => tr.classList.toggle('is-sel', +tr.dataset.a === S.sel));
}
$('[data-act=close]', drawer).addEventListener('click', closeDrawer);
function renderDrawer(fresh) {
  const a = ACC[S.sel]; if (!a) return;
  drawer.setAttribute('aria-label', a.n);
  $('[data-d=meta]', drawer).textContent = SEGN[a.seg] + ' · ' + CSMS[a.csm] + ' · renews ' + dfmt(a, true);
  $('[data-d=name]', drawer).textContent = a.n;
  $('[data-d=arr]', drawer).textContent = kfmt(a.arr);
  const scEl = $('[data-d=sc]', drawer);
  scEl.className = 'dbc-renewal__num is-t is-' + a.tier;
  if (fresh) scEl._v = null;
  countTo(scEl, a.sc, v => String(Math.round(v)));
  $('[data-d=p]', drawer).textContent = Math.round(a.p * 100) + '%';
  $('[data-d=exp]', drawer).textContent = kfmt(a.exp);
  const tot = S.w.reduce((s, x) => s + x, 0) || 1, ss = sigScores(a.e), base = sigScores(eff(a, new Set()));
  const stack = $('.dbc-renewal__stack', drawer);
  if (stack.children.length !== SIG.length) stack.innerHTML = SIG.map(() => '<i></i>').join('');
  [...stack.children].forEach((el, k) => { el.style.setProperty('--w', (S.w[k] / tot * ss[k]).toFixed(2)); el.className = 'is-' + tierOf(ss[k]); el.title = SIG[k].n + ': ' + (S.w[k] / tot * ss[k]).toFixed(1) + ' points'; });
  const ul = $('.dbc-renewal__sigs', drawer);
  if (ul.children.length !== SIG.length) ul.innerHTML = SIG.map(s => '<li><span class="n"><b>' + s.n + '</b><small></small></span><span class="bar"><i></i></span><span class="c"></span></li>').join('');
  [...ul.children].forEach((li, k) => {
    $('small', li).textContent = SIG[k].f(a.e);
    li.classList.toggle('is-bumped', ss[k] > base[k] + 0.5);
    const bar = $('.bar i', li); bar.style.setProperty('--v', ss[k].toFixed(1)); bar.className = 'is-' + tierOf(ss[k]);
    $('.c', li).innerHTML = (S.w[k] / tot * ss[k]).toFixed(1) + '<small>' + Math.round(ss[k]) + ' × ' + Math.round(S.w[k] / tot * 100) + '%</small>';
  });
  const pg = $('.dbc-renewal__pg', drawer);
  if (pg.children.length !== PLAYS.length) pg.innerHTML = PLAYS.map(p => '<button type="button" class="dbc-renewal__play" data-play="' + p.k + '" aria-pressed="false"><b>' + p.n + '</b><small>' + p.d + '</small><em></em></button>').join('');
  [...pg.children].forEach((b, k) => {
    const p = PLAYS[k], has = a.plays.has(p.k);
    const without = new Set(a.plays); without.delete(p.k);
    const avail = has || p.on(eff(a, without));
    b.disabled = !avail;
    b.setAttribute('aria-pressed', has ? 'true' : 'false');
    const alt = new Set(a.plays); if (has) alt.delete(p.k); else alt.add(p.k);
    const delta = has ? a.exp - evalA(a, alt).exp : evalA(a, alt).exp - a.exp;
    const em = $('em', b);
    em.textContent = avail ? (delta >= 0 ? '+' : '−') + kfmt(Math.abs(delta)) + (has ? ' · planned' : ' expected') : 'Nothing to fix';
    em.classList.toggle('is-neg', delta < 0 && avail);
  });
}
$('.dbc-renewal__pg', drawer).addEventListener('click', e => {
  const b = e.target.closest('[data-play]'); if (!b || b.disabled || !ACC[S.sel]) return;
  const a = ACC[S.sel], k = b.dataset.play, before = a.exp, tierB = a.tier;
  if (a.plays.has(k)) a.plays.delete(k); else a.plays.add(k);
  update();
  const d = a.exp - before;
  say(PLAYS.find(p => p.k === k).n + (a.plays.has(k) ? ' planned' : ' removed') + ' for ' + a.n + '. Health ' + Math.round(a.sc) + (a.tier !== tierB ? ', now ' + TIERN[a.tier] : '') + '. Expected ARR ' + (d >= 0 ? 'up ' : 'down ') + kfmt(Math.abs(d)) + '.');
});

/* ------------------------------------------------------------------ wiring */
function update() {
  compute(); renderKpis(); renderWeights(); renderDist();
  if (S.view === 'runway') drawRunway(); else if (S.view === 'matrix') drawMatrix(); else renderTable();
  if (S.sel >= 0) renderDrawer(false);
}
$$('.dbc-renewal__seg[data-f], .dbc-renewal__chips').forEach(g => radioGroup(g, v => {
  const f = g.dataset.f;
  if (f === 'win') S.win = +v; else if (f === 'seg') S.seg = v; else if (f === 'tier') { S.tier = v; renderTable(); return; }
  else if (f === 'preset') { S.w = PRESETS[v].slice(); }
  S.kbR = { m: Math.min(S.kbR.m, S.win - 1), k: 0 };
  update();
  if (f === 'preset') say(g.querySelector('[data-v=' + v + ']').textContent + ' weighting. ' + ACC.filter(inWin).filter(a => a.tier === 'risk').length + ' accounts at risk.');
}));
$('[data-csm]').addEventListener('change', e => { S.csm = +e.target.value; update(); });
tabs($('.dbc-renewal__tabs'), v => {
  S.view = v; hideTip(tip);
  $$('.dbc-renewal__view').forEach(s => { s.hidden = s.dataset.view !== v; });
  update();
});
root.addEventListener('keydown', e => { if (e.key === 'Escape') { if (!closeDrawer()) hideTip(tip); } });
onResize(plotR, () => { if (S.view === 'runway') drawRunway(); });
onResize(plotM, () => { if (S.view === 'matrix') drawMatrix(); });

/* boot */
compute(); renderWeights(); renderDist(); renderTable();
if (!RM) { svgR.classList.add('is-enter'); svgM.classList.add('is-enter'); setTimeout(() => { if (!root.isConnected) return; svgR.classList.remove('is-enter'); svgM.classList.remove('is-enter'); }, 2400); }
drawRunway();
requestAnimationFrame(() => { if (!root.isConnected) return; renderKpis(); });
